window.PHY_LESSONS=[{"chapter_number":0,"chapter_title":"🧮 الفصل التمهيدي: أساسيات الرياضيات","lesson_number":1,"lesson_title":"🔟 الدرس 1: التدوين العلمي","order_index":1,"hook":"شحنة الإلكترون = 0.00000000000000000016 كولوم! هل تتخيل كتابة هذا في كل مسألة؟ الفيزيائيون اخترعوا طريقة ذكية تختصره إلى 16×10⁻²⁰ — هذا هو التدوين العلمي.","concepts":[{"term":"رقم بسيط × 10 مرفوعة لأس","text":"بدل ما نكتب رقماً طويلاً مليئاً بالأصفار، نكتبه على شكل: . والأس يخبرنا كم خانة نحرّك الفاصلة.\n150000 = 15 × 10⁴ بدل ما نعدّ 4 أصفار كل مرة، نكتب 10⁴ وخلص 👍\n0.0006 = 6 × 10⁻⁴ العدد صغير جداً ← الأس سالب (الفاصلة تمشي لليسار)","ministerial":false},{"term":"التدوين العلمي","text":"هو كتابة أي عدد على الصورة a × 10ⁿ حيث:\na عدد طبيعي بدون فاصلة عشرية، وبدون أصفار زائدة في نهايته.\nn عدد صحيح (موجب أو سالب) يمثل عدد الخانات التي حرّكنا بها الفاصلة.\n10 هو الأساس دائماً في الفيزياء.","ministerial":false}],"laws":[{"name":"قاعدة إشارة الأس في التدوين العلمي","formula":"كبير ⟵ أس موجب | صغير ⟶ أس سالب","variables_note":""}],"notes":[{"heading":"القاعدة الذهبية — إلى أي جهة تتحرك الفاصلة؟","items":["🔺 عدد كبير (أكبر من 1): نحذف كل الأصفار في نهاية العدد فيبقى عدد طبيعي a، والأس يكون موجباً بعدد الأصفار المحذوفة.","🔻 عدد صغير (كسر عشري أصغر من 1): نحرّك الفاصلة إلى اليمين حتى تختفي تماماً فيتكوّن عدد طبيعي a من كل أرقامه المعنوية، والأس يكون سالباً بعدد الخطوات."],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال ١: اكتب العدد 96000 بالتدوين العلمي.","givens":"العدد كبير (أكبر من 1) ← نتوقع أساً موجباً.","solution_steps":["الخطوة ١: نحذف الأصفار الموجودة في نهاية العدد فيبقى العدد الطبيعي a: 96","الخطوة ٢: نعدّ كم صفراً حذفناه من نهاية العدد: 96 0 0 0 → حذفنا 3 أصفار","الخطوة ٣: العدد كبير ← الأس موجب = عدد الأصفار المحذوفة: 96000 = 96 × 10³"],"ministerial":false},{"problem":"مثال ٢: اكتب العدد 0.00045 بالتدوين العلمي.","givens":"العدد صغير (أصغر من 1) ← نتوقع أساً سالباً.","solution_steps":["الخطوة ١: نحرّك الفاصلة يميناً حتى تختفي تماماً، فيتكوّن العدد الطبيعي a من كل الأرقام المعنوية: 0.00045 → 45","الخطوة ٢: نعدّ خطوات التحريك: 0.0 0 0 4 5 = 5 خطوات","الخطوة ٣: العدد صغير ← الأس سالب: 0.00045 = 45 × 10⁻⁵"],"ministerial":false},{"problem":"مثال ٣ (العكس): اكتب العدد 2×10⁶ بصورته العادية.","givens":"الأس موجب (+6) ← العدد كبير، نحرّك الفاصلة يميناً 6 خانات.","solution_steps":["الخطوة ١: نبدأ من 2. ونضيف أصفاراً بعدد الأس: 2 × 10⁶ = 2 000 000","الخطوة ٢: النتيجة = مليونان."],"ministerial":false},{"problem":"مثال ٤ (العكس): اكتب العدد 7×10⁻³ بصورته العادية.","givens":"الأس سالب (−3) ← العدد صغير، نحرّك الفاصلة يساراً 3 خانات.","solution_steps":["الخطوة ١: نبدأ من 7 ونحرّك الفاصلة 3 خانات لليسار (نضيف أصفاراً): 7 × 10⁻³ = 0.007"],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"🧪 المحوّل: من عدد عادي إلى تدوين علمي"},{"chapter_number":0,"chapter_title":"🧮 الفصل التمهيدي: أساسيات الرياضيات","lesson_number":2,"lesson_title":"✖️ الدرس 2: ضرب وقسمة قوى العشرة","order_index":2,"hook":"في قانون كولوم تحسب 9×10⁹ × 4×10⁻⁶ × 9×10⁻⁶ ÷ (0.06)² ... كل هذا يعتمد على مهارة واحدة: جمع وطرح الأسس.","concepts":[{"term":"عدد مرّات تكرار العدد 10 في الضرب","text":"تذكّر معنى الأس: هو ببساطة .\n10³ = 10 × 10 × 10\n(ثلاث عشرات مضروبة ببعض)\nالحين شوف شنو يصير لمّا نضرب 10³ × 10² ونفتحها على طولها:\n(10×10×10) × (10×10) = 10×10×10×10×10 = 10⁵ عدّينا كل العشرات مع بعض: 3 + 2 = 5 عشرات. فبدل ما نفتحها كل مرة، نجمع الأسس وبس! 😎","ministerial":false},{"term":"القاعدة العامة","text":"📌 (نفس الفكرة بأي رقمين مهما كانا): عند الضرب نجمع 10ᵃ × 10ᵇ = 10ᵃ⁺ᵇ ، وعند القسمة نطرح 10ᵃ ÷ 10ᵇ = 10ᵃ⁻ᵇ.","ministerial":false},{"term":"قاعدة إضافية مفيدة:","text":"💡 10⁰ = 1 دائماً، و 1/10ⁿ = 10⁻ⁿ (نقل القوة من المقام للبسط يقلب إشارة الأس).","ministerial":false}],"laws":[{"name":"✖️ ضرب؟ اجمع الأسس","formula":"10³ × 10² = 10⁵","variables_note":"لأن 3 + 2 = 5"},{"name":"➗ قسمة؟ اطرح الأسس","formula":"10⁵ ÷ 10² = 10³","variables_note":"لأن 5 − 2 = 3"}],"notes":[{"heading":"انتبه للإشارات! (أهم نقطة)","items":["الجمع مع أرقام سالبة: 10⁻⁶ × 10⁻⁶ = 10^(−6−6) = 10⁻¹²","الطرح يقلب إشارة الأس السفلي: 10⁹ ÷ 10⁻⁴ = 10^(9−(−4)) = 10¹³","الأرقام العادية (المعاملات) تُضرب أو تُقسم بشكل منفصل عن القوى."],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال ١: احسب 10⁵ × 10³","givens":"","solution_steps":["الخطوة ١: عملية ضرب ← نجمع الأسّين: 5 + 3 = 8","الخطوة ٢: النتيجة: 10⁵ × 10³ = 10⁸"],"ministerial":false},{"problem":"مثال ٢: احسب (4×10⁻⁶) × (9×10⁻⁶) — كما في قانون كولوم!","givens":"","solution_steps":["الخطوة ١: نضرب المعاملات (الأرقام العادية) معاً: 4 × 9 = 36","الخطوة ٢: نجمع أسس القوى: 10⁻⁶ × 10⁻⁶ = 10^(−6−6) = 10⁻¹²","الخطوة ٣: نجمع النتيجتين: = 36 × 10⁻¹²"],"ministerial":false},{"problem":"مثال ٣: احسب 36×10⁻¹² ÷ 36×10⁻⁴","givens":"","solution_steps":["الخطوة ١: نقسم المعاملات: 36 ÷ 36 = 1","الخطوة ٢: نطرح الأسس (انتبه: طرح سالب): 10⁻¹² ÷ 10⁻⁴ = 10^(−12−(−4)) = 10^(−12+4) = 10⁻⁸","الخطوة ٣: النتيجة: = 1 × 10⁻⁸ = 10⁻⁸"],"ministerial":false},{"problem":"مثال ٤: احسب 9×10⁹ × 36×10⁻¹² ÷ (36×10⁻⁴) — خطوة كاملة من قانون كولوم!","givens":"نتعامل مع المعاملات معاً، والقوى معاً.","solution_steps":["الخطوة ١: المعاملات: 9 × 36 ÷ 36 = 9","الخطوة ٢: القوى (نجمع ثم نطرح): 10⁹ × 10⁻¹² ÷ 10⁻⁴ = 10^(9−12+4) = 10¹","الخطوة ٣: النتيجة النهائية: 9 × 10¹ = 90"],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"🧪 آلة الأسس: اضرب أو اقسم القوى"},{"chapter_number":0,"chapter_title":"🧮 الفصل التمهيدي: أساسيات الرياضيات","lesson_number":3,"lesson_title":"√ الدرس 3: الجذر التربيعي للقوى","order_index":3,"hook":"في مسائل كولوم كثيراً ما نصل إلى q² = 4×10⁻¹² ثم نحتاج إيجاد q نفسها. الحل؟ نأخذ الجذر التربيعي للطرفين.","concepts":[{"term":"السؤال المعكوس للتربيع","text":"الجذر التربيعي هو : أي عدد إذا ضربناه بنفسه يعطينا العدد الذي تحت الجذر؟\n√9 = 3 لأنّ 3 × 3 = 9\nوليش نأخذ نصف الأس؟ تذكّر من الدرس 2 أن الضرب يجمع الأسس:\n10³ × 10³ = 10⁶ ➜ √10⁶ = 10³ الجذر يبحث عن القوة التي إذا ضربناها بنفسها ترجّع الأصل. ونصف الأس 6 هو 3! 😎","ministerial":false},{"term":"القاعدة العامة:","text":"📌 √10ⁿ = 10^(n/2) — أي نقسم الأس على 2 (لهذا نحتاج الأس زوجياً).","ministerial":false},{"term":"الأس يجب أن يكون زوجياً","text":"⚠️ ليقبل القسمة على 2 بسهولة. إذا كان الأس فردياً، نعيد كتابة العدد ليصبح الأس زوجياً قبل أخذ الجذر (انظر المثال ٣).","ministerial":false}],"laws":[{"name":"جذر قوة العشرة = خُذ نصف الأس","formula":"√10⁶ = 10³","variables_note":"لأن 6 ÷ 2 = 3"}],"notes":[{"heading":"خطوات أخذ جذر عدد أسي مثل √a × 10ⁿ :","items":["١. نأخذ جذر المعامل a (مثل √4 = 2، √36 = 6، √9 = 3).","٢. نقسم الأس n على 2.","٣. نجمع النتيجتين."],"ministerial":false}],"tables":[{"caption":"","headers":["جذر تربيعي شائع","الناتج","لأن"],"rows":[["√4","2","2×2=4"],["√9","3","3×3=9"],["√16","4","4×4=16"],["√25","5","5×5=25"],["√36","6","6×6=36"],["√49","7","7×7=49"],["√64","8","8×8=64"],["√81","9","9×9=81"],["√100","10","10×10=100"]],"ministerial":false}],"examples":[{"problem":"مثال ١: احسب √10⁶","givens":"","solution_steps":["الخطوة ١: نقسم الأس على 2: 6 ÷ 2 = 3","الخطوة ٢: النتيجة: √10⁶ = 10³"],"ministerial":false},{"problem":"مثال ٢: احسب √4×10⁻¹² — إيجاد q من q²!","givens":"q² = 4×10⁻¹² ← المطلوب q","solution_steps":["الخطوة ١: جذر المعامل: √4 = 2","الخطوة ٢: نقسم الأس على 2: −12 ÷ 2 = −6","الخطوة ٣: نجمع النتيجتين: q = 2 × 10⁻⁶"],"ministerial":false},{"problem":"مثال ٣ (الأس فردي — الخدعة المهمة): احسب √40×10⁻¹³","givens":"الأس −13 فردي! لا يقبل القسمة على 2 بسهولة.","solution_steps":["الخطوة ١: نعيد الكتابة لجعل الأس زوجياً (نأخذ 10 من المعامل): 40×10⁻¹³ = 4×10⁻¹²","الخطوة ٢: الآن الأس زوجي — نأخذ الجذر: √4 = 2 و −12 ÷ 2 = −6","الخطوة ٣: النتيجة: √40×10⁻¹³ = 2 × 10⁻⁶"],"ministerial":false},{"problem":"مثال ٤: احسب √36×10⁻⁴ — إيجاد البعد r من r²!","givens":"r² = 36×10⁻⁴ ← المطلوب r","solution_steps":["الخطوة ١: جذر المعامل: √36 = 6","الخطوة ٢: نقسم الأس على 2: −4 ÷ 2 = −2","الخطوة ٣: النتيجة: r = 6 × 10⁻² m = 0.06 m"],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"🧪 حاسبة جذر القوى"},{"chapter_number":0,"chapter_title":"🧮 الفصل التمهيدي: أساسيات الرياضيات","lesson_number":4,"lesson_title":"⚖️ الدرس 4: إيجاد المجهول","order_index":4,"hook":"في الفيزياء لا تُعطى دائماً القيمة مباشرة! أحياناً تُعطى القوة ويُطلب البعد، أو تُعطى النتيجة ويُطلب الشحنة. المهارة هي ترتيب المعادلة لعزل المجهول.","concepts":[{"term":"ميزان متوازن","text":"المعادلة مثل : الطرفان متساويان. أي عملية تجريها على طرف يجب أن تجريها على الطرف الآخر ليبقى الميزان متوازناً.\nشوف بمثال بسيط: لو عندنا x + 3 = 7 ونريد نعرف x:\nx + 3 = 7 ⟸ ننقص 3 من الطرفين ⟹ x = 7 − 3 = 4 الرقم 3 كان مُضافاً، فلمّا «يعبر» للطرف الثاني يصير ناقصاً. هذا بالضبط معنى «نقل الحدود» 👇","ministerial":false}],"laws":[{"name":"مثال على الترتيب","formula":"F = K·q² / r² ⟵ننقل r²ونعزل q²⟶ q² = F·r² / K","variables_note":""}],"notes":[{"heading":"الطريقة السريعة — نقل الحدود:","items":["➕➖ الحد المُضاف ننقله للطرف الآخر بالطرح، والمطروح ننقله بالجمع (تنقلب إشارته).","✖️➗ العدد المضروب في المجهول ننقله للطرف الآخر بالقسمة.","➗✖️ العدد الذي يُقسم عليه المجهول ننقله بالضرب.","√ إذا وصلنا إلى «مجهول تربيعي» (مثل q²) نأخذ الجذر التربيعي للطرفين (راجع الدرس 3)."],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال ١: جِد قيمة x في 2x + 3 = 11","givens":"","solution_steps":["الخطوة ١: ننقل 3 للطرف الآخر بالطرح (تنقلب لسالب): 2x = 11 − 3 = 8","الخطوة ٢: ننقل 2 (المضروبة في x) بالقسمة: x = 8 ÷ 2 = 4","تحقّق: نعوّض x=4: 2(4) + 3 = 8 + 3 = 11 ✓"],"ministerial":false},{"problem":"مثال ٢: جِد قيمة x في x / 5 = 20","givens":"","solution_steps":["الخطوة ١: x مقسومة على 5 ← ننقل 5 بالضرب: x = 20 × 5 = 100"],"ministerial":false},{"problem":"مثال ٣ (من الفيزياء): من قانون كولوم F = K·q₁·q₂ / r²، اعزل r².","givens":"المطلوب: عزل r² في طرف لوحده.","solution_steps":["الخطوة ١: r² في المقام ← نضرب الطرفين في r² لرفعه للأعلى: F · r² = K·q₁·q₂","الخطوة ٢: ننقل F (المضروبة) بالقسمة: r² = K·q₁·q₂ / F","الخطوة ٣: لإيجاد r نأخذ الجذر التربيعي للطرفين: r = √K·q₁·q₂ / F"],"ministerial":false},{"problem":"مثال ٤ (تطبيق كامل): شحنتان متماثلتان، قوة التنافر بينهما 10N والبعد 6cm = 6×10⁻² m. جِد شحنة كل منهما.","givens":"F = 10N — r = 6×10⁻² m — q₁=q₂=q ← إذن q₁·q₂ = q²","solution_steps":["الخطوة ١: نرتّب القانون لعزل q²: q² = F·r² / K = (10 × (6×10⁻²)²) / (9×10⁹)","الخطوة ٢: نحسب (6×10⁻²)² = 36×10⁻⁴، والبسط: q² = (10 × 36×10⁻⁴) / (9×10⁹) = 360×10⁻⁴ / 9×10⁹","الخطوة ٣: المعاملات 360÷9=40، والأسس −4−9=−13: q² = 40×10⁻¹³ = 4×10⁻¹²","الخطوة ٤: نأخذ الجذر (الدرس 3): q = 2×10⁻⁶ C"],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"🧪 ميزان المعادلة: جِد قيمة x التي تُوازن الطرفين"},{"chapter_number":0,"chapter_title":"🧮 الفصل التمهيدي: أساسيات الرياضيات","lesson_number":5,"lesson_title":"📏 الدرس 5: تحويل البادئات والوحدات","order_index":5,"hook":"القاعدة الأولى قبل تطبيق أي قانون فيزيائي: وحّد الوحدات! البعد بالمتر، الشحنة بالكولوم. مسافة 6cm ليست 6 في القانون، بل 6×10⁻² m.","concepts":[{"term":"اسم مختصر لقوة من قوى العشرة","text":"كل بادئة (سنتي، مِلّي، مايكرو...) هي مجرّد . مثلاً «سنتي» تعني جزء من مئة = ×10⁻². فالتحويل = نستبدل البادئة بالقوة التي تقابلها.\n1 متر = 100 سنتيمتر لهذا 1 سم = جزء من مئة من المتر = 1 × 10⁻² m 📏","ministerial":false}],"laws":[],"notes":[{"heading":"القاعدة:","items":["من جزء صغير → الوحدة الأساسية (مثل cm → m): نضرب في القوة الموجودة في الجدول (أس سالب).","مثال: 1 cm = 1×10⁻² m · 1 μC = 1×10⁻⁶ C","💡 نفس البادئات تنطبق على كل الوحدات: المتر، الكولوم، الغرام... (سنتيمتر، سنتي كولوم، سنتي غرام)."],"ministerial":false}],"tables":[{"caption":"جدول البادئات — احفظه!","headers":["البادئة","الرمز","للتحويل إلى الوحدة الأساسية نضرب في"],"rows":[["كيلو (Kilo)","k","×10³"],["الوحدة الأساسية","m, C, g","×10⁰ = ×1"],["سنتي (Centi)","c","×10⁻²"],["مِلّي (Milli)","m","×10⁻³"],["مايكرو (Micro)","μ","×10⁻⁶"],["نانو (Nano)","n","×10⁻⁹"],["بيكو (Pico)","p","×10⁻¹²"]],"ministerial":false}],"examples":[{"problem":"مثال ١: حوّل 6 cm إلى متر.","givens":"","solution_steps":["الخطوة ١: من الجدول: سنتي = ×10⁻² 6 cm = 6 × 10⁻² m","الخطوة ٢: وبالصورة العادية: = 0.06 m"],"ministerial":false},{"problem":"مثال ٢: حوّل 30 cm إلى متر بالتدوين العلمي.","givens":"","solution_steps":["الخطوة ١: نطبّق البادئة: 30 cm = 30 × 10⁻² m","الخطوة ٢: نبسّطها للتدوين العلمي الصحيح (نحذف العامل المشترك 10 من a): 30 × 10⁻² = 3 × 10⁻¹ m = 0.3 m"],"ministerial":false},{"problem":"مثال ٣: حوّل 4 μC إلى كولوم.","givens":"","solution_steps":["الخطوة ١: مايكرو = ×10⁻⁶ (نفس البادئة تعمل مع الكولوم): 4 μC = 4 × 10⁻⁶ C"],"ministerial":false},{"problem":"مثال ٤: حوّل 2 km إلى متر.","givens":"","solution_steps":["الخطوة ١: كيلو = ×10³: 2 km = 2 × 10³ m = 2000 m"],"ministerial":false}],"qa":[],"has_simulation":true,"simulation_title":"🧪 محوّل الوحدات إلى المتر"},{"chapter_number":1,"chapter_title":"⚡ الفصل الأول: الكهربائية الساكنة","lesson_number":1,"lesson_title":"🎈 الدرس 1: ما الكهربائية الساكنة؟","order_index":1,"hook":"هل جربت يوماً دلك بالون بشعرك ثم لصقه بالجدار فبقي ملتصقاً؟ أو سمعت «طقطقة» عند خلع كنزة صوفية في الشتاء؟ كل هذا كهربائية ساكنة!","concepts":[{"term":"الكهربائية الساكنة:","text":"هي ظاهرة تجمع الشحنات الكهربائية على سطوح الأجسام حيث تكتسب هذهِ الأجسام شحنة من خلال ملامستها للأجسام الأخرى أو عن طريق التقارب الكبير بينها. ونحصل عليها بعدة طرق منها: ١. دلك ساق من المطاط بقطعة من الفرو ٢. دلك الشعر الجاف بالمشط.","ministerial":false}],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"وضح دور العلماء القدماء الذين ساهموا في اكتشاف الكهرباء؟","answer":"لقد وجد الحكيم الاغريقي أرسطو طاليس ٦٠٠ (ق.م) إن مادة الكهرب عند دلكها بقطعة من الصوف تصبح لها القابلية على جذب الاجسام الخفيفة مثل قصاصات الورق وقطع من القش. بعد ذلك وجد العالم الإنكليزي وليام كلبرت عام ١٦٠٠م ان الكثير من هذه المواد تشارك الكهرب في هذه الخاصية لذا يعتبر اول من أطلق عليها اسم الكهربائية.","ministerial":false},{"type":"سؤال","question":"ماذا يحصل عند دلك مادة الكهرب بقطعة من الصوف؟","answer":"تصير لها القابلية على جذب الأجسام الخفيفة مثل قصاصات الورق.","ministerial":false},{"type":"علل","question":"انجذاب قصاصات الورق الصغيرة اذا قربت منها مادة لدنة (بلاستيكية) كالمشط بعد دلكه بالشعر.","answer":"لأن المشط المدلوك يصير مشحوناً بالشحنات الكهربائية الساكنة (عندما يكون الشعر جافاً وبدون زيت).","ministerial":false},{"type":"علل","question":"إنجذاب القصاصات أو شعرك من بالون (نفاخة مملوءة بالهواء) بعد دلكه بقطعة من الصوف.","answer":"لان البالون المدلوك بالصوف سوف يشحن بالشحنات الكهربائية الساكنة لذلك سيجذب قصاصات الورق الصغيرة اليه.","ministerial":false},{"type":"علل","question":"التصاق البالون (النفاخة) بالجدار لعدة ساعات بعد دلكه بالصوف، إذا كان الجو جافاً.","answer":"لأن البالون سيصبح مشحوناً لذا يلتصق بالجدار وتطول فترة التصاقه كلما كان الجو جافاً لان الهواء الرطب يساعد على تفريغ الشحنات الكهربائية بسرعة.","ministerial":false},{"type":"علل","question":"ما سبب شعورنا عند السير على السجاد ومسك مقبض الباب المعدني، بصعقة كهربائية طفيفة؟","answer":"بسبب حدوث التفريغ الكهربائي للشحنات الكهربائية المكتسبة نتيجة الاحتكاك بين الجسم ومقبض الباب.","ministerial":true},{"type":"علل","question":"عند دلك مشط بلاستك بشعرك ثم قربته من ماء ينساب رفيعاً من الحنفية نلاحظ أن الماء ينجذب نحو المشط.","answer":"وذلك لأن المشط بعدما دلك بالشعر اكتسب شحنات كهربائية ساكنة مخالفة لشحنة الماء ونتيجة لهذا الإختلاف نلاحظ أنجذاب الماء نحو المشط.","ministerial":false},{"type":"علل","question":"عند تزحلق الأطفال في المتنزهات على لعبة التزحلق البلاستيكية وعند نزوله وملامسته بصورة مباشرة لمقبض معدني سوف يشعر الطفل بصعقة كهربائية؟","answer":"لأن عند تزحلق الطفل من أعلى اللعبة سوف تحتك ملابسه بأرضية اللعبة وبالتالي سيكتسب الطفل شحنات كهربائية ساكنة لذا عند ملامسته لمقبض معدني سوف يحصل تفريغ الشحنات التي اكتسبها أثناء عملية الاحتكاك.","ministerial":false},{"type":"سؤال","question":"هل يمكن شحن ساق من النحاس بالكهربائية الساكنة؟ وضح ذلك؟","answer":"نعم يمكن ذلك. حيث تدلك ساق النحاس بقطعة من الصوف او الفرو مثلاً حيث سيكتسب النحاس الالكترونات وبتالي ستكتسب شحنات سالبة وعند تقريبه من قصاصات ورقية صغيرة نلاحظ انجذابها نحو الساق دليل على انه تم شحنة بالكهربائية الساكنة.","ministerial":true},{"type":"سؤال","question":"هل تنجز الشحنات الكهربائية الساكنة شغلاً؟","answer":"كلا، لا تنجز شغلاً لأنها شحنات ساكنة وليست متحركة ضمن المادة.","ministerial":true}],"has_simulation":true,"simulation_title":"🧪 جرب بنفسك: المشط وقصاصات الورق"},{"chapter_number":1,"chapter_title":"⚡ الفصل الأول: الكهربائية الساكنة","lesson_number":2,"lesson_title":"⚛️ الدرس 2: الشحنة الكهربائية والذرة","order_index":2,"hook":"تتألف المادة من جسيمات صغيرة جداً تدعى الذرات. فما الذي يجعل جسماً «موجباً» وآخر «سالباً»؟ الجواب في الإلكترونات!","concepts":[],"laws":[],"notes":[{"heading":"📌 ملاحظات مهمة","items":["البروتون داخل نواة الذرة وشحنته موجبة ومقدارها يساوي مقدار شحنة الالكترون.","ان شحنة الإلكترون أو البروتون تعد أصغر وحدة قياس للشحنات.","أن شحنة أي جسم مشحون تساوي مضاعفات صحيحة لمقدار شحنة الالكترون: عدد الإلكترونات = شحنة الجسم ÷ شحنة الإلكترون","أوضحت التجارب ان مقدار شحنة الالكترون (1.6 × 10⁻¹⁹ C) والكولوم وحدة قياس الشحنات الكهربائية.","الكولوم الواحد (1C) يعادل شحنة كمية من الالكترونات عددها 6.25 × 10¹⁸ الكترون.","الكولوم وحدة كبيرة واجزائها الشائعة الاستعمال هي: المايكروكولوم 1μC = 10⁻⁶ C — والنانوكولوم 1nC = 10⁻⁹ C"],"ministerial":true},{"heading":"","items":["عند دلك ساق من المطاط بقطعة صوف أو فرو سوف تصبح شحنتهُ سالبة لأنهُ قد اكتسب الإلكترونات.","عند دلك ساق من الزجاج بقطعة من الحرير سوف تصبح شحنتهُ موجبة لأنهُ فقد الإلكترونات."],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال (خارجي): ما عدد الإلكترونات المفقودة لجسم متعادل الشحنة فقد شحنة مقدارها 4.8×10⁻¹¹ C ؟","givens":"المعطيات: شحنة الجسم المفقودة = 4.8×10⁻¹¹ C — شحنة الإلكترون = 1.6×10⁻¹⁹ C","solution_steps":["الخطوة ١: نكتب العلاقة: عدد الإلكترونات المفقودة = شحنة الجسم الفاقد ÷ شحنة الإلكترون","الخطوة ٢: نعوض: n = (4.8 × 10⁻¹¹) ÷ (1.6 × 10⁻¹⁹)","الخطوة ٣: نقسم الأعداد ونطرح الأسس: n = 3 × 10⁻¹¹⁺¹⁹ = 3 × 10⁸ electron ✨ إذن فقد الجسم 300 مليون إلكترون!"],"ministerial":false}],"qa":[{"type":"سؤال","question":"ما هي الذرة؟ وماهي مكوناتها؟","answer":"هي جسيمات صغيرة جدا مكونه للمادة وتحتوي الكترونات سالبة الشحنة تدور بسرعة عالية جدا حول نواة الذرة التي تحتوي بداخلها على بروتونات موجبة الشحنة ونيوترونات متعادلة الشحنة.","ministerial":false},{"type":"سؤال","question":"في معظم المواد تكون الذرة المتعادلة كهربائيا. ماذا نقصد بذلك؟ متى تكون الذرة متعادلة؟","answer":"أي ان الذرة يكون فيها عدد الكترونات مساوياً الى عدد بروتوناتها، ويكون صافي شحنته يساوي صفر.","ministerial":true},{"type":"سؤال","question":"كيف تفسر ظهور الشحنات الكهربائية الساكنة (السالبة والموجبة) على أسطح المواد؟ / متى يصير الجسم مشحون بشحنة موجبة ومتى يشحن بشحنة سالبة؟","answer":"١. عند فقدان الذرة عدد من الإلكترونات الخارجية بسبب مؤثر خارجي سوف يقل عدد الإلكترونات لذلك تصبح أيونا موجب فتظهر شحنة موجبة على الجسم.\n٢. عند اكتساب الذرة عدد من الإلكترونات الخارجية سوف يزداد عدد الإلكترونات لذلك تصبح ايونا سالب فتظهر شحنة سالبة على الجسم.","ministerial":true},{"type":"نشاط","question":"وضح بنشاط تبين فيه أن الشحنات المتشابهة تتنافر.","answer":"أدوات النشاط: ١- ساقان متماثلان من المطاط الصلب ٢- قطعة من الصوف أو الفرو ٣- خيط من القطن أو الحرير ٤- حاملان.\nالعمل: ١- نعلق ساقي المطاط بوضع افقي بخيطين بواسطة حاملان ونجعلهما متقاربين مع بعضهما. ٢- ندلكهما وعلى انفراد بقطعة الصوف ((سيشحنان بالشحنة السالبة)). ٣- نترك الساقين معلقين بحرية نلاحظ تنافرهما مع بعضهما.\nالإستنتاج: نستنتج من ذلك أن الشحنات المتشابهة تتنافر مع بعضها.","ministerial":false},{"type":"نشاط","question":"وضح بنشاط تبين فيه أن الشحنات المختلفة تتجاذب.","answer":"الأدوات: ١- ساق من المطاط وآخر من الزجاج ٢- قطعة من الصوف وأخرى من الحرير ٣- حاملان ٤- خيط من القطن أو الحرير.\nالعمل: ١- نعلق ساق من الزجاج والساق الآخر من المطاط بوضع افقي بخيطين بواسطة حاملان ونجعلهما متقاربين مع بعض. ٢- ندلك ساق الزجاج بقطعة الحرير (سينشحن الساق بالشحنة الموجبة). وندلك ساق المطاط بقطعة الصوف (ستنشحن الساق بالشحنة السالبة). ٣- نترك الساقين معلقين بحرية نلاحظ تجاذبهما.\nالإستنتاج: أن الساقين المشحونان بالشحنة المختلفة يتجاذبا مع بعضهما.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 مختبر الذرة: اصنع أيوناً بنفسك!"},{"chapter_number":1,"chapter_title":"⚡ الفصل الأول: الكهربائية الساكنة","lesson_number":3,"lesson_title":"🤝 الدرس 3: طرائق شحن الأجسام","order_index":3,"hook":"سؤال وزاري مضمون تقريباً: ما هي طرائق شحن الاجسام بالكهربائية الساكنة؟ بعد هذا الدرس ستعرف الثلاثة وتفهم الفرق بينها بالمحاكاة!","concepts":[{"term":"التفريغ الكهربائي:","text":"هو عملية فقدان الجسم لشحناته الكهربائية.","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["عند شحن جسم بطريقة الدلك أو الحث فان نوع الشحنة المتولد تخالف شحنة الجسم الدالك/الشاحن.","عند شحن جسم بطريقة التمــاس فان نوع الشحنة المتولد يطابق شحنة الجسم الدالك."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هي طرائق شحن الاجسام بالكهربائية الساكنة؟","answer":"توجد ثلاث طرق لشحن المواد بالكهربائية الساكنة وهي كالتالي:\n١. الشحن بطريقة الدلك  ٢. الشحن بطريقة التماس  ٣. الشحن بطريقة الحث.","ministerial":true},{"type":"نشاط","question":"وضح بتجربة طريقة الشحن بالدلك؟","answer":"ندلك بالوناً مطاطية بقطعة من الصوف ستظهر شحنة موجبة عليه (نتيجة لفقدان بعض من الكتروناتها) بينما تظهر شحنة سالبة على البالون (لأنه اكتسب تلك الالكترونات). نعلق البالون بالخيط ونقرب قطعة الصوف نلاحظ تجاذب البالون مع الصوف بسبب اختلاف شحناتهم.","ministerial":false},{"type":"علل","question":"تكون شحنة الصوف موجبة عند دلكها بالبالون؟","answer":"نتيجة لفقدان بعض من الكتروناتها.","ministerial":false},{"type":"علل","question":"تكتسب البالونة شحنة سالبة؟","answer":"لأنه اكتسب الالكترونات التي فقدتها قطعة الصوف.","ministerial":false},{"type":"نشاط","question":"وضح بتجربة الشحن بالتماس؟","answer":"نعلق كرتين من نخاع البيلسان بواسطة خيطين من مادة عازلة ومن نقطة واحدة. نشحن إحدى الكرتين بملامستها لساق من الزجاج المدلوك بالحرير ثم نتركها تلامس الكره الأخرى (الغير مشحونة) نلاحظ ابتعاد الكرتين بعد فتره عن بعض مما يدل على أن الكرة الثانية (الغير مشحونة) قد اكتسبت الشحنة نفسها من شحنة الكرة الأولى بالتماس.","ministerial":true},{"type":"نشاط","question":"وضح مع الرسم كيفية شحن جسم موصل معزول متعادل كهربائيا بشحنة موجبة بطريقة الحث؟","answer":"١. نأخذ كرة معدنية معزولة و متعادلة كهربائية.\n٢. نقرب ساق من المطاط مشحون بشحنة سالبة (بعد أن تدلك بالصوف) من الكرة المتعادلة سوف تتجمع الشحنات الموجبة في جزء الكرة القريب من الجسم المشحون (شحنة مقيدة) وجزء الكرة البعيد عن الجسم المشحون تتجمع فيه الشحنة السالبة (شحنة طليقة).\n٣. نربط الكرة المعدنية بالأرض عبر سلك موصل أو مسكها باليد من جهة الشحنة الطليقة لغرض تفريغها مع بقاء الساق المشحونة قريبة من الكرة.\n٤. نقطع اتصال الكرة بالأرض ثم نبعد الساق المشحونة عن الكرة المعدنية لتبقى الشحنة الموجبة على الكرة فقط حيث أصبحت الكرة مشحونة بهذه الشحنة.","ministerial":true},{"type":"سؤال","question":"في طريقة الشحن بالحث ما نوع شحنة الجسم المشحون؟","answer":"تكون مخالفة لشحنة الجسم الشاحن.","ministerial":false},{"type":"سؤال","question":"لديك ساق من الزجاج مدلوك بالحرير ومشحون بشحنة موجبة ولديك كرة معدنية متعادلة كهربائيا ومعزولة. كيف يمكنك شحن هذه الكرة بشحنة موجبة مرة وبشحنة سالبة مرة أخرى باستخدام نفس الساق؟","answer":"يتم شحن الكرة بالشحنة المشابهة للساق (الموجبة) بطريقة التماس حيث تنتقل بعض الشحنات الموجبة من الساق الى سطح الكرة بالتماس فتقل بذلك شحنة الساق ويتم شحن الكرة بالشحنة المخالفة للساق (السالبة) بطريقة الحث. حيث ان سطح الكرة المقابل للساق تظهر عليه شحنة سالبة مقيدة وسطح الكرة من الجهة الثانية تظهر علية شحنة موجبة طليقة والشحنة الموجبة الطليقة تعادلت بسبب تسرب الالكترونات من الأرض الى الكرة.","ministerial":true},{"type":"سؤال","question":"ماذا يحصل لشحنة جسم مشحون شحنة سالبة عند ايصاله بالأرض؟","answer":"تتعادل شحنة الجسم المشحون بالشحنة الموجبة عند ايصاله بالأرض، وذلك لكون الأرض مستودع كبير للشحنات السالبة، فالجسم المشحون بالشحنة الموجبة تتسرب الإلكترونات من الأرض الى الجسم وتعادل شحنته.","ministerial":true},{"type":"علل","question":"تجهز سيارات الوقود بسلاسل معدنية في مؤخرتها تلامس الأرض؟","answer":"للتخلص من الشحنات الكهربائية الساكنة المتولدة من احتكاك الوقود بجدار الخزان والمتجمعة عند السطح الخارجي والتي قد تسبب كارثة عند حدوث تفريغ كهربائي.","ministerial":true},{"type":"سؤال","question":"ما تأثير الرطوبة في الهواء المحيط بالجسم المشحون بطريقة التماس؟","answer":"تزيد من عملية فقدان شحنة الجسم الى الهواء المحيط حيث يصبح متعادل الشحنة مع الهواء (الشحنة الكلية = صفر).","ministerial":false},{"type":"سؤال","question":"ما المقصود بالشحنات الطليقة والشحنات المقيدة؟","answer":"الشحنات الطليقة: هي الشحنات الموجود على سطح مادة متعادلة الشحنة وتظهر عندما يقترب منها جسم اخر مشحون بشحنة مشابهة لشحنتها فتهرب تلك الشحنات الطليقة الى الطرف الاخر من سطح المادة لكي تتنافر مع شحنات الجسم المشابهه لها.\nالشحنات المقيدة: هي الشحنات الموجود على سطح مادة متعادلة وتظهر عندما يقترب منها جسم اخر مشحون بشحنة مخالفة لشحنتها فتتجاذب معها وتكون محصورة بين الشحنات الطليقة وشحنات الجسم الاخر المخالفة.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 محاكاة طرائق الشحن الثلاث"},{"chapter_number":1,"chapter_title":"⚡ الفصل الأول: الكهربائية الساكنة","lesson_number":4,"lesson_title":"🔬 الدرس 4: الكشاف الكهربائي","order_index":4,"hook":"كيف نعرف إن كان جسم ما مشحوناً؟ وكيف نعرف نوع شحنته؟ المحقق الذي يجيب عن السؤالين اسمه الكشاف الكهربائي!","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما الكشاف الكهربائي وما الغرض منهُ؟","answer":"هو جهاز يستخدم في تجارب الكهربائية الساكنة لأغراض منها:\n١. الكشف عن وجود شحنة كهربائية على جسم ما.\n٢. معرفة نوع الشحنة الكهربائية على الجسم المشحون.","ministerial":true},{"type":"سؤال","question":"مم يتركب الكشاف الكهربائي؟","answer":"يتألف الكشاف الكهربائي من:\n١. ساق معدنية طويلة.\n٢. قرص معدني يتصل بالطرف العلوي للساق.\n٣. ورقتين من الذهب أو الألمنيوم تتصلان بالطرف السفلي للساق.\n٤. صندوق من الزجاج أو المعدن (للحفاظ عليه من التأثيرات الخارجية).\n٥. سداد من الفلين في الجزء العلوي من الصندوق.","ministerial":true},{"type":"سؤال","question":"ما هي طرق شحن الكشاف الكهربائي؟","answer":"١- طريقة التماس (التوصيل)  ٢- طريقة الحث.","ministerial":false},{"type":"نشاط","question":"اشرح نشاط توضح فيه شحن الكشاف الكهربائي بطريقة التماس؟","answer":"الأدوات: ١- كشاف كهربائي ٢- مشط من البلاستك.\nالعمل: ١- ندلك المشط بالشعر بشرط أن يكون جافاً، كي لا يحصل تفريغ كهربائي. ٢- نجعل المشط يلامس قرص الكشاف المتعادل كهربائياً. نلاحظ ابتعاد ورقتي الكشاف.\nالإستنتاج: عند حصول التماس بين المشط المشحون وقرص الكشاف المتعادل كهربائياً تبتعد ورقتا الكشاف بسبب ظهور قوة تنافر بينهما لإكتساب الورقتين النوع نفسهُ من الشحنات.","ministerial":true},{"type":"نشاط","question":"وضح بنشاط تبين فيه شحن كشاف كهربائي بطريقة الحث؟","answer":"الأدوات: ١- كشاف كهربائي ٢- ساق من زجاج ٣- قطعة من الحرير.\nالعمل:\n١- ندلك ساق الزجاج بقطعة الحرير تظهر على الساق شحنة موجبة.\n٢- نقرب ساق الزجاج المشحون من قرص كشاف متعادل الشحنة (سينشحن قرص الكشاف بالشحنة السالبة المقيدة وتنشحن ورقة الألمنيوم بالشحنة الموجبة وهي الشحنة الطليقة) كهربائياً نلاحظ تنافر ورقة الكشاف الكهربائي.\n٣- نصل قرص الكشاف بالأرض ((بوضع اصبع اليد على قرص الكشاف)) مع بقاء ساق الزجاج المشحونة بالقرب من قرص الكشاف نلاحظ إنطباق الورقة على ساق الكشاف بسبب اكتساب الكشاف شحنات من الأرض.\n٤- نقطع اتصال قرص الكشاف بالأرض ((نرفع اصبع اليد على القرص)) مع بقاء ساق الزجاج المشحونة بالقرب من قرص الكشاف نلاحظ بقاء الورقة ساق الكشاف.\n٥- نبعد ساق الزجاج عن الكشاف نلاحظ تنافر ورقة الألمنيوم مع ساق الكشاف وهذا يدل على توزع الشحنات الباقية ((الشحنات التي كانت مقيدة)) على قرص الكشاف والساق والورقة.","ministerial":true},{"type":"سؤال","question":"كيف يمكن الكشف عن وجود الشحنة باستخدام الكشاف الكهربائي؟","answer":"يتم الكشف عن وجود الشحنة وذلك عن طريق تقريب الجسم المراد الكشف عن امتلاكه شحنه أم لا من قرص الكشاف، فاذا انفرجت ورقتا الكشاف دل ذلك على ان الجسم مشحون، اما إذا بقيت ورقتي الكشاف منطبقة فان الجسم غير مشحون.","ministerial":false},{"type":"سؤال","question":"كيف يمكن معرفة نوع شحنة جسم مشحون باستخدام الكشاف الكهربائي؟","answer":"١. يشحن الكشاف بشحنة معلومة بالنسبة لنا.\n٢. نقرب الجسم المراد معرفة نوع شحنته من قرص الكشاف، فاذا:\n  أ- أزداد انفراج ورقتي الكشاف دل على ان الجسم مشحون بشحنة مشابهة لشحنة الكشاف.\n  ب- قل انفراج ورقتي الكشاف دل ذلك على ان الجسم مشحون بشحنة مخالفة لشحنة الكشاف.","ministerial":false},{"type":"علل","question":"يزداد انفراج ورقتي الكشاف الكهربائي المشحون بشحنة سالبة عند تقريب جسم مشحون بشحنة سالبة منهُ؟","answer":"يزداد انفراج ورقتي الكشاف الكهربائي لأن الشحنات السالبة على قرص الكشاف تنافرت مع الشحنات السالبة للجسم لذلك زاد انفراج ورقتي الكشاف.","ministerial":true},{"type":"علل","question":"يزداد إنفراج ورقتي الكشاف الكهربائي المشحون بشحنة موجبة عند تقريب جسم مشحون بشحنة موجبة من قرصه؟","answer":"يزداد انفراج ورقتي الكشاف الكهربائي لأن الشحنات الموجبة بقرص الكشاف سوف تتنافر مع الشحنات الموجبة الموجودة في ذلك الجسم.","ministerial":true},{"type":"سؤال","question":"ماذا يحصل عند ملامسة قرص الكشاف الكهربائي المتعادل لجسم مشحون بشحنة سالبة؟","answer":"سوف يزداد انفراج ورقتي الكشاف الكهربائي بسبب ظهور قوة تنافر بينهما لإكتساب الورقتين النوع نفسهُ من الشحنات.","ministerial":true},{"type":"سؤال","question":"لماذا تنفرج ورقتا الكشاف الكهربائي المشحون بطريقة التماس؟","answer":"وذلك لاكتسابهما شحنة مماثلة لشحنة الجسم الملامس.","ministerial":false},{"type":"سؤال","question":"لماذا تنجذب ورقتا الكشاف الكهربائي المشحون بطريق الحث؟","answer":"وذلك لاكتسابهما شحنة مخالفة لشحنة الجسم المقرب من قرص الكشاف.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 الكشاف التفاعلي"},{"chapter_number":1,"chapter_title":"⚡ الفصل الأول: الكهربائية الساكنة","lesson_number":5,"lesson_title":"🏭 الدرس 5: التطبيقات وأقسام المواد","order_index":5,"hook":"هل تعلم أن طلاء سيارة أبيك صُبغ باستخدام الكهربائية الساكنة؟ قطرات الصبغ المشحونة تتوزع بالتساوي فيخرج الطلاء متجانساً وجميلاً!","concepts":[],"laws":[],"notes":[],"tables":[{"caption":"ما الفرق بين المواد الموصلة والمواد العازلة؟","headers":["","المواد الموصلة","المواد العازلة"],"rows":[["١","هي مواد تحتوي على وفرة من الشحنات الكهربائية السالبة وتكون جيدة التوصيل الكهربائي","هي المواد التي تكون ضعيفة التوصيل الكهربائي"],["٢","الكتروناتها ضعيفة الارتباط بالنواة","تكون الكتروناتها قوية الارتباط بنواة الذرة"],["٣","تتحرك الإلكترونات فيها بسهولة","لا تتحرك فيها الشحنات الكهربائية بحرية"],["٤","مثل النحاس والفضة والالمنيوم وغيرها","مثل الزجاج والصوف والخشب"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"ما الفائدة (التطبيقات العملية) من الكهربائية الساكنة؟ / تستثمر الكهربائية الساكنة في عدد من الأجهزة عددها؟","answer":"١. في جهاز المرذاذ ((جهاز صبغ السيارات))\n٢. جهاز الإستنساخ\n٣. أجهزة الترسيب في معامل الإسمنت\n٤. تثبيت مواد التجميل والعدسات اللاصقة.","ministerial":true},{"type":"سؤال","question":"ما هو المرذاذ؟ وما هو الغرض منهُ؟ وكيف يعمل؟","answer":"المرذاذ: هو أحد التطبيقات الكهربائية الساكنة يستخدم لغرض صبغ الأجسام (مثل السيارات والكراسي) حيث توصل فوهة المرذاذ بالقطب الموجب للمصدر الكهربائي وهذا يجعل جميع قطيرات الصبغه الخارجية من فوهة الجهاز مشحونة بشحنة موجبة. فتتباعد قطرات الصبغ بعضها عن بعض بسبب قوى التنافر بينها. أما الجسم المراد صبغهُ فيوصل مع القطب السالب للمصدر أو يوصل بالأرض وهذا يساعد على انجذاب قطرات الصبغ الى الجسم المراد صبغهُ وبالتالي تكون عملية الطلاء جيدة ومتجانسة.","ministerial":true},{"type":"سؤال","question":"تقسم المواد من حيث قابليتها للتوصيل الكهربائي الى ثلاثة أقسام عددها مع الشرح والأمثلة؟","answer":"١. الموصلات: هي المواد التي تحتوي على وفرة من الشحنات الكهربائية السالبة الشحنة ((الكتروناتها ضعيفة الإرتباط بنواتها)) مثل النحاس، الألمنيوم وغيرها.\n٢. العوازل: هي المواد التي لا تتحرك فيها الشحنات الكهربائية بحرية ((تكون الكتروناتها قوية الإرتباط)) بالنواة. مثل الزجاج والصوف والخشب وغيرها.\n٣. أشباه الموصلات: هي المواد التي تمتلك قابلية التوصيل الكهربائي في ظروف معينة وتسلك سلوك العوازل في الظروف الأخرى، مثل السليكون والجرمانيوم.","ministerial":false},{"type":"سؤال","question":"كيف تكون حركة الالكترونات في الموصلات؟ ولماذا؟","answer":"تتحرك الكتروناتها بسهولة لان الكتروناتها ضعيفة الإرتباط بنواتها.","ministerial":false},{"type":"سؤال","question":"كيف تكون حركة الالكترونات العوازل؟ ولماذا؟","answer":"لا تتحرك الكتروناتها بحرية لان الكتروناتها قوية الإرتباط بنواتها.","ministerial":false},{"type":"سؤال","question":"ما هي الظروف التي تكون فيها أشباه الموصلات مواد موصلة؟","answer":"درجة حرارة عالية – الضوء – احتوائها على شوائب من مواد اخرى.","ministerial":false},{"type":"سؤال","question":"ما الفرق بين المواد الموصلة والمواد العازلة؟","answer":"","ministerial":true},{"type":"علل","question":"عدم إنجذاب قصاصات الورق الصغيرة الى ساق النحاس المدلوكة بالصوف عند مسكة اليد.؟","answer":"وذلك لأن الشحنات الكهربائية المتولدة على ساق النحاس قد تسربت الى الأرض عن طريق الجسم.","ministerial":true},{"type":"علل","question":"إنجذاب قصاصات الورق الى ساق النحاس المدلوك بالصوف عند مسكه بمادة عازلة أو عند لبس كف من مادة عازلة؟","answer":"وذلك لأن ساق النحاس قد أحتفظ بالشحنات الكهربائية لفترة قصيرة مما أدى الى إنجذاب قصاصات الورق.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 شاهد: كيف يعمل المرذاذ؟"},{"chapter_number":1,"chapter_title":"⚡ الفصل الأول: الكهربائية الساكنة","lesson_number":6,"lesson_title":"⚖️ الدرس 6: قانون كولوم","order_index":6,"hook":"عرفنا أن الشحنات تتجاذب وتتنافر... لكن بأي قوة؟ العالم كولوم وضع القانون الذي يحسبها بدقة!","concepts":[],"laws":[{"name":"قانون كولوم","formula":"F = K × (q₁ × q₂) / r²","variables_note":"F: القوة الكهربائية وتقاس بالنيوتن N · K: ثابت التناسب (ثابت كولوم) ومقداره في الفراغ 9×10⁹ N·m²/C² · q₁q₂: مقدار الشحنتين وتقاسان بالكولوم C · r: البعد بين مركزي الشحنتين ويقاس بالمتر m"}],"notes":[{"heading":"خطوات مهمة جداً عند تطبيق قانون كولوم:","items":["١. أكتب معطيات المسألة بصورة دقيقة جداً.","٢. تحويل الوحدات إذا لم تكون موحدة: الإنتباه الى وحدة البعد (يجب أن تكون بالمتر) ووحدة الشحنة بالكولوم ووحدة القوة بالنيوتن.","٣. نطبق القانون: F = K × (q₁×q₂) / r²","٤. التعويض عن المتغيرات بأرقامها المعطاة.","٥. نستخدم العمليات الحسابية المعتادة لإيجاد المطلوب."],"ministerial":false}],"tables":[{"caption":"جدول التحويلات — احفظه جيداً!","headers":["للتحويل من أجزاء المتر الى المتر","للتحويل من أجزاء الكولوم الى الكولوم"],"rows":[["سانتي متر: cm → m نضرب ×10⁻²","بيكو كولوم: pC → C نضرب ×10⁻¹²"],["ملي متر: mm → m نضرب ×10⁻³","ملي كولوم: mC → C نضرب ×10⁻³"],["مايكرو متر: μm → m نضرب ×10⁻⁶","مايكرو كولوم: μC → C نضرب ×10⁻⁶"],["نانو متر: nm → m نضرب ×10⁻⁹","نانو كولوم: nC → C نضرب ×10⁻⁹"]],"ministerial":false}],"examples":[{"problem":"مثال ١: وضعت شحنة نقطية موجبة مقدارها (+4×10⁻⁶ C) على بعد (0.06m) من شحنة كهربائية نقطية موجبة أخرى مقدارها (+9×10⁻⁶ C). احسب مقدار: ١- القوة التي تؤثر بها الشحنة الاولى q₁ على الشحنة الثانية q₂.  ٢- القوة التي تؤثر بها الشحنة الثانية q₂ على الشحنة الأولى q₁.","givens":"المعطيات: q₁ = +4×10⁻⁶ C — q₂ = +9×10⁻⁶ C — r = 0.06 m — المطلوب F₁₂ = ?","solution_steps":["الخطوة ١: الوحدات موحدة أصلاً (كولوم ومتر) — نطبق القانون مباشرة: F₁₂ = K × (q₁ × q₂) / r²","الخطوة ٢: نعوض: F₁₂ = 9×10⁹ × (4×10⁻⁶ × 9×10⁻⁶) / (0.06)²","الخطوة ٣: نحسب البسط والمقام: F₁₂ = 9×10⁹ × (36×10⁻¹²) / (36×10⁻⁴) = 90 N","الخطوة ٤: وبنفس الطريقة F₂₁ = 90 N. بما ان القوى متبادلة بين الشحنات فانها تخضع لقانون نيوتن الثالث: F₂₁ = −F₁₂ — مقدار القوة الاولى يساوي مقدار القوة الثانية لكن معاكس لها بالاتجاه."],"ministerial":false},{"problem":"مثال ٢ (خارجي): شحنتان كهربائيتان نقطيتان مقدارهما (2×10⁻⁶ C) و (−8×10⁻⁶ C) وضعتا على بعد (0.06m) عن بعضهما. احسب مقدار القوة التي تؤثر بها الشحنة الاولى على الشحنة الثانية وما نوعها؟","givens":"المعطيات: q₁ = 2×10⁻⁶ C — q₂ = −8×10⁻⁶ C — r = 0.06 m","solution_steps":["الخطوة ١: نطبق القانون: F = 9×10⁹ × (2×10⁻⁶ × −8×10⁻⁶) / (0.06)²","الخطوة ٢: نحسب: F = 9×10⁹ × (−16×10⁻¹²) / (36×10⁻⁴) = −40 N","الخطوة ٣: الإشارة السالبة تعني أن نوع القوى تجاذب (لأن الشحنتين مختلفتان). 💡"],"ministerial":false},{"problem":"مثال ٣ (خارجي): شحنتان نقطيتان موضوعتان في الهواء مقدار الشحنة الاولى (6μC) ومقدار الشحنة الثانية (2μC) والبعد بينهما (30cm). احسب مقدار القوة الكهربائية المتبادلة بينهما مبينا نوع القوة؟","givens":"المعطيات: q₁ = 6μC = 6×10⁻⁶ C — q₂ = 2μC = 2×10⁻⁶ C — r = 30cm = 3×10⁻¹ m","solution_steps":["الخطوة ١: لاحظ التحويلات! μC ضربنا ×10⁻⁶ و cm ضربنا ×10⁻².","الخطوة ٢: نطبق ونعوض: F = 9×10⁹ × (6×10⁻⁶ × 2×10⁻⁶) / (3×10⁻¹)² = 9×10⁹ × (12×10⁻¹²) / (9×10⁻²)","الخطوة ٣: النتيجة: F = 12×10⁻³ × 10² = 1.2 N والقوة تنافر لأن الشحنتين موجبتان."],"ministerial":false},{"problem":"مثال ٤ (خارجي): شحنتان كهربائيتان نقطيتان متماثلتان قوة التنافر بينهما (10N) عندما كان البعد بينهما (6cm). احسب مقدار شحنة كل منهما؟","givens":"المعطيات: q₁ = q₂ = q → q₁×q₂ = q² — F = 10N — r = 6cm = 6×10⁻² m","solution_steps":["الخطوة ١: نطبق القانون مع مجهول q²: 10 = 9×10⁹ × q² / (6×10⁻²)²","الخطوة ٢: نرتب لإيجاد q²: q² = (10 × 36×10⁻⁴) / (9×10⁹) = 40×10⁻¹³ = 4×10⁻¹²","الخطوة ٣: نأخذ الجذر: q = 2×10⁻⁶ C"],"ministerial":false},{"problem":"مثال ٥ (خارجي): شحنتان كهربائيتان نقطيتان احداهما (4×10⁻⁶ C) والاخرى (9×10⁻⁶ C) قوة التنافر بينهما (90N). احسب مقدار البعد بين الشحنتين؟","givens":"المعطيات: q₁ = 4×10⁻⁶ C — q₂ = 9×10⁻⁶ C — F = 90 N — المطلوب: r","solution_steps":["الخطوة ١: نرتب القانون لإيجاد r²: r² = K × (q₁ × q₂) / F","الخطوة ٢: نعوض: r² = 9×10⁹ × (4×10⁻⁶ × 9×10⁻⁶) / 90 = 36×10⁻⁴","الخطوة ٣: الجذر: r = 6×10⁻² m = 0.06 m 💡 لاحظ: هذه عكس المثال الأول تماماً — نفس الشحنتين ونفس القوة!"],"ministerial":false}],"qa":[{"type":"سؤال","question":"ما نص قانون كولوم؟","answer":"القوة الكهربائية المتبادلة بين شحنتين كهربائيتين نقطيتين ساكنتين تتناسب طردياً مع حاصل ضرب مقدار الشحنتين وعكسياً مع مربع البعد بينهما.","ministerial":false},{"type":"سؤال","question":"على ماذا يعتمد ثابت التناسب في قانون كولوم؟","answer":"يعتمد على نوع مادة الوسط بين الشحنتين.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 مختبر كولوم: العب بالشحنات!"},{"chapter_number":1,"chapter_title":"⚡ الفصل الأول: الكهربائية الساكنة","lesson_number":7,"lesson_title":"🌐 الدرس 7: المجال الكهربائي","order_index":7,"hook":"كيف «تشعر» شحنة بوجود شحنة أخرى بعيدة عنها؟ الجواب: كل شحنة تصنع حولها مجالاً كهربائياً غير مرئي، مثل هالة من التأثير!","concepts":[{"term":"الشحنة الاختبارية:","text":"هي شحنة موجبة صغيرة المقدار لا تؤثر على الشحنات المجاورة لها باي قوة.","ministerial":false}],"laws":[{"name":"قانون المجال الكهربائي","formula":"E = F / q","variables_note":"E: المجال الكهربائي ووحداته N/C · F: القوة الكهربائية وتقاس بالنيوتن N · q: الشحنة الاختبارية وتقاس بالكولوم C"}],"notes":[],"tables":[],"examples":[{"problem":"مثال (٢): شحنة كهربائية نقطية موجبة (+2×10⁻⁹ C) وضعت عند نقطة في مجال كهربائي فتأثرت بقوة مقدارها (4×10⁻⁶ N). ما مقدار المجال الكهربائي؟","givens":"المعطيات: q = +2×10⁻⁹ C — F = 4×10⁻⁶ N — المطلوب: E","solution_steps":["الخطوة ١: نطبق قانون المجال: E = F / q","الخطوة ٢: نعوض: E = (4×10⁻⁶) / (2×10⁻⁹)","الخطوة ٣: نقسم ونطرح الأسس: E = 2×10⁻⁶⁺⁹ = 2×10³ N/C"],"ministerial":false},{"problem":"مثال (خارجي): شحنة كهربائية مقدارها (6μC) وضعت عند نقطة A في مجال كهربائي وكان مقدار القوة الكهربائية المؤثر فيها (24N). جد مقدار المجال الكهربائي في تلك النقطة.","givens":"المعطيات: q = 6μC = 6×10⁻⁶ C — F = 24 N — المطلوب: E","solution_steps":["الخطوة ١: حولنا المايكروكولوم: 6μC = 6×10⁻⁶ C.","الخطوة ٢: نعوض في E = F/q: E = 24 / (6×10⁻⁶)","الخطوة ٣: النتيجة: E = 4×10⁺⁶ N/C"],"ministerial":false},{"problem":"مثال (خارجي): شحنة كهربائية مقدارها (3μC) وضعت عند النقطة P في مجال كهربائي وكان مقدار المجال الكهربائي (4×10⁺⁶ N/C). احسب مقدار القوة الكهربائية المؤثرة فيها؟","givens":"المعطيات: q = 3μC = 3×10⁻⁶ C — E = 4×10⁺⁶ N/C — المطلوب: F","solution_steps":["الخطوة ١: نرتب القانون: من E = F/q نحصل على: F = E × q","الخطوة ٢: نعوض: F = 4×10⁺⁶ × 3×10⁻⁶","الخطوة ٣: النتيجة: F = 12 N"],"ministerial":true}],"qa":[{"type":"سؤال","question":"ما المقصود بـ: ١- المجال الكهربائي في أي نقطة ٢- مقدار المجال الكهربائي؟","answer":"المجال الكهربائي: هو الحيز الذي تظهر فيه تأثير القوة الكهربائية على الشحنات الاختبارية الداخلة فيه.\nمقدار المجال الكهربائي: هو القوة الكهربائية لوحدة الشحنة والمؤثرة في شحنة اختبارية صغيرة موجبة موضوعه عند نقطه بداخله ويحسب بالعلاقة التالية: E = F / q","ministerial":true},{"type":"سؤال","question":"كيف نستدل على وجود المجال الكهربائي؟","answer":"لنفرض لدينا شحنة نقطية موجبة في نقطة معينه وان هذه الشحنة تحدث في الحيز المحيط بها تاثيرا يعرف بالمجال الكهربائي ويختبر هذا المجال في اي نقطة بواسطة شحنة صغير موجبة تسمى شحنة الاختبار توضع في تلك النقطة وتقاس القوة فيها لمعرفة المجال الكهربائي.","ministerial":true},{"type":"سؤال","question":"كيف يمكن تمثيل المجال الكهربائي؟ وما مميزات خطوط المجال الكهربائي؟","answer":"يمكن تمثيل المجال الكهربائي بخطوط وهمية (غير مرئية) تبدأ من الشحنة الموجبة وتنتهي بالشحنة السالبة تسمى خطوط المجال الكهربائي.","ministerial":false},{"type":"سؤال","question":"ما المقصود بالمجال الكهربائي المنتظم؟","answer":"هو المجال المتولد بين لوحين معدنيين مستويين متوازيين مشحونين بشحنتين متساويتين مقدارا ومختلفتين في النوع فتكون خطوط هذا المجال متوازية مع بعضها بأبعاد متساوية وتكون عمودية على اللوحين.","ministerial":false},{"type":"سؤال","question":"ما الفرق بين المجال الكهربائي بين شحنتين نقطيتين والمجال الكهربائي بين لوحين معدنيين مستويين متوازيين مشحونين بشحنتين متساويتين في المقدار مختلفتين نوعا؟","answer":"المجال الكهربائي بين شحنتين نقطيتين يمثل بخطوط تبدأ من الشحنة الموجبة وتنتهي بالشحنة السالبة. اما المجال بين لوحين معدنيين تمثل بخطوط متوازية مع بعضها وتبتعد عن بعضها بأبعاد متساوية وتكون عمودية على اللوحين.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 راسم خطوط المجال الكهربائي"},{"chapter_number":2,"chapter_title":"🧲 الفصل الثاني: المغناطيس","lesson_number":1,"lesson_title":"🧲 الدرس 1: قصة اكتشاف المغناطيس","order_index":1,"hook":"لماذا ينغلق باب الثلاجة من تلقاء نفسه؟ وكيف تعرف البوصلة طريق الشمال دائماً حتى في وسط البحر؟ السرّ كله في المغناطيس!","concepts":[{"term":"ابرة البوصلة:","text":"هي عبارة عن مغناطيس دائمي صغير يمكنه الدوران بحرية في مستوى أفقي حول محور شاقولي مدبب وتتجه نحو الشمال المغناطيسي الأرضي.","ministerial":true}],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"أوضح بإيجاز تاريخ اكتشاف المغناطيس؟","answer":"منذ 25 قرنا اكتشف اليونانيون معدنا يجذب اليه قطع الحديد اطلقوا علية أسم المغنيت والذي يتركب من أوكسيد الحديد الأسود ورمزه الكيميائي هو Fe₃O₄ واصبح معروفا باسم الحجر المغناطيسي.","ministerial":false},{"type":"سؤال","question":"ما هي اشكال المغناطيس الصناعي؟","answer":"١. ساق مغناطيسية مستقيمة  ٢. مغناطيس بشكل حرف U","ministerial":false},{"type":"سؤال","question":"ما استعمالات المغانط الكهربائية؟ ما الفائدة العملية من المغناطيسية؟","answer":"١. تستعمل لرفع قطع الفولاذ أو الحديد (السكراب)\n٢. يستعمل في مولدات الصوت (السماعة) والمولدات والمحركات الكهربائية والتلفاز وأجهزة التسجيل الصوتي\n٣. يستعمل في الحروف المطبعية للآلة الكاتبة\n٤. يستعمل في بوصلة الملاحة","ministerial":true}],"has_simulation":true,"simulation_title":"🧪 جرب بنفسك: البوصلة والمغناطيس"},{"chapter_number":2,"chapter_title":"🧲 الفصل الثاني: المغناطيس","lesson_number":2,"lesson_title":"🔍 الدرس 2: المواد المغناطيسية","order_index":2,"hook":"قرّب مغناطيساً من دبابيس ثم من قلم رصاص — الدبابيس تقفز نحوه والقلم لا يتحرك أبداً! لماذا؟ الجواب في أنواع المواد المغناطيسية.","concepts":[],"laws":[],"notes":[{"heading":"📌 ملاحظة مهمة:","items":["المواد التي تتنافر مع المغناطيس القوي تنافراً ضعيفاً تدعى الدايا مغناطيسية بينما المواد التي تنجذب للمغناطيس الاعتيادي تدعى فيرو مغناطيسية."],"ministerial":false}],"tables":[{"caption":"ما الفرق بين المواد الدايا مغناطيسية والبارا مغناطيسية والفيرومغناطيسية؟","headers":["","المواد الدايامغناطيسية","المواد البارا مغناطيسية","المواد الفيرومغناطيسية"],"rows":[["١","هي المواد التي تتنافر مع المغناطيس القوي تنافرا ضعيفا","مواد تنجذب الى المغناطيس القوي تجاذبا ضعيفا","هي المواد التي تنجذب للمغناطيس الاعتيادي فهي تمتلك قابلية تمغنط عالية"],["٢","مثل البزموث، الانتيمون، النحاس، السيلكون، الفضة","مثل المنيوم، كالسيوم، صوديوم، تيتانيوم","مثل الحديد، الفولاذ، النيكل، كوبلت"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"تصنف المواد المختلفة وفقا إلى خواصها المغناطيسية إلى أنواع اذكر هذه الأنواع؟ / عدد أنواع المواد المغناطيسية مع ذكر الخواص المغناطيسية لكل نوع؟","answer":"١. المواد الدايا مغناطيسية: هي المواد التي تتنافر مع المغناطيس القوي تنافرا ضعيفا مثل (البزموث والانتيمون والنحاس والسيليكون والفضه).\n٢. المواد البارا مغناطيسية: هي المواد التي تنجذب بالمغناطيس القوي تجاذبا ضعيفا مثل (الألمنيوم والكالسيوم والصوديوم وتيتانيوم).\n٣. المواد الفيرو مغناطيسية: هي المواد التي تنجذب بالمغناطيس الاعتيادي حيث تمتلك قابلية تمغنط عالية مثل (الحديد والفولاذ والنيكل والكوبلت).","ministerial":true},{"type":"سؤال","question":"ما الفرق بين المواد الدايا مغناطيسية والبارا مغناطيسية والفيرومغناطيسية؟","answer":"","ministerial":true},{"type":"سؤال","question":"ما الخواص المغناطيسية للمواد الدايا مغناطيسية (البزموث، الانتيمون، النحاس، السلكون، الفضه)؟","answer":"تتنافر مع المغناطيس القوي تنافرا ضعيفا.","ministerial":false},{"type":"سؤال","question":"ما الخواص المغناطيسية للمواد الفيرو مغناطيسية (الحديد، الفولاذ، النيكل، الكوبلت)؟","answer":"تنجذب بالمغناطيس الاعتيادي وتمتلك قابلية تمغنط عالية.","ministerial":false},{"type":"سؤال","question":"ما الخواص المغناطيسية للمواد البارامغناطيسية (الألمنيوم، الكالسيوم، الصوديوم، التيتانيوم)؟","answer":"تنجذب بالمغناطيس القوي تجاذبا ضعيفا.","ministerial":false},{"type":"علل","question":"بعض المواد تنجذب بسهولة نحو المغناطيس مثل ماسكات الورق والدبابيس على عكس المواد الأخرى مثل قلم الرصاص والممحاة؟","answer":"لأنه ماسكات الورق والدبابيس مواد فيرومغناطيسية تمتلك قبلية تمغنط عالية بعكس المواد الأخرى الممحاة وقلم الرصاص فهي مواد لا تتأثر بالمغناطيس.","ministerial":false}],"has_simulation":true,"simulation_title":"🎮 لعبة: صنّف المواد المغناطيسية!"},{"chapter_number":2,"chapter_title":"🧲 الفصل الثاني: المغناطيس","lesson_number":3,"lesson_title":"🧭 الدرس 3: الأقطاب المغناطيسية","order_index":3,"hook":"لو قصصت مغناطيساً إلى نصفين، هل تحصل على قطب شمالي وحده في يد وقطب جنوبي وحده في اليد الأخرى؟ مستحيل! اكتشف السبب في هذا الدرس.","concepts":[{"term":"الأقطاب المغناطيسية:","text":"هي مناطق في المغناطيس يكون عندها مقدار القوة المغناطيسية بأعظم ما يمكن ويحتوي المغناطيس على قطبين أحدهما شمالي والآخر جنوبي ولا يوجد بصورة منفرده بل بشكل ازواج شمالي وجنوبي.\nمميزاتها:\n١. لا توجد بشكل منفرد بل بصورة (الزوج شمالي وجنوبا).\n٢. عند تقطيع قطعة المغناطيس إلى أجزاء صغيرة تبقى محافظة على ازدواجية الأقطاب.\n٣. يكون مقدار القوة المغناطيسية عندها بأعظم ما يمكن.","ministerial":true}],"laws":[],"notes":[{"heading":"📌 ملاحظة:","items":["عند تقطيع ساق مغناطيسية إلى قطع صغيرة فإننا سوف نحصل على قطع صغيرة تمتلك كل منها قطب شمالي وجنوبي."],"ministerial":true}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"إذا قطعت قطعة من المغناطيس إلى قطع صغيرة فإن كل قطعة تحتوي على قطب واحد فقط؟ هل هذه العبارة صحيحة أم خاطئة؟","answer":"العباره خاطئة لأنه إذا قطع المغناطيس إلى أجزاء صغيرة فإنه كل جزء يحتوي على قطبين متساويين بالمقدار مختلفين في النوع شمالي وجنوبي.","ministerial":true},{"type":"سؤال","question":"هل يمكن ان يفقد المغناطيس مغناطيسيته عند التقطيع؟ ولماذا؟","answer":"لا يفقد المغناطيس مغناطيسيته عند التقطيع لأنه إذا قطع المغناطيس الى قطع صغيرة فان كل قطعة تحتوي على قطبين شمالي وجنوبي.","ministerial":true},{"type":"سؤال","question":"يفقد المغناطيس مغناطيسيته بطريقتين؟ اذكرهما. أو كيف يفقد المغناطيس مغناطيسيته؟","answer":"١. الطرق القوي.  ٢. التسخين الشديد.","ministerial":true},{"type":"نشاط","question":"اشرح نشاط توضع فيه قوى تجاذب والتنافر بين الأقطاب؟","answer":"الأدوات: ١- ساقان مغناطيسيان ٢- خيط ٣- كلاب ٤- حامل من مادة لا تتأثر بالمغناطيس.\nالعمل:\n١. يعلق الساق المغناطيسية من منتصفها بواسطة الخيط والكلاب والحامل ونتركها حرة في وضع أفقي نلاحظ أن الساق المغناطيسية تتخذ وضعا أفقيا بموازاة خط (الشمال الجنوب) الجغرافي تقريباً.\n٢. نمسك بيدنا ساقاً مغناطيسية أخرى ونجعل قطبها الشمالي بارزاً من اليد.\n٣. نقرب القطب الشمالي للساق المغناطيسية الممسوكة باليد من القطب الشمالي للساق المغناطيسية المعلقة نجد أن القطب الشمالي للمغناطيس الطليق يبتعد عن القطب الشمالي للمغناطيس الممسوك باليد وهذا ناتج عن تنافرهما.\n٤. نعكس قطبية الساق الممسوكة باليد (نجعل القطب الجنوبي هو البارز من اليد) نقربه من القطب الجنوبي للساق المغناطيسية المعلقة نجد ان القطب الجنوبي للمغناطيس الطليق يبتعد عن القطب الجنوبي للمغناطيس الممسوك في اليد وهذا ناتج أيضا عن قوة التنافر بينهما.\n٥. نكرر العملية السابقة ونقرب القطب الشمالي للساق المغناطيسية الممسوكة باليد من القطب الجنوبي للساق المعلقة نجد أن القطبين ينجذبان مع بعضهما في هذه الحالة وهذا ناتج عن تأثرهما بقوة تجاذب.\nالاستنتاج: الأقطاب المغناطيسية المتشابهة تتنافر مع بعضها بينما الأقطاب المغناطيسية المختلفة تتجاذب مع بعضها.","ministerial":true}],"has_simulation":true,"simulation_title":"🧪 جرب بنفسك: المغناطيس المعلق"},{"chapter_number":2,"chapter_title":"🧲 الفصل الثاني: المغناطيس","lesson_number":4,"lesson_title":"🌀 الدرس 4: المجال المغناطيسي","order_index":4,"hook":"انثر برادة حديد حول مغناطيس وانقر بلطف... سترى خطوطاً منتظمة مذهلة ترسم نفسها! هذه هي خريطة المجال المغناطيسي الخفي.","concepts":[{"term":"المجال المغناطيسي:","text":"هو الحيز الذي يحيط بالمغناطيس والذي يظهر فيه تأثير القوة المغناطيسية.","ministerial":true}],"laws":[],"notes":[{"heading":"","items":["يمكن رسم خطوط المجال المغناطيسي باستعمال بوصلة مغناطيسية، ويمكن الكشف عنها باستعمال برادة حديد.","يمكن للمجال المغناطيسي النفاذ خلال جسم الإنسان وكذلك خلال مواد مختلفة منها الورق المقوى والزجاج والماء."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هي مميزات خطوط القوى المغناطيسية (خطوط المجال المغناطيسي)؟","answer":"١. خطوط مقفلة غير مرئية.\n٢. تتجه من القطب الشمالي نحو القطب الجنوبي خارج المغناطيس ومكملة دورتها داخله.\n٣. لا تتقاطع فيما بينها بل تتنافر.\n٤. تكون مزدحمة عند الأقطاب.","ministerial":true},{"type":"سؤال","question":"كيف يمكن تمثيل المجال المغناطيسي؟","answer":"يمثل بالرسم بخطوط وهمية (غير مرئية) تسمى خطوط القوى المغناطيسية باستخدام بوصلة أو عدة بوصلات وكذلك يمكن من خلال مشاهدتها باستخدام برادة الحديد.","ministerial":false},{"type":"سؤال","question":"ما الفائدة العملية من استعمال (البوصلة المغناطيسية، مجموعة من البوصلات المغناطيسية الصغيرة، برادة الحديد)؟","answer":"لرسم خطوط المجال المغناطيسي حول المغناطيس.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من استعمال برادة الحديد؟","answer":"للكشف عن خطوط المجال المغناطيسي.","ministerial":false},{"type":"نشاط","question":"اشرح نشاط يمكنك فيه مشاهدة خطوط المجال المغناطيسي باستعمال برادة الحديد لساق مغناطيسية؟","answer":"الأدوات: ١. ساق مغناطيسية  ٢. لوح من الزجاج وبرادة حديد.\nالعمل:\n١. نضع لوح الزجاج على الساق المغناطيسية وبمستوى افقي.\n٢. ننثر برادة الحديد على لوح الزجاج وننقر اللوح بالطف، نلاحظ ان برادة الحديد ترتبت بشكل خطوط.\nالاستنتاج: ان برادة الحديد التي ترتبت بشكل خطوط هي تلك الخطوط التي تمثل المجال المغناطيسي حول الساق المغناطيسية.","ministerial":true},{"type":"علل","question":"تكون قوة جذب المغناطيس عند الأقطاب اكبر من المنتصف؟","answer":"لان القوة المغناطيسية تتركز عند الاقطاب كون خطوط المجال المغناطيسي مزدحمه عند الاطراف وضعيفة في المنتصف.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 راسم خطوط المجال المغناطيسي"},{"chapter_number":2,"chapter_title":"🧲 الفصل الثاني: المغناطيس","lesson_number":5,"lesson_title":"✋ الدرس 5: نفاذ المجال المغناطيسي","order_index":5,"hook":"ضع مغناطيساً فوق كفّك ومثبتات ورق تحت الكف... سترى المثبتات تلتصق بيدك وكأنها مسحورة! المجال المغناطيسي عبر يدك كاملة.","concepts":[],"laws":[],"notes":[{"heading":"📌 الخلاصة:","items":["يمكن للمجال المغناطيسي النفاذ خلال جسم الإنسان وكذلك خلال مواد مختلفة منها الورق المقوى والزجاج والماء."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"نشاط","question":"اشرح نشاط توضح فيه ان المجال المغناطيسي يمكنه النفاذ من خلال جسم الانسان؟","answer":"الأدوات: ١. مجموعة من مثبتات الورق مصنوعة من الفولاذ  ٢. مغناطيس قوي.\nطريقة العمل:\n١. نضع الساق المغناطيسية على كف يدنا.\n٢. نضع راحة يدنا على مجموعة من مثبتات الورق.\n٣. نرفع كف يدنا الى الاعلى نجد ان مجموعة منها قد انجذبت الى راحة كف يدنا.\nالاستنتاج: ان انجذاب مثبتات الورق دليل على ان المجال المغناطيسي نفذ من خلال جسم الانسان.","ministerial":true},{"type":"نشاط","question":"اشرح نشاطاً توضح فيه أن المجال المغناطيسي يمكن النفاذ خلال قطعة من الورق المقوى (الكارتون)؟","answer":"الادوات: ١. ساق مغناطيسية  ٢. قطعة من الكارتون  ٣. مجموعة مسامير.\nخطوات العمل:\n١. نمسك الساق المغناطيسية بوضع شاقولي باليد.\n٢. نضع بعض مسامير الحديد بلطف على قطعة ورق المقوى.\n٣. نمسك قطعة ورقة المقوى باليد الأخرى ونضعها فوق القطب العلوي للمغناطيس.\n٤. نحرك الساق المغناطيسية تحت الورقة في مسار دائري أو بخط مستقيم.\n٥. نلاحظ أن مجموعة المسامير تنجذب نحو القطب المغناطيسي للساق وتتحرك متبعه المسار نفسه لحركة القطب المغناطيسي.\nالاستنتاج: نستنتج من هذا النشاط أن المجال المغناطيسي يمكنه النفاذ خلال مواد مختلفة منها الورق المقوى.","ministerial":true},{"type":"نشاط","question":"اشرح نشاط توضح فيه أن المجال المغناطيسي يمكنه النفاذ من خلال الماء؟","answer":"الادوات: ١- ساق مغناطيسية  ٢- مجموعة من المسامير  ٣- إسطوانة زجاج  ٤- ماء.\nالخطوات:\n١. نجعل مجموعة المسامير داخل الأسطوانة الزجاجية ثم نضيف كمية مناسبة من الماء في الإسطوانه.\n٢. نقرب أحد قطبي الساق المغناطيسية من جدار الأسطوانة سنلاحظ أن المسامير تنجذب نحو قطب المغناطيس القريب منها.\n٣. نحرك القطب المغناطيسي للساق حول الأسطوانة نجد أن المسامير تتحرك متبعة المسار نفسه لحركة القطب المغناطيسي.\nالاستنتاج: نستنتج من هذا النشاط أن المجال المغناطيسي يمكنه النفاذ خلال مواد مختلفة منها الماء.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 شاهد النشاط: المجال ينفذ من كفّك!"},{"chapter_number":2,"chapter_title":"🧲 الفصل الثاني: المغناطيس","lesson_number":6,"lesson_title":"⚡ الدرس 6: تمغنط المواد","order_index":6,"hook":"هل تصدق أن إبرة الخياطة في بيتكم يمكن أن تتحول إلى مغناطيس دائمي؟ وأن مسماراً عادياً يصير مغناطيساً قوياً بمجرد لف سلك حوله وتوصيله ببطارية؟","concepts":[{"term":"الحافظه المغناطيسية:","text":"هي مادة فيرومغناطيسية تستعمل لحماية الاجهزة كالساعات من التأثيرات المغناطيسية الخارجية ولحفظ المغانط الدائمة من زوال مغناطيسيتها بعد مرور الزمن.\nفائدتها:\n١. لحماية الاجهزة من التأثيرات المغناطيسية الخارجية.\n٢. لحفظ المغانط الدائمة من زوال مغناطيسيتها بمرور الوقت.","ministerial":true}],"laws":[],"notes":[{"heading":"📌 ملاحظة:","items":["طريقة التمغنط بالحث تتم بطريقتين هما التمغنط بالتقريب والتمغنط بالتيار الكهربائي المستمر."],"ministerial":false},{"heading":"📌 ملاحظات مهمة:","items":["المغانط الدائمية تصنع من مادة الفولاذ.","يصنع المغناطيس الكهربائي الذي يفقد مغناطيسيته بعد فترة قصيرة من انقطاع التيار الكهربائي عنه من مادة الحديد المطاوع.","إن مسمار الحديد في تجويف ملف سلكي منساب فيه تيار مستمر يمكن له الأحتفاظ بمغناطيسيته بصورة دائمية.","عند وضع مسمار من الحديد داخل مجال مغناطيسي قوي دون حدوث تلامس بين المسمار والمغناطيس فإن المسمار يكتسب المغناطيسية بطريقة الحث."],"ministerial":true}],"tables":[{"caption":"ما الفرق بين طريقة التمغنط بالدلك والحث؟","headers":["","مغنطة المواد بطريقة الدلك","مغنطة المواد بطريقة الحث"],"rows":[["١","تتم مغنطة قطعة الفولاذ وذلك بدلكها بأحد قطبي مغناطيس حيث يجب تحريك المغناطيس فوق الفولاذ باتجاه واحد فقط وبحركة بطيئة وتكرر عدة مرات وبتماس بينهما","تتم مغنطة المادة الفيرومغناطيسية الغير ممغنطة وذلك بوضعها داخل مجال مغناطيسي قوي او وضعها بالقرب من مغناطيس قوي من دون تماس مباشر معه"],["٢","بعد الانتهاء يكون الفولاذ مغناطيسا وان القطب المغناطيسي المتولد في نهاية جهة الدلك بنوعية مخالفة للقطب المغناطيسي الدالك","يتولد على طرفي المادة الفيرومغناطيسية قطبان احدهما شمالي والآخر جنوبي علما ان طرف المادة الفيرومغناطيسية القريب من المغناطيس المؤثر يكون قطبا مخالفا في النوع"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"اذكر طرائق تمغنط المواد للحصول على المغانط الدائمة والمغانط المؤقتة؟","answer":"١. طريقة التمغنط بالدلك  ٢. طريقة التمغنط بالحث","ministerial":true},{"type":"سؤال","question":"اشرح طريقة التمغنط بالدلك؟ كيف تمغنط قطعة فولاذ (أبرة خياطة) وتجعلها مغناطيساً دائمياً؟","answer":"يتم مغنطة إبرة الفولاذ وذلك بدلكها بأحد قطبي مغناطيس ويجب تحريك القطب المغناطيسي للساق المغناطيسية فوق إبرة الفولاذ باتجاه واحد فقط وبحركة بطيئة وتكرر لمرات عدة بعدها تصير الإبرة مغناطيساً وان القطب المغناطيسي المتولد في نهاية جهة الدلك للإبرة يكون دائما مخالفاً بنوعه للقطب المغناطيسي الدالك.","ministerial":true},{"type":"سؤال","question":"ما هي طرق مغنطة المادة بالحث؟","answer":"١. التمغنط بالتقريب  ٢. التمغنط بالتيار الكهربائي المستمر","ministerial":false},{"type":"سؤال","question":"صحح الخطأ / عند تقريب مسمار من قطب شمالي مغناطيسي فان الطرف القريب منه يكون قطباً جنوبيا؟","answer":"ان العبارة أعلاه صحيحة لأنه في نهاية العملية أصبح المسمار مغناطيسياً يمتلك قطبان شمالي بعيد عن المغناطيس الأصلي وجنوبي قريب من المغناطيس الأصلي.","ministerial":true},{"type":"سؤال","question":"وضح كيف يمكن تمغنط المواد الفيرومغناطيسية بطريقة التقريب؟ أو ماذا يحدث عند وضع مادة فيرومغناطيسية غير ممغنطة (مسمار) داخل مجال مغناطيسي من غير تماس؟","answer":"عند وضع مادة فيرومغناطيسية غير ممغنطة مسمار مثلا داخل مجال مغناطيسي قوي (بالقرب من مغناطيس قوي من غير تماس) فإن المسمار سيكتسب المغناطيسية بالحث ويتولد على طرفي المسمار قطبان أحدهما قطب شمالي والآخر جنوبي حيث أن طرف المسمار القريب من المغناطيس المؤثر يكون قطبا مخالفا في النوع للقطب المغناطيسي المؤثر.","ministerial":true},{"type":"سؤال","question":"هل يمكن مغنطة قطعة من الفولاذ باستخدام التيار الكهربائي المستمر؟","answer":"نعم يمكن ذلك. عند وضع قطعة من الفولاذ داخل ملف مجوف وهو عبارة عن سلك موصل معزول ملفوف بشكل لولبي او لف السلك مباشرة حول المسمار من الفولاذ ونوصل طرفا الملف ببطارية (تيار مستمر) ونحصل بذلك على مغناطيس كهربائي.","ministerial":true},{"type":"سؤال","question":"وضح كيف يمكن ان تبين طريقة التمغنط بالتيار المستمر في المختبر؟","answer":"عند وضع مسمار حديد (من الحديد المطاوع)، فان قطعة الحديد المطاوع سوف تتمغنط عند انسياب التيار الكهربائي المستمر في السلك الموصل المحلزن وعند قطع التيار الكهربائي سوف تفقد قطعة الحديد مغناطيسيتها. ان الناتج من هذه العملية مغناطيس كهربائي مؤقت وتزول مغناطيسيته بزوال التيار الكهربائي المنساب في السلك.","ministerial":true},{"type":"سؤال","question":"ما الفرق بين طريقة التمغنط بالدلك والحث؟","answer":"","ministerial":true},{"type":"سؤال","question":"على ماذا تعتمد قوة المغناطيس الكهربائي؟","answer":"١. مقدار التيار المستمر المنساب في الدائرة الكهربائية.\n٢. عدد لفات السلك حول قطعة الفولاذ (عدد لفات الملف).\n٣. نوع المادة المراد مغنطتها.","ministerial":true},{"type":"سؤال","question":"هل يمكن أن يتولد مجال مغناطيسي حول شحنة كهربائية متحركة؟ أعطي مثال؟","answer":"نعم مثل انسياب التيار الكهربائي المستمر في سلك موصل يولد مجال مغناطيسي.","ministerial":false},{"type":"سؤال","question":"عرف المغناطيس الدائمي؟","answer":"وهو مغناطيس لا يفقد مغناطيسيته عند زوال المصدر المسبب لها مثل عملية جعل ابرة صغيرة من الفولاذ مغناطيس دائمي وبعدة طرق منها التقريب او باستخدام مصدر للتيار المستمر.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 مختبر: اصنع مغناطيساً كهربائياً!"},{"chapter_number":3,"chapter_title":"🔌 الفصل الثالث: التيار الكهربائي","lesson_number":1,"lesson_title":"⚡ الدرس 1: حركة الشحنات الكهربائية","order_index":1,"hook":"عندما تضغط زر المصباح اليدوي يضيء فوراً! السبب: مجال كهربائي يدفع إلكترونات سلك التوصيل فتتحرك جميعها معاً — هذه الحركة هي التيار الكهربائي.","concepts":[],"laws":[],"notes":[{"heading":"","items":["التيار الكهربائي يعتبر وسيلة نقل الطاقة الكهربائية من مصادر التوليد إلى الأجهزة الكهربائية التي نستثمرها."],"ministerial":false},{"heading":"","items":["يكون اتجاه حركة الإلكترونات خلال اسلاك التوصيل المربوطة ببطارية من القطب السالب للبطارية الى القطب الموجب للبطارية وذلك لان الإلكترونات سالبة الشحنة."],"ministerial":false},{"heading":"","items":["أطلق على التيار الكهربائي عبارة التيار الاصطلاحي عندما يكون اتجاهه بنفس اتجاه المجال الكهربائي المؤثر.","التيار الاصطلاحي يعتمد في جميع الدوائر الكهربائية لتحديد اتجاه التيار.","قد يكون التيار ناتج عن حركة الأيونات الموجبة والايونات السالبة داخل المحاليل الإلكترونية أو بواسطة الايونات الموجبة والإلكترونات كما في تأين غاز النيون داخل مصباح الفلورسنت تحت الضغط واطئ."],"ministerial":true}],"tables":[{"caption":"قارن بين المواد الموصلة والعازلة للتيار الكهربائي من حيث (قابلية التوصيل – ارتباطها بالنواة)؟","headers":["المواد الموصلة","المواد العازلة"],"rows":[["هي تلك المواد التي تسمح بانسياب التيار الكهربائي من خلالها","هي المواد التي لا تسمح بانسياب التيار الكهربائي من خلالها"],["تكون الكتروناتها ضعيفة الارتباط بالنواة فاذا تعرضت الى مجال كهربائي خارجي فأنها ستتحرك باتجاه معاكس لذلك المجال الكهربائي","تكون الكتروناتها قوية الارتباط بالنواة فلا تتحرك بتأثير مجال كهربائي خارجي"],["مثل الالمنيوم والفولاذ والحديد والنحاس","مثل الخشب والزجاج والمطاط والبلاستيك"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"هل يمكن للشحنات الكهربائية الساكنة أن تنجز شغلاً؟ ومتى تنجز الشحنة الكهربائية شغلاً؟","answer":"لا يمكن للشحنات الكهربائية الساكنة أن تنجز شغلاً. ويمكن أن تنجز شغلاً عندما تتحرك ضمن أسلاك التوصيل التي تربط أي جهاز كهربائي بمصدر الطاقة الكهربائية.","ministerial":true},{"type":"علل","question":"إذا تعرضت الكترونات المدارات (الكترونات التكافؤ) في المواد الموصلة إلى مجال كهربائي خارجي فأنها ستتحرك بين ذرات الموصل باتجاه معاكس لاتجاه المجال الكهربائي المؤثر (لأن الإلكترونات سالبة الشحنة). ما سبب ذلك؟","answer":"لأن الكترونات المدارات الخارجية في المواد الموصلة تكون ضعيفة الارتباط بنواتها.","ministerial":false},{"type":"سؤال","question":"عدد أنواع المواد من حيث قابليتها أم عدم قابليتها على إيصال التيار الكهربائي؟","answer":"١. الموصلات: تسمح بإنسياب التيار الكهربائي خلالها.\n٢. العوازل: لا تسمح بإنسياب التيار الكهربائي خلالها مثل الخشب.\n٣. أشباه الموصلات: تكون موصلة في ظروف معينة وعازلة في ظروف أخرى مثل السيلكون.","ministerial":false},{"type":"قارن","question":"قارن بين المواد الموصلة والعازلة للتيار الكهربائي من حيث (قابلية التوصيل – ارتباطها بالنواة)؟","answer":"","ministerial":true},{"type":"سؤال","question":"ما المقصود بـ (التيار الإلكتروني - التيار الاصطلاحي)؟ أو قارن بينهما؟","answer":"التيار الإلكتروني: هو التيار الذي يكون اتجاهه من القطب السالب إلى القطب الموجب خلال أسلاك التوصيل فيكون اتجاهه معاكس لاتجاه المجال الكهربائي.\n\nالتيار الاصطلاحي: هو التيار الذي يكون اتجاهه من القطب الموجب للبطارية إلى القطب السالب خلال أسلاك التوصيل فيكون اتجاهه مع اتجاه المجال الكهربائي.","ministerial":true},{"type":"سؤال","question":"كيف ينتج التيار الكهربائي في المحاليل الالكتروليتية؟","answer":"ينتج من حركة الايونات الموجبة والسالبة داخل المحاليل الالكتروليتية.","ministerial":false},{"type":"سؤال","question":"كيف ينتج التيار الكهربائي في اسلاك التوصيل؟","answer":"ينتج من حركة الالكترونات السالبة فقط عندما تتعرض الى مجال كهربائي خارجي.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 محاكاة: من أين إلى أين يتحرك التيار؟"},{"chapter_number":3,"chapter_title":"🔌 الفصل الثالث: التيار الكهربائي","lesson_number":2,"lesson_title":"📏 الدرس 2: التيار الكهربائي والأمبير","order_index":2,"hook":"تخيل شرطي مرور يقف عند مقطع من السلك ويعدّ الشحنات العابرة كل ثانية... كلما عبرت شحنات أكثر في الثانية كان التيار أكبر!","concepts":[{"term":"التيار الكهربائي:","text":"هو مقدار الشحنات الكهربائية المتحركة خلال مقطع عرضي لموصل في وحدة الزمن ويقاس بالأمبير.","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["هناك اجزاء صغيرة المقدار هي ملي امبير ومايكرو امبير ويمكن تحويلها الى امبير كتالي:","ملي أمبير mA ← نضرب × 10⁻³ للتحويل إلى A","مايكرو أمبير μA ← نضرب × 10⁻⁶ للتحويل إلى A"],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال ١: يمر من مقطعا عرضيا من موصل شحنات كهربائية مقدارها (1.2C) في كل دقيقة احسب مقدار التيار المنساب خلال الموصل؟","givens":"المعطيات: q = 1.2 C — t = دقيقة واحدة = 60 s — المطلوب: I","solution_steps":["الخطوة ١: نحول الزمن إلى ثوانٍ: دقيقة واحدة = 60 ثانية.","الخطوة ٢: نطبق القانون: I = q / t = 1.2 / 60","الخطوة ٣: النتيجة: I = 0.02 A"],"ministerial":false},{"problem":"مثال ٢: اذا كان مقدار التيار المنساب في موصل (0.4A) احسب كمية الشحنة التي تعبر مقطعا عرضيا من موصل خلال: a – 2 sec b - 4 minutes","givens":"المعطيات: I = 0.4 A — المطلوب: q في الحالتين","solution_steps":["الخطوة ١ (الفرع a): من I = q/t نحصل على q = I × t: q = 0.4 × 2 = 0.8 C","الخطوة ٢ (الفرع b): نحول الدقائق إلى ثوانٍ: 4 دقائق = 4 × 60 ثانية: q = 0.4 × 4 × 60 = 96 C"],"ministerial":false},{"problem":"سؤال: اذا كان مقدار التيار الكهربائي المنساب في موصل يساوي (0.6A) احسب كمية الشحنة التي تعبر مقطعا من موصل خلال (120 ثانية)؟","givens":"المعطيات: I = 0.6 A — t = 120 s — المطلوب: q","solution_steps":["الخطوة ١: من I = q/t نحصل على q = I × t.","الخطوة ٢: نعوض: q = 0.6 × 120 = 72 C"],"ministerial":false},{"problem":"سؤال: اذا كان مقدار التيار الكهربائي في موصل كهربائي هو (3A) فما هو الزمن الازم لعبور كمية من الشحنات الكهربائية مقدارها (9μC) خلال مقطعا عرضيا من ذلك الموصل؟","givens":"المعطيات: I = 3 A — q = 9 μC = 9×10⁻⁶ C — المطلوب: t","solution_steps":["الخطوة ١: نحول المايكرو كولوم: 9μC = 9×10⁻⁶ C.","الخطوة ٢: من I = q/t نحصل على t = q / I: t = (9×10⁻⁶) / 3","الخطوة ٣: النتيجة: t = 3×10⁻⁶ sec"],"ministerial":false}],"qa":[{"type":"سؤال","question":"عرف التيار الكهربائي وذكر الصيغة الرياضية له مع ذكر وحدة القياس؟","answer":"التيار الكهربائي: هو مقدار الشحنات الكهربائية المتحركة خلال مقطع عرضي لموصل في وحدة الزمن ويقاس بالأمبير.\nالتيار الكهربائي = الشحنة ÷ الزمن أو I = q / t\nحيث ان:\nI: هو التيار الكهربائي ويقاس بوحدة الأمبير (A)\nq: هي الشحنة الكهربائية وتقاس بالكولوم (C)\nt: الزمن يقاس بالثانية (S)","ministerial":false},{"type":"سؤال","question":"عرف الامبير؟","answer":"الامبير: هو تدفق واحد من الشحنات الكهربائية في مقطع الموصل خلال ثانية واحدة حيث:\nالامبير = كولوم / ثانية أو Ampere = coulomb / Second","ministerial":true},{"type":"سؤال","question":"ما المقصود بالعبارة الاتية: تيار كهربائي مقداره (4A) ينساب في سلك موصل؟","answer":"معنى ذلك ان شحنات كهربائية مقدارها (4C) تعبر مقطعا في هذا السلك الموصل في زمن قدره ثانية واحدة.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 عدّاد الشحنات: اصنع تيارك بنفسك!"},{"chapter_number":3,"chapter_title":"🔌 الفصل الثالث: التيار الكهربائي","lesson_number":3,"lesson_title":"🔋 الدرس 3: أنواع التيار الكهربائي","order_index":3,"hook":"لماذا يشتغل هاتفك بالبطارية وبالشاحن معاً؟ لأن هناك نوعين من التيار: مستمر DC من البطارية ومتناوب AC من مأخذ الحائط — والشاحن يحوّل بينهما!","concepts":[],"laws":[],"notes":[{"heading":"","items":["اذا كان التيار الكهربائي المنساب في موصل ثابتا في الاتجاه مع مرور الزمن يسمى بـ التيار الكهربائي المستمر."],"ministerial":true}],"tables":[{"caption":"قارن بين التيار الكهربائي المستمر والمتناوب من ناحية المصدر والخصائص؟","headers":["التيار الكهربائي المستمر","التيار الكهربائي المتناوب"],"rows":[["١- وهو التيار الكهربائي المنساب خلال موصل ما ويكون ثابت في الاتجاه مع مرور الزمن","١- وهو التيار الذي يكون متغير في المقدار والاتجاه مع مرور الزمن"],["٢- رمزه DC","٢- رمزه AC"],["٣- مصادره هي البطاريات ومولدات التيار المستمر","٣- مصادره هي مولدات التيار المتناوب"]],"ministerial":false}],"examples":[],"qa":[{"type":"سؤال","question":"ما هي أنواع التيار الكهربائي؟ ذاكرا مصادر كل نوع؟","answer":"١. التيار المستمر DC: هو التيار الذي يكون ثابت في المقدار والاتجاه مع الزمن (مثاليا) اذا كان خارج من البطارية ويكون ثابت في الاتجاه ومتغير المقدار مع الزمن اذا كان خارج من المولد الكهربائي البسيط ويرمز له بالرمز DC، ومصادر التيار المستمر هي الاعمدة الكيميائية (البطاريات) ومولدات التيار المستمر.\n\n٢. التيار المتناوب AC: وهو التيار الذي يكون متغير في المقدار والاتجاه مع مرور الزمن ويرمز له بالرمز AC ومصادر التيار المتناوب هي مولدات التيار المتناوب.","ministerial":true},{"type":"قارن","question":"قارن بين التيار الكهربائي المستمر والمتناوب من ناحية المصدر والخصائص؟","answer":"","ministerial":false},{"type":"سؤال","question":"ما نوع وشكل التيار الخارج من المصادر التالية: (البطارية – مولد التيار المستمر – مولد التيار المتناوب)؟","answer":"أولا: البطارية: تيار مستمر ثابت المقدار والاتجاه.\nثانيا: مولد التيار المستمر: تيار مستمر ثابت الاتجاه متغير المقدار.\nثالثا: مولد التيار المتناوب: تيار متناوب متغير المقدار والاتجاه.\n(شاهد الأشكال الثلاثة في الراسم أدناه 👇)","ministerial":false},{"type":"سؤال","question":"ما هي مميزات التيار الخارج من البطارية؟","answer":"١- تيار كهربائي مستمر رمزة DC ٢- ثابت في المقدار والاتجاه ٣- يعد تيار مثالي","ministerial":false},{"type":"سؤال","question":"ما هي مميزات التيار الكهربائي الخارج من المولد الكهربائي البسيط؟","answer":"١- تيار كهربائي مستمر رمزه DC ٢- ثابت في الاتجاه ومتغير المقدار ٣- يعد تيار غير مثالي","ministerial":false},{"type":"سؤال","question":"ما هي مميزات التيار الكهربائي الخارج من مولد التيار المتناوب؟","answer":"١- تيار كهربائي متناوب رمزه AC ٢- متغير في المقدار والاتجاه ٣- يعد تيار غير مثالي","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 راسم أشكال التيار (مثل شاشة راسم الذبذبات!)"},{"chapter_number":3,"chapter_title":"🔌 الفصل الثالث: التيار الكهربائي","lesson_number":4,"lesson_title":"💡 الدرس 4: الدائرة الكهربائية وقياس التيار","order_index":4,"hook":"لماذا ينطفئ مصباح غرفتك لحظة ضغط المفتاح؟ لأنك فتحت الدائرة فانقطع مسار الإلكترونات — أغلقه فيعود التيار للانسياب فوراً!","concepts":[{"term":"الدائرة الكهربائية:","text":"هي المسار المغلق الذي تتحرك الإلكترونات من خلاله وتتألف من مصباح كهربائي (حمل) - أسلاك توصيل - مفتاح كهربائي - بطارية فولطياتها مناسبة.","ministerial":true}],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما المقصود بالدائرة الكهربائية المفتوحة والمغلقة؟","answer":"الدائرة المفتوحة: هي الدائرة التي يكون فيها المفتاح الكهربائي مفتوحا أي لا ينساب تيار كهربائي فيها حيث لا يتوهج المصباح المربوط فيها وهذا يعني وجود قطع في الدائرة.\n\nالدائرة المغلقة: هي الدائرة التي يكون فيها المفتاح مغلق أي أنه يؤدي إلى انسياب تيار كهربائي خلال أسلاك التوصيل فيؤدي إلى توهج المصباح.","ministerial":false},{"type":"سؤال","question":"ما الفائدة العملية من استخدام الأميتر؟ ما الغرض من استعمال جهاز الأميتر؟","answer":"الأميتر جهاز يستخدم لقياس التيار الكهربائي في الدائرة الكهربائية.","ministerial":true},{"type":"سؤال","question":"ما الغرض من استخدام جهاز الملي اميتر؟","answer":"يستعمل لقياس التيارات صغيرة المقدار بالملي امبير.","ministerial":false},{"type":"سؤال","question":"ما الأمور الواجب مراعاتها عند استخدام جهاز الأميتر لقياس التيار الكهربائي؟","answer":"١. يربط الأميتر على التوالي مع الحمل أو الجهاز المطلوب معرفة التيار المنساب فيه (لكي تنساب من خلاله جميع الشحنات الكهربائية في الجزء الموضوع فيه الأميتر).\n٢. تكون مقاومة الأميتر صغيرة جدا نسبة إلى مقاوم الدائرة أو الجهاز المطلوب معرفة التيار المار فيه.\n٣. يربط الطرف الموجب لجهاز الأميتر (وهو عادة يكون باللون الأحمر أو علامة +) مع القطب الموجب للنضيدة. (نقطة ذات جهد أعلى) بينما يربط القطب السالب (وهو باللون الأسود او إشارة −) من جهة القطب السالب للنضيدة (نقطة جهد اوطأ).","ministerial":true},{"type":"علل","question":"يربط جهاز الأميتر على التوالي في الدار الكهربائية؟","answer":"وذلك لكي تنساب من خلاله جميع الشحنات الكهربائية في الجزء الموضوع في الأميتر.","ministerial":false},{"type":"سؤال","question":"يراد قياس التيار الكهربائي المنساب في حمل مقاومته صغيرة باستعمال جهاز الاميتر. هل يربط الاميتر على التوالي ام على التوازي مع ذلك الحمل؟ وضح ذلك. (الجواب النقطة الاولى فقط)","answer":"يربط على التوالي مع الحمل لكي ينساب خلاله جميع الشحنات الكهربائية ويربط القطب الموجب للحمل مع القطب الموجب لجهاز الأميتر وسالب منه مع القطب السالب للحمل.","ministerial":true},{"type":"نشاط","question":"وضح نشاط قياس التيار الكهربائي باستعمال جهاز الأميتر ذاكر الاستنتاج مع رسم؟","answer":"الأدوات: ١- جهاز الأميتر ٢- أسلاك توصيل. ٣- مصباح كهربائي ٤- مفتاح كهربائي ٥- بطارية فولطياتها مناسبة ٦- مقاومة متغيرة (ريوستات).\nالخطوات:\n١. نربط كل من جهاز الأميتر والمصباح الكهربائي والمفتاح والبطارية والمقاومة المتغيرة بواسطة أسلاك التوصيل مع بعضها على التوالي مع الانتباه لنوعية الأقطاب لكل من البطارية والاميتر.\n٢. نغلق مفتاح الدائرة نلاحظ توهج المصباح و انحراف مؤشر جهاز الأميتر مشيرا إلى انسياب تيار كهربائي في الدائرة.\n٣. نغير مقدار مقاومة أريوستات سيتغير تيار الدائرة فنحصل على قراءة جديدة للأميتر نلاحظ توهج المصباح ثم نكرر العملية وفي كل مرة نحصل على مقدار جديد للتيار المنساب في الدائرة.\nالاستنتاج: قراءة الأميتر تتغير بتغير مقدار التيار المنساب في الدائرة الكهربائية فهي تشير دائما إلى مقدار التيار المنساب في الدائرة.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 نفّذ النشاط بنفسك: قياس التيار بالأميتر"},{"chapter_number":3,"chapter_title":"🔌 الفصل الثالث: التيار الكهربائي","lesson_number":5,"lesson_title":"🔺 الدرس 5: فرق الجهد الكهربائي","order_index":5,"hook":"الماء ينساب من النقطة العالية إلى الواطئة... والتيار الكهربائي ينساب من نقطة الجهد الأعلى إلى الجهد الأوطأ — وعند تساوي الجهدين يتوقف!","concepts":[{"term":"فرق الجهد:","text":"هو الشغل اللازم لنقل واحدة الشحنة الكهربائية من نقطة ذات جهد عالي إلى نقطة ذات جهد واطئ داخل المجال الكهربائي ويقاس بوحدة الفولت ويستخدم لقياس مقداره جهاز الفولتميتر.","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["يكون أنسياب التيار الكهربائي من النقطة ذات الجهد الأعلى إلى النقطة ذات الجهد الأوطأ، وعند تساوي جهدي النقطتين يتوقف سريان التيار الكهربائي.","وحدة قياس فرق الجهد الكهربائي هي الفولط Volt وهو يقاس بجهاز الفولطميتر."],"ministerial":false}],"tables":[{"caption":"ما الفرق بين جهاز الاميتر وجهاز الفولطميتر من حيث الربط في الدائرة الكهربائية والاستخدام؟","headers":["الاميتر","الفولتميتر"],"rows":[["يربط على التوالي في الدائرة الكهربائية مع الحمل بسبب صغر مقاومته الداخلية نسبة لمقاومة الدائرة","يربط على التوازي في الدائرة بسبب كبر مقاومته الداخلية نسبة الى مقاومة الدائرة"],["يستخدم لقياس مقدار التيار الكهربائي","يستخدم لقياس مقدار فرق الجهد الكهربائي"],["يربط الطرف الموجب (باللون الأحمر) لجهاز الاميتر مع الطرف الموجب للنضيدة ويربط طرفة السالب (باللون الأسود) مع الطرف السالب للنضيدة","يربط الطرف الموجب (باللون الأحمر) لجهاز الفولتميتر مع الطرف الموجب للنضيدة ويربط طرفة السالب (باللون الأسود) مع الطرف السالب للنضيدة"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"ما المقصود بفرق الجهد الكهربائي؟ وما واحدة قياسه؟ وجهاز قياسه؟","answer":"فرق الجهد: هو الشغل اللازم لنقل واحدة الشحنة الكهربائية من نقطة ذات جهد عالي إلى نقطة ذات جهد واطئ داخل المجال الكهربائي ويقاس بوحدة الفولت ويستخدم لقياس مقداره جهاز الفولتميتر.","ministerial":false},{"type":"سؤال","question":"ما الذي يحدد مقدار واتجاه التيار الكهربائي المنساب داخل سلك موصل؟","answer":"ان مقدار فرق الجهد بين نقطتين داخل المجال الكهربائي يحدد مقدار التيار الكهربائي المنساب فيكون اتجاه التيار من النقطة ذات الجهد الكهربائي الأعلى الى النقطة ذات الجهد الكهربائي الاوطأ.","ministerial":false},{"type":"سؤال","question":"ما الفائدة العملية من جهاز الفولتميتر؟","answer":"يستعمل لقياس مقدار فرق الجهد الكهربائي بين أي نقطتين في الدائرة الكهربائية.","ministerial":true},{"type":"سؤال","question":"ما هي الأمور الواجب اتباعها عند ربط جهاز الفولتميتر في الدائرة الكهربائية؟","answer":"١. ربط الفولطميتر على التوازي بين طرفي الجهاز المطلوب معرفة فرق الجهد بين طرفيه.\n٢. تكون مقاومة الفولطميتر كبيرة جدا بالنسبة الي مقاومة الدائرة.\n٣. يربط الطرف الموجب لجهاز الفولطميتر مع القطب الموجب للنضيدة بينما يربط طرفه السالب من جهة القطب السالب للنضيدة.\n٤. قبل الربط يجب أن يكون مفتاح الدائرة مفتوحاً.","ministerial":true},{"type":"سؤال","question":"ما لفائدة العملية من جهاز الملي فولتميتر؟","answer":"لقياس مقدار الفولتيات صغيرة المقدار المقدرة بوحدة الملي فولط (mV).","ministerial":false},{"type":"قارن","question":"ما الفرق بين جهاز الاميتر وجهاز الفولطميتر من حيث الربط في الدائرة الكهربائية والاستخدام؟","answer":"","ministerial":true},{"type":"نشاط","question":"اشرح نشاط توضع في قياس فرق الجهد الكهربائي بين نقطتين باستعمال جهاز الفولتميتر؟","answer":"الأدوات: ١- جهاز فولتميتر ٢- أسلاك توصيل ٣- مصباح كهربائي. ٤- مفتاح كهربائي.\nالخطوات:\n١. نربط بواسطة أسلاك التوصيل المصباح الكهربائي والمفتاح بين قطبي البطارية على التوالي، ثم نربط جهاز الفولتميتر على التوازي مع المصباح كما في الشكل.\n٢. نلاحظ انحراف مؤشر جهاز الفولتميتر مشيرا إلى وجودفرق جهد كهربائي بين طرفي المصباح نسجل قراءة الفولتميتر.\nالاستنتاج: ان قراءة الفولتميتر التي سجلت سابقا تمثل مقدار فرق الجهد بين طرفي المصباح.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 نفّذ النشاط بنفسك: قياس فرق الجهد بالفولتميتر"},{"chapter_number":3,"chapter_title":"🔌 الفصل الثالث: التيار الكهربائي","lesson_number":6,"lesson_title":"🧱 الدرس 6: المقاومة الكهربائية وقانون أوم","order_index":6,"hook":"تخيل ممراً مزدحماً بالناس: كلما كان أضيق وأطول صعب المرور فيه! نفس الشيء يحدث للإلكترونات داخل السلك — وهذا سر المقاومة الكهربائية.","concepts":[{"term":"المقاومة الكهربائية:","text":"هي الإعاقة التي يبديها المقاوم للتيار الكهربائي المار من خلاله و تقاس بوحدة (الاوم). أنواعها: ١- مقاومة ثابتة المقدار ٢- مقاومة متغيرة المقدار. والجهاز المستخدم لقياسها هو الأوميتر.","ministerial":true}],"laws":[],"notes":[{"heading":"","items":["لا يعتمد مقدار المقاومة الكهربائية لسلك موصل على: التيار الكهربائي المنساب في السلك.","يُستعمل الأوميتر لقياس مقدار المقاومة الكهربائية بشكل مباشر، وجهاز الاوميتر لا يربط مع الدائرة الكهربائية المغلقة."],"ministerial":true},{"heading":"","items":["لا يعتمد مقدار المقاومة لسلك موصل على التيار الكهربائي المار فيه.","تتناسب مقاومة الموصل طرديا مع درجة الحرارة وطول السلك وعكسيا مع مساحة المقطع العرضي.","مقاومة سلك الحديد أكبر من مقاومة سلك الفضة عند تساوي الطول ومساحة المقطع ودرجة الحرارة."],"ministerial":true}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هي وحدة قياس المقاومة؟ اذكرها بطريقتين؟","answer":"تقاس المقاومة بوحدة الاوم ورمزه ( Ω ) وكذلك تقاس بوحدة volt / amper.","ministerial":true},{"type":"سؤال","question":"المقاومة الكهربائية نوعين؟ اذكرهما مع مثال لكل نوع؟","answer":"١. مقاومة ثابتة المقدار مثل المقاومة ذات الألوان.\n٢. مقاومة متغيرة المقدار مثل الريوستات.","ministerial":true},{"type":"سؤال","question":"ما لفائدة العملية من جهاز الاوميتر؟","answer":"لقياس مقدار المقاومة الكهربائية بصورة مباشرة.","ministerial":true},{"type":"سؤال","question":"ما الجهاز المستعمل لقياس المقاومة بصورة مباشرة؟ وماهي الأمور الواجب اتباعها؟","answer":"نستعمل جهاز الاوميتر. حيث يجب ان تكون المقاومة غير موصلة بالدائرة الكهربائية.","ministerial":true},{"type":"سؤال","question":"كيف يمكنك قياس قيمة مقاومة بطريقة مباشرة مرة وبطريقة قراءة جهاز الاميتر والفولتميتر مرة ثانية؟","answer":"في الطريقة المباشرة نستعمل جهاز الاوميتر حيث يجب ان تكون المقاومة غير موصلة بالدائرة الكهربائية. اما الطريقة الأخرى غير المباشرة فنستعمل قانون اوم حيث نقسم قيمة مقدار فرق الجهد قراءة الفولطميتر على قيمة التيار الكهربائي قراءة جهاز الاميتر فيكون الناتج هو مقدار المقاومة بوحدة الاوم.","ministerial":true},{"type":"سؤال","question":"ماذا يعني فيزيائيا او ما المقصود في العبارة التالية: الموصل ولد إعاقة للتيار الكهربائي أو للمواصل مقاومة كهربائية؟","answer":"ان حركة الإلكترونات تواجه إعاقة أثناء انتقالها داخل الموصلات وهذه الإعاقة ناجمة عن تصادم الإلكترونات مع بعضها ومع ذرات الموصل مما يسبب ارتفاع درجة حرارة الموصل وهذا يعني أن الموصل ولد إعاقة للتيار الكهربائي أي أن للمواصل مقاومة كهربائية.","ministerial":false},{"type":"سؤال","question":"عرف قانون أوم؟ ذاكراً صيغته الرياضية؟","answer":"قانون أوم: هو حاصل قسمة فرق الجهد الكهربائي بين طرفي المقاوم على التيار المنساب فيه يساوي مقدار ثابت ضمن حدود معينة وقد سميه هذا الثابت بالمقاومة الكهربائية.\nR = V / I\nحيث: R المقاومة الكهربائية — V فرق الجهد — I التيار الكهربائي.","ministerial":false},{"type":"سؤال","question":"عرف الاوم؟","answer":"هو مقاومة موصل فرق الجهد بين طرفيه فولطاً واحداً ومقدار التيار المار خلاله أمبيراً واحداً.","ministerial":true},{"type":"نشاط","question":"وضح بأن نشاط قياس مقاومة كهربائية صغيرة المقدار باستعمال الأميتر والفولطميتر","answer":"الأدوات: ١- أسلاك توصيل ٢- جهاز أميتر ٣- جهاز فولتميتر ٤- بطارية ٥- مفتاح كهربائي ٦- مقاومة صغيرة المقدار.\nالخطوات:\n١. نربط الاجهزة الكهربائية كما في الشكل مع مراعاة ربط الإميتر على التوالي مع المقاومة المطلوب حساب مقدارها وربط الفولتميتر على التوازي بين طرفيها.\n٢. نغلق الدائرة الكهربائية ونسجل قراءة كل من الأميتر والفولطميتر.\n٣. نقسم مقدار قراءة الفولطميتر (فرق الجهد) على مقدار قراءة الأميتر (التيار) نحصل على مقدار المقاومة طبقا لقانون أوم R = V / I.","ministerial":true},{"type":"سؤال","question":"عدد العوامل التي يتوقف عليها مقدار مقاومة الموصل؟","answer":"١- درجة الحرارة ٢- طول المواصل ٣- مساحة المقطع العرضي ٤- نوع المادة.","ministerial":true},{"type":"سؤال","question":"وضح تأثير عامل الطول على المقاومة؟","answer":"تتناسب مقاومة الموصل طرديا مع طول السلك (تزداد مقاومة الموصل بزيادة طول السلك).","ministerial":false},{"type":"سؤال","question":"وضح تأثير الحرارة على مقاومة الموصل؟","answer":"تزداد مقاومة الموصل بزيادة درجة الحرارة مثل المواد الموصلة النقية كالنحاس وهناك مواد تقل مقاومتها بارتفاع درجة الحرارة مثل الكربون وهناك مواد أخرى تبقى مقاومتها ثابتة بارتفاع أو انخفاض درجة الحرارة مثل المنكانين والكونستنتان.","ministerial":false},{"type":"سؤال","question":"وضع تأثير نوع المادة على مقدار المقاومة الكهربائية؟","answer":"المقاومة الكهربائية هي خاصية فيزيائية للمادة تبين إعاقتها للتيار الكهربائي المنساب خلالها تختلف المقاومة الكهربائية باختلاف نوع المادة بثبوت العوامل الأخرى مثلا مقاومة سلك من الفضة اصغر من مقاومة سلك من الحديد مساوية له بطول وكذلك مساوي لمساحة المقطع العرضي وعنده درجة الحرارة نفسها.","ministerial":false},{"type":"نشاط","question":"وضح بنشاط عملي تبين فيه العلاقة بين مقاومة الموصل وطوله؟","answer":"الأدوات: ١- بطارية فولطيتها مناسبة ٢- سلك موصل طويل نسبيا ٣- مصباح كهربائي ٤- اميتر ٥- أسلاك توصيل ٦- ماسكين من مادة موصلة ٧- مفتاح كهربائي.\nالخطوات:\n١. نربط دائرة كهربائية متوالية عملية الرابط تحتوي الأميتر والبطارية والمصباح والسلك والمفتاح الكهربائي.\n٢. نضع الماسكين بين طرفي السلك ونلاحظ توهج المصباح ونسجل قراءة الأميتر.\n٣. نحرك الماسكين على السلك نحو بعضهما تدريجيا (لتصغير طول السلك) نلاحظ حصول زيادة تدريجية في قراءة الأميتر وكذلك توهج المصباح وتفسير ذلك أن زيادة التيار المنساب في الدائرة بنقصان مقدار مقاومة الموصل نتيجة لنقصان طوله.\nالاستنتاج: من هذا النشاط نستنتج أن مقاومة الموصل R تتناسب طرديا مع طوله L بثبوت العوامل الأخرى.","ministerial":false},{"type":"نشاط","question":"وضح بنشاط العلاقة بين مقاومة الموصل ومساحة مقطعة العرضي؟","answer":"الأدوات: ١- بطارية فولطيتها مناسبة ٢- سلكين موصلين من مادة النيكل أو الكروم متساويان بالطول والمقطع العرضي ٣- مصباح كهربائي ٤- اميتر ٥- أسلاك توصيل ٦- ماسكين من مادة موصلة ٧- مفتاح كهربائي.\nالخطوات:\n١. نربط دائرة كهربائية متوالية الرابط تحوي الأميتر و البطارية والمصباح وسلك واحد من النيكل.\n٢. نضع الماسكين بين طرفي سلك ونلاحظ توهج المصباح ونسجل قراءة الأميتر.\n٣. نأخذ السلكين المتماثلين بالطول والمقطع العرضي نربط طرفيهما ببعض ونجعلها كسلك واحد لنحصل على سلك غليظ مساحة مقطعه ضعف مساحة السلك الواحد.\n٤. نضع الماسكين بين طرفي السلكين نلاحظ ازدياد توهج المصباح بمقدار أكبر من الحالة الأولى للسلك المنفرد وزيادة قراءة الأميتر عن قراءتها السابقة وهذا يعني أن التيار الكهربائي المنساب في الدائرة قد ازداد بمضاعفة مساحة المقطع العرضي للسلك.\nالاستنتاج: مقاومه الموصل R تتناسب عكسياً مع مساحة مقطعة العرضي A بثبوت العوامل الأخرى.","ministerial":false},{"type":"سؤال","question":"ما الغرض من وجود عوامة داخل خزان الوقود المركبات؟","answer":"تعمل على تغيير مقدار المقاومة الكهربائية التي تتحكم في مقدار التيار المنساب في مقياس الوقود وعندما يكون مستوى الوقود مرتفعا يسري تيار اكبر مسببا انحراف اكبر لمؤشر مقياس الوقود والعكس صحيح.","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 مختبر قانون أوم"},{"chapter_number":3,"chapter_title":"🔌 الفصل الثالث: التيار الكهربائي","lesson_number":7,"lesson_title":"⛓️ الدرس 7: طرائق ربط المقاومات الكهربائية","order_index":7,"hook":"التوالي = طريق واحد تمر منه كل السيارات، والتوازي = عدة طرق تتوزع عليها! لهذا يزداد الازدحام (المقاومة) في التوالي ويقل في التوازي.","concepts":[],"laws":[],"notes":[{"heading":"","items":["واجب بيتي 📝: المقاومتان (3Ω و R) ربطتا على التوالي مع بعضهما ثم ربطتا على طرفي مصدر جهده الكهربائي (12V) فكان التيار المنساب في الدائرة (2A) احسب مقدار: ١- المقاومة المجهولة ٢- فرق الجهد عبر طرفي كل مقاومة ٣- التيار المنساب في كل مقاومة؟"],"ministerial":false},{"heading":"واجبات بيتية 📝:","items":["س١: مقاومتان الاولى (R₁ = 180Ω) والثانية (R₂ = 90Ω) ربطتا على التوازي وربطت المجموعة عبر مصدر فرق جهده (36V) احسب: ١- التيار المار بالمقاومة الاولى ٢- التيار الكلي.","س٢: مقاومتان (R₁ = 9Ω و R₂ = 18Ω) على التوازي عبر (V = 36 volt): احسب ١- المقاومة المكافئة ٢- التيار المار في كل مقاومة.","س٣: مقاومتان (R₁ = 6Ω و R₂ = 12Ω) على التوازي عبر (24V): احسب ١- المقاومة المكافئة ٢- التيار المار في كل مقاومة."],"ministerial":false}],"tables":[],"examples":[{"problem":"سؤال: مقاومتان (4Ω و 8Ω) ربطتا على التوالي مع بعظهما ثم ربطتا الى مصدر فرق جهد كهربائي (24V) احسب مقدار: ١- التيار الكهربائي المنساب في الدائرة. ٢- فرق الجهد الكهربائي على طرفي كل مقاومة","givens":"المعطيات: R₁ = 4Ω — R₂ = 8Ω — Vtotal = 24V","solution_steps":["الخطوة ١: نحسب المقاومة المكافئة: Req = R₁ + R₂ = 4 + 8 = 12 Ω","الخطوة ٢ (المطلب الاول): نحسب التيار: Itotal = Vtotal / Req = 24 ÷ 12 = 2 A","الخطوة ٣ (المطلب الثاني): فرق الجهد على كل مقاومة: V₁ = I × R₁ = 2 × 4 = 8 V\nV₂ = I × R₂ = 2 × 8 = 16 V"],"ministerial":false},{"problem":"سؤال: مقاومتان (4Ω و R) ربطتا على التوالي مع بعضهما على طرفي مصدر فرق جهده الكهربائي (18V) فانساب تيار كهربائي في الدائرة مقداره (3A) احسب: ١- المقاومة R ٢- فرق الجهد على طرفي كل مقاومة؟","givens":"المعطيات: R₁ = 4Ω — Vtotal = 18V — I = 3A","solution_steps":["الخطوة ١: نحسب المقاومة المكافئة: Req = Vtotal / Itotal = 18 ÷ 3 = 6 Ω","الخطوة ٢: نجد R المجهولة: Req = R₁ + R₂ ⟸ 6 = R + 4 ⟸ R = 6 − 4 = 2 Ω","الخطوة ٣: فرق الجهد على كل مقاومة: V₁ = I × R₁ = 3 × 2 = 6 V\nV₂ = I × R₂ = 3 × 4 = 12 V"],"ministerial":false},{"problem":"سؤال: مقاومتان (2Ω و 4Ω) ربطتا على التوالي مع بعظهما ثم ربطتا الى مصدر فرق جهد كهربائي (12V) احسب مقدار: ١- المقاومة المكافئة ٢- التيار الكهربائي المنساب في الدائرة.","givens":"المعطيات: R₁ = 2Ω — R₂ = 4Ω — Vtotal = 12V","solution_steps":["الخطوة ١: Req = R₁ + R₂ = 4 + 2 = 6 Ω","الخطوة ٢: I = Vtotal / Req = 12 ÷ 6 = 2 A"],"ministerial":false},{"problem":"سؤال: ثلاث مقاومات (5Ω و 4Ω و 3Ω) ربطت على التوالي عبر مصدر (24V) — احسب: ١- المقاومة المكافئة ٢- فرق الجهد بين طرفي كل مقاومة","givens":"المعطيات: R₁ = 5Ω — R₂ = 4Ω — R₃ = 3Ω — Vtotal = 24V","solution_steps":["الخطوة ١: Req = R₁ + R₂ + R₃ = 5 + 4 + 3 = 12 Ω","الخطوة ٢: Itotal = Vtotal / Req = 24 ÷ 12 = 2 A","الخطوة ٣: V₁ = 2 × 5 = 10V — V₂ = 2 × 4 = 8V — V₃ = 2 × 3 = 6V"],"ministerial":false},{"problem":"سؤال: ثلاث مقاومات (3Ω ، R ، 4Ω) ربطت على التوالي مع بعضها والمقاومة المكافئة لهما ربطت عبر فرق جهد كهربائي (18V) فانساب تيار كهربائي في الدائرة قدرة (2A) احسب: ١- المقاومة المجهولة R ٢- فرق الجهد الكهربائي على طرفي كل مقاومة.","givens":"المعطيات: R₁ = 4Ω — R₂ = R — R₃ = 3Ω — Vtotal = 18V — I = 2A","solution_steps":["الخطوة ١: Req = Vtotal / Itotal = 18 ÷ 2 = 9 Ω","الخطوة ٢: 9 = 4 + 3 + R ⟸ R = 9 − 7 = 2 Ω","الخطوة ٣: V₁ = 2 × 4 = 8V — V₂ = 2 × 2 = 4V — V₃ = 2 × 3 = 6V"],"ministerial":false},{"problem":"سؤال: مقاومتان (18Ω و 9Ω) ربطتا على التوازي والمقاومة المكافئة لهما مربوطة عبر فرق جهد كهربائي (18V) احسب: ١- المقاومة المكافئة ٢- التيار المنساب في كل مقاومة.","givens":"المعطيات: R₁ = 9Ω — R₂ = 18Ω — Vtotal = 18V","solution_steps":["الخطوة ١: 1/Req = 1/9 + 1/18 = (2+1)/18 = 3/18 = 1/6 ⟸ Req = 6 Ω","الخطوة ٢: I₁ = V₁/R₁ = 18 ÷ 9 = 2 A\nI₂ = V₂/R₂ = 18 ÷ 18 = 1 A"],"ministerial":false},{"problem":"مثال ٣: في الشكل المجاور ثلاث مقاومات (R₁ = 6Ω ، R₂ = 9Ω ، R₃ = 18Ω) والمقاومة المكافئة لها مربوطة عبر فرق جهد كهربائي مقداره (18V) احسب: ١- مقدار المقاومة المكافئة ٢- التيار المنساب في كل مقاومة ٣- التيار الكلي.","givens":"المعطيات: R₁ = 6Ω — R₂ = 9Ω — R₃ = 18Ω — Vtotal = 18V","solution_steps":["الخطوة ١: 1/Req = 1/6 + 1/9 + 1/18 = (3+2+1)/18 = 6/18 = 1/3 ⟸ Req = 3 Ω","الخطوة ٢: I₁ = 18 ÷ 6 = 3A — I₂ = 18 ÷ 9 = 2A — I₃ = 18 ÷ 18 = 1A","الخطوة ٣: Itotal = Vtotal / Req = 18 ÷ 3 = 6 A\nوهناك طريقة اخرى لحساب التيار الكلي هي: Itotal = I₁ + I₂ + I₃ = 3 + 2 + 1 = 6 A"],"ministerial":false},{"problem":"سؤال: من الشكل المجاور (R₁ = 6Ω ، R₂ = 3Ω مربوطتان على التوازي عبر V = 12 volt) احسب مقدار: ١- المقاومة المكافئة ٢- التيار المنساب في كل مقاومة ٣- التيار الكلي المنساب في الدائرة؟","givens":"المعطيات: R₁ = 6Ω — R₂ = 3Ω — Vtotal = 12V","solution_steps":["الخطوة ١: 1/Req = 1/6 + 1/3 = (1+2)/6 = 3/6 = 1/2 ⟸ Req = 2 Ω","الخطوة ٢: I₁ = V₁/R₁ = 12 ÷ 6 = 2A — I₂ = V₂/R₂ = 12 ÷ 3 = 4A","الخطوة ٣: Itotal = I₁ + I₂ = 2 + 4 = 6 A"],"ministerial":false}],"qa":[{"type":"قوانين","question":"عند ربط مقاومتان او اكثر مع بعضهما على التوالي فان:","answer":"١. للدائرة الكهربائية مسرب واحد لانسياب التيار الكهربائي وبالتالي يكون التيار متساوي بكل اجزاء الدائرة: Itotal = I₁ = I₂ = I₃\n٢. فرق الجهد الكلي للدائرة (Vtotal) يساوي مجموع فروق الجهد عبر طرفي كل مقاومة: Vtotal = V₁ + V₂ + V₃\n٣. تزداد المقاومة المكافئة (Req) كلما زاد عدد المقاومات المربوطة على التوالي ويقل التيار المار في الدائرة: Req = R₁ + R₂ + R₃","ministerial":false},{"type":"ملاحظات","question":"بعض الملاحظات على حل مسائل ربط التوالي","answer":"- اذا كان التيار الكلي مجهول (تيار الدائر) يمكن ايجاده من القوانين التالية: Itotal = I₁ = I₂ = I₃ او R = V / I\n- اذا كان فرق الجهد الكهربائي الكلي مجهول يمكن ايجادها من القوانين التالية: Vtotal = Itotal × Req او Vtotal = V₁ + V₂ + V₃\n- اذا فرق الجهد لأي مقاومة مجهول فيحسب من خلال ضرب قيمة تلك المقاومة في التيار المار فيها.\n- اذا كانت المقاومة المكافئة Req مجهولة فتحسب من خلال القوانين التالية: Req = R₁ + R₂ + R₃ او Req = Vtotal / Itotal\n- اذا جاء في السؤال عبارة قراءة الأميتر او التيار المنساب في الدائرة فهذا يعتبر تيار كلي واذا جاءت عبارة قراءة الفولتميتر او المقاومة المكافئة ربطت عبر مصدر فرق جهده فتعتبر فولطية كلية.\n- يمكن معرفة ربط التوالي من خلال منطوق السؤال حيث يذكر فيه كلمة توالي او من خلال رسم الدائرة.","ministerial":false},{"type":"قوانين","question":"ربط المقاومات على التوازي (يوجد اكثر من مسرب لمرور التيار)","answer":"يمكن معرفة ربط التوازي من خلال منطوق السؤال حيث يذكر فيه كلمة توازي او من خلال الرسم (يوجد اكثر من مسرب لمرور التيار).\n\n- اذا كان التيار الكلي (Itotal) مجهول فيمكن ايجاده من خلال القوانين التالية: Itotal = Vtotal / Req او Itotal = I₁ + I₂ + I₃\n- اذن كان فرق الجهد الكلي (Vtotal) مجهول فيمكن ايجاده من خلال: Vtotal = V₁ = V₂ = V₃ او Vtotal = Itotal × Req\n- اذا كانت المقاومة المكافئة (Req) مجهولة يمكن ايجاده من احد القوانين التالية: 1/Req = 1/R₁ + 1/R₂ + 1/R₃ او Req = Vtotal / Itotal\n- اذا طلب في السؤال تيار كل مقاومة نستخدم القوانين التالية: I₁ = Vtotal / R₁ ، I₂ = Vtotal / R₂ ، I₃ = Vtotal / R₃","ministerial":false},{"type":"سؤال","question":"ماذا يحصل لمقدار المقاومة المكافئة عند ربط المقاومات أولا: على التوالي، ثانيا: على التوازي؟","answer":"أولا: عند ربط المقاومات على التوالي يزداد مقدار المقاومة المكافئة كلما ازدادت عدد المقاومات.\nثانيا: ربط المقاومات على التوازي تقل قيمة المقاومة المكافئة كلما زادت عدد المقاومات.","ministerial":true}],"has_simulation":true,"simulation_title":"🧪 مختبر ربط المقاومات"},{"chapter_number":3,"chapter_title":"🔌 الفصل الثالث: التيار الكهربائي","lesson_number":8,"lesson_title":"🏠 الدرس 8: ربط المصابيح والخلايا والدائرة القصيرة","order_index":8,"hook":"زينة رمضان القديمة: إذا انطفأ مصباح واحد انطفأ الشريط كله! لأنها مربوطة على التوالي... أما مصابيح بيتك فعلى التوازي — كل مصباح مستقل.","concepts":[{"term":"الدائرة القصيرة:","text":"هي جزء من دائرة كهربائية مقفلة تكون مقاومتها أصغر من أي جزء من الدائرة الكهربائية فيمر معظم التيار الكهربائي فيها عندما تكون جزءا من دائرة كهربائية اكبر.","ministerial":false}],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"نشاط","question":"لديك ثلاث مصابيح صغيرة و متماثلة وضح بنشاط ربط هذه المصابيح على التوالي وماذا تستنتج؟","answer":"الأدوات: ١- ثلاث مصابيح (a, b, c) صغيرة متماثلة ٢- بطارية فولطياتها مناسبة ٣- أسلاك توصيل ٤- مفتاح كهربائي.\nالخطوات:\n١. نربط أحد المصابيح الثلاثة على التوالي مع المفتاح والبطارية نغلق المفتاح ونلاحظ توهج المصباح.\n٢. نربط مصباحين من المصابيح ثلاثة على التوالي مع بعضهما ومع المفتاح في البطارية.\n٣. نغلق الدائرة ونلاحظ توهج المصباحين نجد أن توهجهما متساوي و توهج كل منهما أقل من توهج المصباح لو ربط لوحده.\n٤. نكرر العملية وذلك بربط المصابيح الثلاثة بواسطة اسلال التوصيل مع بعضها والمفتاح الكهربائي على التوالي ثم نغلق الدائرة سنجد أن مقدار توهج المصابيح الثلاثة متساوي وتوهج كل منهما أقل مما عليه في الحالة السابقة.\nالاستنتاج: نستنتج من النشاط أن تيار الدائرة المتوالية الربط يكون متساوي في جميع أجزائها و يقل مقداره بازدياد عدد المصابيح المربوطة على التوالي بسبب ازدياد مقدار المقاومة المكافئة لمجموعة التوالي.","ministerial":false},{"type":"سؤال","question":"عنده زيادة عدد المصابين المربوطة مع بعضها على التوالي بين قطبي البطارية في دائرة كهربائية هل يزداد ام يقل أم يتساوى مقدار التيار المنساب في جميع المصابيح؟ وضح ذلك؟","answer":"يقل مقدار التيار بزياد عدد المصابيح المربوطة على التوالي بسبب ازدياد مقدار المقاومة المكافئة لمجموعة التوالي.","ministerial":true},{"type":"علل","question":"انطفاء المصابيح المربوطة على التوالي عند عطب أو إزالة احد المصابيح منها؟","answer":"عند عطب (تلف) أو رفع احد المصابيح فإن المصابيح الأخرى المربوطة على التوالي سوف تنطفئ (لا تتوهج) وسبب ذلك لأنه سوف ينساب التيار نفسه من مصباح إلى اخر أي يوجد مسرب واحدة لحركة الشحنات إلى الدائرة الكهربائية.","ministerial":false},{"type":"نشاط","question":"لديك ثلاث مصابيح صغيرة و متماثله وضح بنشاط ربط هذه المصابيح على التوازي؟ وماذا تستنتج؟","answer":"الأدوات: ١- ثلاث مصابيح (a,b,c) صغيره ومتماثلة ٢- بطارية ،اسلاك توصيل ٣- مفتاح كهربائي.\nالخطوات:\n١. نربط احد المصابيح الثلاثة على التوالي مع المفتاح والبطارية، نغلق المفتاح، ونلاحظ توهج المصباح.\n٢. نربط مصباحين من المصابيح ثلاثة على التوازي مع بعضهما نربط مجموعتها على التوالي مع المفتاح و البطارية.\n٣. نغلق المفتاح ونلاحظ توهج المصباحين نجد أن توهجهما متساوي ويماثل توهج المصباح في الحالة الأولى.\n٤. نربط المصابيح الثلاثة بواسطة أسلاك توصيل مع بعضهما على التوازي ونربط مجموعة مصابيح على التوالي مع المفتاح.\n٥. نربط طرفي المجموعة الكلية (المصابيح والمفتاح) بين قطبي البطارية.\n٦. نغلق مفتاح الدائرة ونلاحظ توهج المصباح نجد أن مقدار توهج المصباح متساوي ويماثل توهج المصباح في الحالة الأولى والثانية.\nالاستنتاج: أن فرق الجهد عبر أجزاء الدائرة المتوازية الربط يكون متساوي و يساوي مجموع التيارات المارة في المصابيح في الدائرة والذي يزداد مقداره بزيادة عدد المصابيح المربوطة على التوازي وأن المقاومة المكافئة في دائرة التوازي تقل بزيادة عدد المصابيح المقاومات المربوطة على التوازي.","ministerial":false},{"type":"سؤال","question":"ما هي مميزات ربط المصابيح على التوازي؟ ما الفائدة العملية من ربط المصابيح والأجهزة الكهربائية المنزلية على التوازي؟","answer":"١. لتشغيل الاجهزة الكهربائية جميعها بفرق جهد واحد.\n٢. لتشغيل كل جهاز كهربائي او مصباح بشكل مستقل عن الاخر في تيار يناسب اشتغاله.\n٣. عند رفع أو عطب أي جهاز لا يسبب قطع التيار عن بقية الاجهزة.\n٤. عند اضافة أجهزة أخرى إلى الدائرة الكهربائية تقل المقاومة المكافئة للدائرة و يزداد تيارها الرئيسي.","ministerial":true},{"type":"سؤال","question":"لماذا يفضل ربط المصابيح والأجهزة الكهربائية في الدوائر الكهربائية في المنازل على التوازي؟","answer":"١. لتشغيل الأجهزة الكهربائية جميعها بفرق جهد واحد (فولطية الخط).\n٢. لتشغيل كل جهاز كهربائي او مصباح بشكل مستقل عن الاخر بتيار يناسب اشتغاله.\n٣. حين رفع او عطب اي جهاز لا يسبب قطع التيار عن بقيه الأجهزة بينما في ربط التوالي تصير الدائرة الكهربائية في المنزل مفتوحه.\n٤. عند اضافه اجهزه اخرى الى دائرة التوازي تقل المقاومة المكافئة للدائرة ويزداد تيارها الرئيسي بينما في ربط التوالي تزداد المقاومة الكلية للدائرة (المكافئة) ويقل تيارها الرئيسي في الأجهزة جميعها وهذا لا يناسب اشتغالها جميعا وربما تعطب بعض الأجهزة.","ministerial":true},{"type":"علل","question":"عنده ربط مصباحين متساويين بمقاومتها الكهربائية على التوالي إلى مصدر فرق جهد كهربائي (بطارية) وربط سلك موصل مقاومته صغيرة جدا بين طرفي أحد مصباحين نلاحظ أن المصباح الآخر يزداد توهجه؟ ما سبب ذلك","answer":"لأن السلك المربوط إلى طرفي المصباح ولد دائرة قصيره مرة فيها معظم التيار فتقبل بذلك المقاومة الكهربائية المكافئة فيزداد مقدار التيار المنساب في المصباح الثاني وكذلك يزداد التوهج.","ministerial":false},{"type":"علل","question":"اذا ربطنا سلكاً موصلاً غليظا بين طرفي أحد المصباحين في دائرة كهربائية تحتوي على بطارية مصباحين نلاحظ انطفاء هذا المصباح؟","answer":"وذلك لان السلك الغليظ ولد دائرة قصيرة للمصباح فجعل معظم التيار ينساب في السلك الغليظ (مقاومة صغيرة) والجزء القليل جدا من التيار ينساب في المصباح فلا يكفي لتوهجه.","ministerial":false},{"type":"نشاط","question":"وضح مع الرسم كيف تنشأ في المختبر دائرة قصيرة؟","answer":"نحضر مصباحين كهربائيين متساويين في المقاومة ونربطهما على التوالي مع مصدر للفولطية (بطارية) نلاحظ توهجهما. بعد ذلك نربط سلك غليظ بين طرفي احد المصباحين نلاحظ انطفاء هذا المصباح بسبب إن السلك الغليظ ولد دائرة قصيرة جعل معظم التيار ينساب فيه.","ministerial":false},{"type":"سؤال","question":"اذكر مميزات ربط الخلايا الكهربائية على التوالي مع الرسم؟ و ما الغرض منه؟","answer":"١. يتم ربط القطب الموجب للخلية الأولى مع القطب السالب للخلية الثانية وهكذا مع بقية الخلايا.\n٢. تجهز الدائرة بقوة دافعة كهربائية كبيرة (emf).\n٣. يكون مقدار التيار الكلي هو تيار بطارية واحدة.","ministerial":true},{"type":"سؤال","question":"اذكر مميزات ربط الخلايا الكهربائية على التوازي مع الرسم؟ و ما الغرض منه؟","answer":"١. تربط الأقطاب الموجبة مع بعض وسالبة مع بعض إلى الدائرة الكهربائية.\n٢. تجهز الدائرة الكهربائية بتيار اكبر.\n٣. تكون الفولطية الكلية هي فولطية بطارية واحدة.","ministerial":true},{"type":"سؤال","question":"لديك ثلاثة أعمدة كهربائية emf لكل منهما (1.5 V) كيف يتم ربطها للحصول على (4.5 V) مرة و (1.5 V) مرة أخرى كقوة دافعة كهربائية كلية وضح ذلك مع الرسم؟","answer":"يتم الحصول على (4.5 V) عند ربط هذه الأعمدة على التوالي وذلك لانه ربط الاعمدة على التوالي يساوي مجموع الفولطيات الخلايا: Vtotal = V₁ + V₂ + V₃ = 1.5 + 1.5 + 1.5 = 4.5 V\nويتم الحصول على (1.5 V) عند ربط الأعمدة على التوازي لانه في ربط التوازي سيكون الفولطية الكلية هي نفسها فولطية البطارية الواحدة: Vtotal = V₁ = V₂ = V₃ = 1.5 V","ministerial":true}],"has_simulation":true,"simulation_title":"🧪 مختبر المصابيح: توالي أم توازي؟"},{"chapter_number":4,"chapter_title":"🔋 الفصل الرابع: البطارية والقوة الدافعة الكهربائية","lesson_number":1,"lesson_title":"🍋 الدرس 1: ما البطارية؟ وكيف تصنع؟","order_index":1,"hook":"موبايلك، ساعتك، سيارة أبيك، وحتى الغواصات العملاقة... كلها تعمل بنفس الفكرة: تفاعل كيميائي يتحول إلى طاقة كهربائية!","concepts":[{"term":"البطارية:","text":"هي مصدر لإنتاج الطاقة الكهربائية عن طريق التفاعل الكيميائي.","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["في بطارية الليمون: النحاس قطب موجب (+) والمسمار المغلون قطب سالب (−)، والمحلول الحامضي في الليمون هو الذي يطلق الإلكترونات من المسمار نحو النحاس.","في الخلية البسيطة يتولد فرق جهد حوالي فولط واحد لأن جهد النحاس اكبر من جهد الخارصين.","الكلفانومتر يتحسس التيارات صغيرة المقدار ورمزه G."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما البطارية؟ ومما تتكون؟ وما اشكالها؟ و كيف تصنع؟","answer":"البطارية: هي مصدر لإنتاج الطاقة الكهربائية عن طريق التفاعل الكيميائي.\nمكوناتها: تتكون من خلية كهربائية واحده او اكثر تحتوي الخلية الواحدة على مواد كيميائية تمكنها من توليد تيار كهربائي.\nاشكالها: تصنع بأشكال واحجام مختلفة فمنها صغير الحجم مثل بطاريه الساعة اليدوية ومنها كبيره الحجم مثل البطاريات التي تغذي الغواصات بالطاقة.","ministerial":false},{"type":"نشاط","question":"اشرح نشاط توضح فيه كيفيه عمل بطاريه الليمون؟","answer":"الادوات: ١. مقياس للتيار الكهربائي (ملي اميتر) ٢. مسمار مغلون ٣. قطعه من النحاس ٤. حبه ليمون حامض ٥. اسلاك توصيل.\nالعمل:\n١. نغرس المسمار المغلون وقطعه النحاس في الليمون.\n٢. يعمل النحاس كقطب كهربائي موجب والمسمار المغلون كقطب كهربائي سالب يؤدي الى تولد فرق الجهد بين القطبين.\n٣. نوصل القطبين بسلكي توصيل الى طرفي مقياس التيار الكهربائي نلاحظ انحراف مؤشر المقياس وهذا دلاله على انسياب تيار كهربائي في الدائرة الخارجية نتيجة انطلاق الالكترونات من المسمار بتأثير المحلول الحامضي متجه نحو النحاس.","ministerial":false},{"type":"نشاط","question":"اشرح نشاط توضح فيه تحويل الطاقة الكيميائية إلى كهربائية؟ او وضح بنشاط عمل الخلية البسيطة.","answer":"الادوات: ١. صفيحه من النحاس ٢. صفيحه من الخارصين ٣. وعاء من الزجاج يحتوي على حامض الكبريتيك المخفف ٤. كلفانوميتر حساس ٥. اسلاك توصيل.\nالعمل:\n١. نضع صفيحتا النحاس والخارصين داخل وعاء الزجاج الحاوي على حامض الكبريتيك المخفف.\n٢. نصل الصفيحتين بسلكي توصيل الى طرفي جهاز الكلفانوميتر.\n٣. نلاحظه انحراف مؤشر الكلفانوميتر دلاله على انسياب تيار كهربائي في الدائرة.\nالاستنتاج: الخلية الكهربائية البسيطة عباره عن صفحتين معدنين مختلفين مثل النحاس والخارصين يتولد بينهما فرق جهد كهربائي يقدر حوالي فولطا واحدا اذ ان جهد النحاس اكبر من جهد الخارصين ونتيجة لذلك تتولد طاقه كافيه تسمح بانسياب تيار كهربائي عند ربطها بدائرة خارجية.","ministerial":false},{"type":"سؤال","question":"عرف الخلية الكهربائية البسيطة؟","answer":"هي عباره عن صفحتين من معدنين مختلفين مثل النحاس والخارصين يتولد بينها فرق جهد كهربائي يقدر حوالي فولطا واحدا اذ ان جهد النحاس اكبر من جهد الخارصين ونتيجة لذلك تتولد طاقه كافيه تسمح بانسياب تيار كهربائي عند ربطها بدائرة خارجيه.","ministerial":true},{"type":"سؤال","question":"ما جهاز الكلفانومتر؟","answer":"جهاز الكلفانومتر: هو جهاز يتحسس التيارات الكهربائية صغيره المقدار ويرمز له بالرمز G.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 نفّذ النشاط بنفسك: بطارية الليمون"},{"chapter_number":4,"chapter_title":"🔋 الفصل الرابع: البطارية والقوة الدافعة الكهربائية","lesson_number":2,"lesson_title":"🗂️ الدرس 2: تصنيف البطاريات وخلية دانيال","order_index":2,"hook":"لماذا نرمي بطارية جهاز التحكم عندما تفرغ، لكن بطارية الموبايل نشحنها من جديد كل يوم؟ الجواب في تصنيف البطاريات!","concepts":[{"term":"البطارية الأولية:","text":"هي نوع من الخلايا البسيطة وتتميز بانها ينتهي مفعولها بعد استهلاك احد المواد المكونة لها ولا يمكن اعاده شحنها مثل خلية دانيال والخلية الكلفانية البسيطة و الخلية الجافه (كاربون خارصين).","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["الخلية الكلفانية البسيطة هي بطاريه اوليه.","تخزن الطاقة الكهربائية في البطارية الاولية بشكل طاقه كيميائية، واساس عملها تحويل الطاقة الكيميائية الى طاقه كهربائية."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"تصنف البطاريات الى ثلاثة انواع اذكرها؟","answer":"١. البطارية الأولية مثل (خلية دانيال والخلية الكلفانية البسيطة و الخلية الجافه).\n٢. البطارية الثانوية مثل (بطاريه السيارة وبطارية ايون - الليثيوم).\n٣. بطاريه الوقود مثل (بطاريه وقود الهيدروجين).","ministerial":false},{"type":"سؤال","question":"ما هي العوامل التي من خلالها يتم تصنيف البطاريات الى انواع مختلفة؟","answer":"١. تصنف حسب المواد الكيميائية الداخلة في تركيبها.\n٢. تصنف حسب امكانياته شحنها.","ministerial":false},{"type":"سؤال","question":"ما البطارية الأولية وما مميزاتها؟","answer":"البطارية الأولية: هي نوع من الخلايا البسيطة وتتميز بانها ينتهي مفعولها بعد استهلاك احد المواد المكونة لها ولا يمكن اعاده شحنها مثل خلية دانيال والخلية الكلفانية البسيطة و الخلية الجافه (كاربون خارصين).","ministerial":false},{"type":"سؤال","question":"ما نوع الطاقة المخزونة في البطارية الأولية ؟","answer":"تخزن الطاقة الكهربائية في البطارية الاولية بشكل طاقه كيميائية.","ministerial":false},{"type":"سؤال","question":"ما اساس عمل البطارية الأولية ؟","answer":"تحويل الطاقة الكيميائية الى طاقه كهربائية.","ministerial":false},{"type":"سؤال","question":"مم تتكون الخلية البسيطة (خليه دانيال)؟ و ماذا يحصل داخل الخلية؟","answer":"تتكون من نصفين خليتين يغمر كل واحده منها لوح معدني احدهما من الخارصين والاخر من النحاس ويغمر كل منهما في محلول لاحد املاحه.\nيحصل داخل الخلية: هو ان ذرات المعدن تترك الالكترونات على اللوح و تدخل المحلول على هيئه ايونات موجبه.","ministerial":false},{"type":"سؤال","question":"ما فائدة الجسر الملحي في الخلية الكلفانية البسيطة؟","answer":"١. يربط محلولي الإناءين بشكل غير مباشر.\n٢. تساعد على هجره الايونات الموجبة والسالبة.","ministerial":false},{"type":"سؤال","question":"ما مميزات الخلية الكلفانية البسيطة (خليه دانيال) ؟","answer":"١. من البطاريات الأولية.\n٢. لا يمكن اعاده شحنها.\n٣. الوسط الكيميائي هو محلول لاحد املاح اللوحين.","ministerial":false},{"type":"سؤال","question":"ما هو الوسط الكيميائي الداخل في تركيب الخلية الكلفانية البسيطة؟","answer":"وسط كيميائي سائل عباره عن كبريتات الخارصين وكبريتات النحاس.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 شاهد خلية دانيال وهي تعمل"},{"chapter_number":4,"chapter_title":"🔋 الفصل الرابع: البطارية والقوة الدافعة الكهربائية","lesson_number":3,"lesson_title":"🔦 الدرس 3: الخلية الجافة (كاربون – خارصين)","order_index":3,"hook":"لماذا تسمى «جافة» مع أن فيها مواد كيميائية؟ لأن وسطها ليس سائلاً بل عجينة! لهذا لا تنسكب مهما قلبتها.","concepts":[],"laws":[],"notes":[{"heading":"","items":["عند حصول التفاعلات الكيميائية داخل الخلية الجافه سوف يتولد فرق جهد بين طرفي الخلية مقداره 1.5 volt.","القطب الموجب: عمود الكاربون — القطب السالب: وعاء الخارصين."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما مكونات الخلية الجافه؟","answer":"١. قطب موجب من الكاربون.\n٢. قطب سالب من الخارصين.\n٣. يحاط العمود بعجينه الكترونيه (عبارة عن كلوريد الخارصين وكلوريد الامونيوم وثاني أوكسيد المنغنيز ومسحوق الكاربون والماء).","ministerial":false},{"type":"سؤال","question":"مم يتكون القطب الموجب للخلية الجافه وكذلك قطبها السالب؟","answer":"يتكون القطب الموجب من عمود من الكربون محاط بعجينه الكتروليتية.\nيتكون القطب السالب من وعاء من الخارصين.","ministerial":false},{"type":"سؤال","question":"ما هو نوع الوسط الكيميائي الداخل في تركيب البطارية الجافة (خارصين_كربون)؟ وما هي مكوناته؟","answer":"وسط كيميائي صلب عباره عن عجينه الكتروليتية تتكون من كلوريد الامونيوم و كلوريد الخارصين والماء وثاني اوكسيد المنغنيز ومسحوق الكاربون.","ministerial":false},{"type":"سؤال","question":"اذكر اربعه اجهزه تستعمل فيها البطارية الجافه؟","answer":"١. كشافات الضوء اليدوية.\n٢. وحده توليد النبضات الكهربائية لأجهزه السيطرة عن بعد.\n٣. في الات التصوير.\n٤. لعب الاطفال الكهربائية.","ministerial":true},{"type":"سؤال","question":"ما مميزات الخلية الجافه (بطاريه كاربون_خارصين)؟","answer":"١. بطاريه اولية.\n٢. لا يمكن اعاده شحنها.\n٣. ينتهي مفعولها بأنتهاء أحد المواد الكيميائية فيها.\n٤. تستعمل في الات التصوير و لعب الاطفال الكهربائية.\n٥. الوسط الكيميائي عجينه الكترونيه.","ministerial":false},{"type":"علل","question":"يفضل خزن العمود الجاف في مكان بارد؟","answer":"لتقليل التفاعلات الكيميائية داخل الخلية الجافه.","ministerial":true},{"type":"علل","question":"لماذا لا يمكن سحب كميه عالية من التيار في فتره زمنيه قصيره من الخلية الجافه ؟","answer":"لأنه يقصر من عمر الخلية.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 استكشف أجزاء الخلية الجافة"},{"chapter_number":4,"chapter_title":"🔋 الفصل الرابع: البطارية والقوة الدافعة الكهربائية","lesson_number":4,"lesson_title":"🚗 الدرس 4: البطارية الثانوية وبطارية السيارة","order_index":4,"hook":"السر كله في عكس اتجاه التيار: عند التفريغ تتحول الطاقة الكيميائية إلى كهربائية، وعند الشحن نعكس العملية فتُخزن الطاقة كيميائياً من جديد!","concepts":[{"term":"البطارية الثانوية:","text":"هي نوع من البطاريات الكهربائية التي يمكن اعاده شحنها و اثناء عملها تتفاعل المواد الكيميائية التي تحتويها تتحول الطاقة الكيميائية المخزونة فيها الى طاقه كهربائية. ولإعادة شحنها يطلب امرار تيار كهربائي في الاتجاه المعاكس لتيار التفريغ وذلك لتحويل الطاقة الكهربائية الى طاقه كيميائية تخزن في البطارية من امثلتها بطاريه السيارة و بطاريه (ايون_ الليثيوم).","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["عند شحن بطاريه السيارة (البطارية الثانوية) تتحول الطاقة الكهربائية الى طاقه كيميائية مخزونه في البطارية.","بطاريه السيارة تتكون من ستة خلايا مربوطة على التوالي لذلك يكون مقدار فرق الجهد هو 12 V عندما تكون تامة الشحن."],"ministerial":false}],"tables":[{"caption":"ما الفرق بين البطارية الأولية والبطارية الثانوية؟","headers":["البطارية الأولية","البطارية الثانوية"],"rows":[["نوع من الخلايا البسيطة وينتهي مفعولها بعد استهلاك احد المواد الكيميائية المكونة لها","هي نوع من البطاريات الكهربائية"],["لا يمكن اعاده شحنها مثل الخلية الكلفانية البسيطة و الخلية الجافه","يمكن اعاده شحنها ومن امثلتها بطاريه السيارة و بطاريه (ايون_ الليثيوم)"]],"ministerial":false}],"examples":[],"qa":[{"type":"سؤال","question":"ما نوع الطاقة المخزونة في البطارية الثانوية؟","answer":"تخزن الطاقة الكهربائية في البطارية الثانوية بشكل طاقه كيميائية.","ministerial":false},{"type":"سؤال","question":"ما مميزات البطارية الثانوية؟","answer":"١. يمكن اعاده شحنها.\n٢. تتحول فيها الطاقة الكيميائية المخزونة فيها الى طاقه كهربائيه.","ministerial":false},{"type":"قارن","question":"ما الفرق بين البطارية الأولية والبطارية الثانوية؟","answer":"","ministerial":false},{"type":"قارن","question":"ما الفرق بين البطارية الأولية والبطارية الثانوية من حيث الوسط الكيميائي الداخل في كل منها؟","answer":"١. في البطارية الأولية عجينه الكتروليتية من كلوريد الامونيوم و كلوريد الخارصين وماء وثاني اكسيد المنغنيز و مسحوق الكربون.\n٢. في البطارية الثانوية محلول الكتروليتي يتكون من حمض الكبريتيك و ماء مقطر.","ministerial":false},{"type":"علل","question":"لا يفضل خزن البطارية الثانوية لفتره طويله؟","answer":"لان خزنها لفتره طويله يؤدي الى تكوين طبقه عازله على الواحها وبالتالي تقل كفاءتها.","ministerial":false},{"type":"سؤال","question":"كيف يمكن تفريغ البطارية الثانوية ؟","answer":"عن طريق سحب تيار من البطارية حيث تتحول الطاقة الكيميائية المخزونة فيها الى طاقه كهربائية.","ministerial":false},{"type":"سؤال","question":"ما هي بطارية السيارة؟ مم تتكون؟","answer":"بطارية السيارة: هي نوع من انواع البطاريات الكهربائية التي يمكن اعاده شحنها تعمل على بدء تشغيل محرك السيارة. تتركب من:\n١. وعاء مصنوع من البلاستيك او المطاط الصلب.\n٢. تحتوي على (6 - 3) خلايا كل واحده منها تتركب من صفائح يحيط بها محلول الكتروليتي يتكون من حامض الكبريتيك و ماء مقطر كثافته النسبية (1.3) عندما تكون تامة الشحن.\n٣. قطب موجب (الواح اوكسيد الرصاص) وقطب سالب (الواح الرصاص) وكلاهما مغمور في محلول حامض الكبريتيك.","ministerial":false},{"type":"علل","question":"يجب ربط بطاريه السيارة باسلاك توصيل غليظة؟","answer":"لان بطاريه السيارة تعطي تيارا كهربائيا عاليا.","ministerial":false},{"type":"علل","question":"بطاريه السيارة المكونة من 6 خلايا مربوطة مع بعضها على التوالي تعطي (12v) عندما تكون تامه الشحن؟","answer":"لان كل خليه من خلايا الرصاص الحامضية تولد فرق جهد قدره (2 volt) لذلك البطارية تعطي (12 volt) عندما تكون تامه الشحن.","ministerial":true},{"type":"سؤال","question":"ما مميزات بطاريه السيارة؟","answer":"١. يمكن اعاده شحنها.\n٢. يمكن سحب تيار عالي منها لفترة زمنية قصيرة.\n٣. تعمل على بدء تشغيل محرك السيارة.","ministerial":false},{"type":"سؤال","question":"كيف تتم عمليه شحن بطاريه السيارة؟ وضح بالرسم دائرة شحن بطاريه السيارة؟","answer":"١. نربط البطارية بمصدر تيار مستمر (شاحنه) ونصل القطب الموجب للمصدر الشاحن مع القطب الموجب للبطارية و القطب السالب لمصدر الشاحن مع القطب السالب للبطارية المراد شحنها.\n٢. ان مقدار القوه الدافعة الكهربائية (emf) لبطارية السيارة (12 v) وعند شحنها بمصدر الشاحن يجب ان يكون مقداره اكبر بقليل من مقدار القوه الدافعة للبطارية حوالي (14 v).\n٣. ترفع الأغطية البلاستيكية للبطارية في اثناء عمليه شحن البطارية للتخلص من الغازات المتولدة نتيجة التفاعلات الكيميائية التي تحصل داخلها.","ministerial":true},{"type":"علل","question":"لماذا تكون فولتيه المصدر الشاحن لبطارية السيارة اكبر مقدار من فولتيه البطارية؟","answer":"اخذين بعين الاعتبار الجهد الضائع في المقاومة الداخلية للبطارية واسلاك التوصيل.","ministerial":false},{"type":"علل","question":"ترفع الأغطية البلاستيكية لبطارية السيارة اثناء عمليه شحنها؟","answer":"للتخلص من الغازات المتولدة نتيجة للتفاعلات الكيميائية التي تحصل داخلها.","ministerial":false},{"type":"سؤال","question":"ما الذي يحصل عند عمليه شحن بطاريه السيارة؟","answer":"تتحول الطاقة الكهربائية من مصدر الشاحن الى طاقه كيميائية مخزونه داخل البطارية.","ministerial":false},{"type":"سؤال","question":"ما الاجراءات اللازم اتخاذها للعناية ببطاريه السيارة؟","answer":"١. عدم سحب تيار عالي.\n٢. مستوى المحلول الحامضي اعلى من مستوى صفائح البطارية بقليل مع المحافظة على الكثافة النسبية للمحلول بنسبه 1.3 تقريبا.\n٣. عدم ترك البطارية من دون استعمال.","ministerial":true},{"type":"علل","question":"عدم ترك البطارية الحامضية (بطاريه السيارة) لمده طويله من غير استعمال؟","answer":"لان ذلك يؤدي الى تكوين طبقه عازله من الكبريتات على الواحها.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 نفّذ النشاط بنفسك: اشحن بطارية السيارة"},{"chapter_number":4,"chapter_title":"🔋 الفصل الرابع: البطارية والقوة الدافعة الكهربائية","lesson_number":5,"lesson_title":"📱 الدرس 5: بطارية أيون الليثيوم","order_index":5,"hook":"اتركها شهراً كاملاً دون استعمال فتفقد 5% فقط من شحنتها... بينما الجافة تفقد 20%! هذا أحد أسرار تفوقها.","concepts":[{"term":"بطارية (ايون_الليثيوم):","text":"هي بطاريه ثانوية يمكن اعاده شحنها لمرات عده و لها فوائد كثيره منها تشغيل الحاسوب النقال _ الموبايل _ الكاميرات _ تشغيل الموسيقى.","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["القطب الموجب من اوكسيد كوبلت الليثيوم والقطب السالب من الكربون — لاحظ الفرق عن الخلية الجافة!","المحلول الالكتروليتي من مادة الايثر تغمر فيه الشرائح الثلاث: القطب الموجب، العازل، القطب السالب."],"ministerial":false}],"tables":[{"caption":"قارن بين بطاريه (ايون _الليثيوم) و البطارية الجافه ؟","headers":["بطارية (ايون _الليثيوم)","البطارية الجافة"],"rows":[["بطاريه ثانويه","بطاريه اوليه"],["يمكن اعاده شحنها","لا يمكن اعاده شحنها"],["تحتوي على عازل يفصل بين القطب الموجب والقطب السالب","لا تحتوى على عازل"],["ذات وسط سائل الكتروليتي","ذات وسط جاف"],["تفقد (٥%) من شحنتها في الشهر في حاله عدم الاستعمال","تفقد (٢٠%) من شحنتها في الشهر في حاله عدم استعمالها"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"ما مكونات بطاريه (ايون_ الليثيوم) ؟","answer":"١. غلاف متين يتحمل الضغط العالي والحرارة المتولدة.\n٢. قطب موجب (مصنوع من اوكسيد كوبلت الليثيوم).\n٣. العازل: مصنوع من البلاستيك يعزل القطب الموجب عن القطب السالب ويسمح لمرور الايونات من خلاله.\n٤. قطب سالب (مصنوع من الكربون).\n٥. محلول الكتروليتي من مادة الايثر تغمر فيه الشرائح (القطب الموجب، العازل، القطب السالب).","ministerial":true},{"type":"سؤال","question":"ما مميزات بطاريه (ايون _الليثيوم) ؟","answer":"١. بطاريه ثانويه يمكن اعاده شحنها مرات عده دون ان تستهلك.\n٢. لها القابلية بالاحتفاظ بالشحنة اكثر من اي بطاريه.\n٣. في حاله عدم استعمالها تفقد من شحنتها (٥%) بالشهر بالمقارنة مع البطارية الجافه التي تفقد من شحنتها (٢٠%) بالشهر.\n٤. تصنع بأشكال واحجام مختلفة.","ministerial":false},{"type":"سؤال","question":"ما اساس عمل بطاريه (ايون_الليثيوم)؟","answer":"اساس عملها التفاعلات الكيميائية فهي تحول الطاقة الكيميائية الى طاقه كهربائية.","ministerial":false},{"type":"سؤال","question":"ما الفائدة العملية من استخدام بطاريه ايون الليثيوم؟","answer":"١. تستخدم في اجهزه الحاسب النقال.\n٢. تستخدم في اجهزه الموبايل.\n٣. تستخدم في اجهزه تشغيل الموسيقى.\n٤. تستخدم في الكاميرات.","ministerial":false},{"type":"سؤال","question":"ما الفائدة العملية من وجود العازل في بطاريه ايون الليثيوم؟","answer":"يعمل على عزل القطب الموجب عن القطب السالب داخل البطارية وكذلك يسمح للأيونات المرور من خلاله.","ministerial":true},{"type":"قارن","question":"قارن بين بطاريه (ايون _الليثيوم) و البطارية الجافه ؟","answer":"","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 استكشف طبقات بطارية أيون الليثيوم"},{"chapter_number":4,"chapter_title":"🔋 الفصل الرابع: البطارية والقوة الدافعة الكهربائية","lesson_number":6,"lesson_title":"🚀 الدرس 6: بطارية الوقود","order_index":6,"hook":"ناتج «عادم» هذه البطارية ليس دخاناً ولا غازات سامة... بل ماء! لهذا تعتبر صديقة للبيئة وتسيّر المركبات الحديثة.","concepts":[{"term":"بطاريه الوقود:","text":"هي خليه قادره على توليد التيار الكهربائي باعتمادها على الوقود الذي يجهز من مصدر خارجي و لا ينتهي مفعولها فهي تعمل باستمرار طالما يتم تجهيزها بالوقود ومن امثلتها بطاريه وقود الهيدروجين.","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["بطارية الوقود لا ينتهي مفعولها — تعمل باستمرار طالما يتم تجهيزها بالوقود من مصدر خارجي.","كل خليه تولد فولطاً واحداً، وكلما ازداد عدد الشرائح الموصلة ازداد فرق الجهد الخارج.","نواتج عملها: ماء + طاقه كهربائية — لهذا فهي صديقة للبيئة!"],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هو مبدا عمل خليه وقود الهيدروجين؟","answer":"اساس عملها التفاعلات الكيميائية.","ministerial":false},{"type":"سؤال","question":"كم فولط تولد الخلية الواحدة لبطارية الوقود؟","answer":"تولد كل خليه منها فرق جهد كهربائي قدره فولطاً واحدا لذلك كلما ازداد عدد الشرائح الموصلة بعضها مع بعض ازداد فرق الجهد الخارج منها.","ministerial":false},{"type":"سؤال","question":"ما الفائدة العملية لبطارية الوقود؟","answer":"١. تشغيل الحاسوب.\n٢. في تسيير المركبات الحديثة.","ministerial":false},{"type":"سؤال","question":"كيف تعمل خليه وقود الهيدروجين؟","answer":"تعمل على تحويل الطاقة الكيميائية الى طاقه كهربائية و يتم تخزين الهيدروجين بشكل سائل في اوعيه خاصه فأثناء عمل خليه الوقود يتم تحويل غاز الهيدروجين و غاز الاوكسجين المأخوذ من الجو الى ماء و طاقه كهربائية.","ministerial":true},{"type":"سؤال","question":"ما مكونات خلايا الوقود؟","answer":"تتكون من شرائح رقيقه وتولد كل خليه فرق جهد كهربائي قدره فولطا واحدا لذلك كلما ازداد عدد الشرائح الموصلة بعضها مع بعض ازداد فرق الجهد الخارج منها.","ministerial":false},{"type":"سؤال","question":"ما مميزات خليه وقود الهيدروجين؟","answer":"١. عدم حصول تلوث او استهلاك المصادر الوقود التقليدي.\n٢. تكنولوجيا الهيدروجين لا تسبب اخطار فهي امنه عند الاستعمال.\n٣. كفاءه تشغيلها عالية جدا.\n٤. عمرها طويل بالمقارنة مع باقي انواع البطاريات.","ministerial":true},{"type":"علل","question":"عند استعمال بطاريه الوقود فإنها لا تسبب تلوث للبيئة او استهلاكا لمصادر الوقود التقليدية التي تؤثر في صحه الانسان؟","answer":"لان الهيدروجين ينتج من الماء بالأكسدة ويعود الى الماء مره اخرى.","ministerial":false},{"type":"علل","question":"تعد بطاريه الوقود امنه عند استعمالها؟","answer":"لأنه تكنولوجيا الهيدروجين لا تحتوي على اي عناصر تسبب في اخطار ممكنه.","ministerial":false},{"type":"علل","question":"تعد بطاريه وقود الهيدروجين احد تطبيقات قانون حفظ الطاقة؟","answer":"لأنها تحول الطاقة الكيميائية الى طاقه كهربائية.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 شغّل خلية وقود الهيدروجين"},{"chapter_number":4,"chapter_title":"🔋 الفصل الرابع: البطارية والقوة الدافعة الكهربائية","lesson_number":7,"lesson_title":"⚡ الدرس 7: القوة الدافعة الكهربائية والمقاومة الداخلية","order_index":7,"hook":"تخيل البطارية مدرب رياضي يعطي كل شحنة «جرعة طاقة» قبل انطلاقها في الدائرة... مقدار هذه الجرعة لكل واحدة شحنة هو القوة الدافعة الكهربائية emf!","concepts":[{"term":"القوة الدافعة الكهربائية (emf):","text":"هي مقدار الطاقة التي تزودها البطارية للشحنات الكهربائية حتى تتحرك أي تتحرك الالكترونات في الدائرة الكهربائية وتقاس بوحدة (joule/coulomb) وتسمى هذه الوحدة volt وتقاس بجهاز الفولطمتر.","ministerial":false},{"term":"المقاومة الداخلية للبطارية:","text":"هي الاعاقة التي تبديها مادة الوسط (المركبات الكيميائية) داخل البطارية لحركة الشحنات الكهربائية خلالها ويرمز لها (r).","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["وحدة قياس emf هي Volt وتكافئ Joule/Col — وتقاس بجهاز الفولطميتر.","المقاومة الداخلية r هي سبب كون فولتية الشاحن (14V) اكبر من فولتية بطارية السيارة (12V) — تذكر الدرس الرابع!"],"ministerial":false}],"tables":[{"caption":"","headers":["الصيغة الرياضية","تعريف الرموز","وحدة القياس"],"rows":[["e.m.f = w / q","e.m.f: القوة الدافعة الكهربائية\nw: الشغل (الطاقة)\nq: الشحنة الكهربائية","e.m.f ⟵ Volt\nw ⟵ Joule جول\nq ⟵ col"]],"ministerial":false}],"examples":[{"problem":"مثال ١: انسابت كمية من الشحنات الكهربائية (q) مقدارها (10 c) خلال بطارية فاكتسبت طاقة مقدارها (20 J) احسب مقدار القوة الدافعة الكهربائية.","givens":"المعطيات: w = 20 J — q = 10 C — المطلوب: emf","solution_steps":["الخطوة ١: نكتب القانون: emf = w / q","الخطوة ٢: نعوض: emf = 20 / 10","الخطوة ٣: النتيجة: emf = 2 V"],"ministerial":false},{"problem":"سؤال: بطارية القوة الدافعة لها (2V) ما مقدار الشغل الذي تزوده لتحريك شحنة مقدارها (20 C)؟","givens":"المعطيات: emf = 2 V — q = 20 C — المطلوب: w","solution_steps":["الخطوة ١: من emf = w/q نحصل على: w = emf × q","الخطوة ٢: نعوض: w = 2 × 20 = 40 J"],"ministerial":false},{"problem":"سؤال: اذا كان مقدار الشغل الذي تزوده البطارية لتحريك شحنة يساوي (60 J) احسب مقدار تلك الشحنة المتحركة اذا علمت ان مقدار القوة الدافعة الكهربائية للبطارية تساوي (4 V)؟","givens":"المعطيات: emf = 4 V — w = 60 J — المطلوب: q","solution_steps":["الخطوة ١: من emf = w/q نحصل على: q = w / emf","الخطوة ٢: نعوض: q = 60 / 4 = 15 C"],"ministerial":false},{"problem":"س١: احسب مقدار الشغل المبذول من قبل شحنة متحركة مقدارها (2 C) في دائرة كهربائية تحتوي على بطارية القوة الدافعة الكهربائية (emf) تساوي (1.5 v)؟","givens":"المعطيات: q = 2 C — emf = 1.5 V — المطلوب: W","solution_steps":["الخطوة ١: من emf = w/q نحصل على w = emf × q.","الخطوة ٢: نعوض: W = 2 × 1.5 = 3 J"],"ministerial":false},{"problem":"س٢: مقدار القوة الدافعة الكهربائية المحتثه (emf) لبطارية (12 V) ومقدار الشغل الذي تزوده البطارية لتحريك الشحنة (120 J) احسب مقدار الشحنة المتحركة (q)؟","givens":"المعطيات: emf = 12 V — w = 120 J — المطلوب: q","solution_steps":["الخطوة ١: من emf = w/q نحصل على: q = w / emf","الخطوة ٢: نعوض: q = 120 / 12 = 10 C"],"ministerial":false},{"problem":"س٣: انسابت كمية من الشحنات الكهربائية مقدارها (15 C) خلال بطارية فاكتسبت طاقة مقدارها (30 J)، احسب مقدار القوة الدافعة الكهربائية؟","givens":"المعطيات: w = 30 J — q = 15 col — المطلوب: e.m.f","solution_steps":["الخطوة ١: نكتب القانون: e.m.f = w / q","الخطوة ٢: نعوض: e.m.f = 30 / 15 = 2 V"],"ministerial":true}],"qa":[{"type":"سؤال","question":"ما هي وحدة قياس القوة الدافعة الكهربائية اذكرها بطريقتين؟","answer":"تقاس القوة الدافعة الكهربائية بوحدة Volt والتي تكافئ Joule/Col.","ministerial":false},{"type":"سؤال","question":"ما هو الجهاز المستخدم في قياس القوة الدافعة الكهربائية؟","answer":"تقاس بجهاز الفولطميتر.","ministerial":false},{"type":"فكر","question":"ماذا نعني أن القوة الدافعة الكهربائية لبطارية (emf = 1.5 volt)؟","answer":"يعني ان مقدار فرق الجهد بين القطب السالب والقطب الموجب للبطارية (1.5 volt) عندما تكون الدائرة الكهربائية مفتوحة، وكذلك مقدار الطاقة التي ممكن ان تجهزها البطارية هي (1.5 J) عندما تكون الشحنة الكهربائية مقدارها (1 c).","ministerial":true}],"has_simulation":true,"simulation_title":"🧮 حاسبة القوة الدافعة الكهربائية"},{"chapter_number":5,"chapter_title":"💡 الفصل الخامس: الطاقة والقدرة الكهربائية","lesson_number":1,"lesson_title":"💪 الدرس 1: القدرة الكهربائية ووحداتها","order_index":1,"hook":"عداءان قطعا نفس المسافة، لكن أحدهما أسرع... نقول قدرته أكبر! وكذلك الأجهزة: الجهاز الذي يستهلك طاقة أكثر في كل ثانية قدرته أكبر.","concepts":[{"term":"القدرة الكهربائية:","text":"مقدار الطاقة التي يستهلكها الجهاز الكهربائي في وحدة الزمن وتقاس بالواط.","ministerial":true}],"laws":[],"notes":[{"heading":"","items":["الكيلو جول على ساعة (kJ/h) هي وحدة قياس القدرة الكهربائية، والجول على ثانية (J/s) هي وحدة قياس القدرة الكهربائية ايضاً.","إذا كان مقدار التيار الكهربائي المنساب في جهاز كهربائي هو 1A وبفرق جهد بين طرفيه قدرة 1V فيكون مقدار القدرة المستثمرة للجهاز يساوي واحد واط 1W.","الطاقة الكهربائية = القدرة الكهربائية × الزمن"],"ministerial":false}],"tables":[{"caption":"","headers":["الصيغة الرياضية","تعريف الرموز","وحدة القياس"],"rows":[["P = E / t","P: يمثل القدرة الكهربائية\nE: يمثل الطاقة الكهربائية المستهلكة او المستثمرة\nt: يمثل الزمن","P ⟵ Watt واط\nE ⟵ Joule جول\nt ⟵ Second ثانية"]],"ministerial":false}],"examples":[],"qa":[{"type":"سؤال","question":"اذكر وحدات قياس القدرة الكهربائية؟","answer":"تقاس القدرة بوحدة (جول/ثانية) تسمى الواط (watt).\nالواط: هي وحدة قياس القدرة ويرمز لها (W) وتكافئ بوحدات (جول/الثانية): W = Joule / Second","ministerial":false},{"type":"سؤال","question":"ايهما اكثر اضاءة مصباح قدرته (20 W) ام مصباح قدرته (100W)؟","answer":"المصباح الذي قدرته (100 W) تكون أضاءته اكبر من المصباح ذو القدرة (20 W) لأنه يستهلك في كل ثانية طاقة كهربائية مقدارها (100 J).","ministerial":true},{"type":"سؤال","question":"لماذا يعطي المصباح ذو القدرة 100 w إضاءة أكبر من المصباح المماثل له ذو القدرة 20 w؟","answer":"لأن المصباح ذو القدرة 20 w يستهلك في 1 Sec طاقة مقدارها 20 Joule، بينما المصباح ذو القدرة 100 w يستهلك في 1 Sec طاقة مقدارها 100 Joule لذا تكون إضاءته أكبر.","ministerial":false},{"type":"سؤال","question":"على ماذا يعتمد مقدار القدرة الكهربائية للجهاز الكهربائي؟","answer":"١. مقدار التيار الكهربائي المنساب في ذلك الجهاز.\n٢. فرق الجهد بين طرفيه.","ministerial":false},{"type":"سؤال","question":"ما هي التطبيقات العملية (الفائدة العملية) للقدرة الكهربائية في حياتنا اليومية؟","answer":"في المنازل والمصانع والمحال التجارية والمستشفيات لأغراض التدفئة والتبريد وتشغيل الأجهزة الكهربائية.","ministerial":false},{"type":"سؤال","question":"وضح مع ذكر الامثلة لبعض انواع الطاقة الناتجة من الطاقة الكهربائية المستهلكة عند تشغيل اي جهاز او اداة كهربائية معينة؟","answer":"١. طاقة حركية كما في المحركات.\n٢. طاقة حرارية كما في المدافئ الكهربائية.\n٣. طاقة ضوئية كما في المصابيح الكهربائية.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 جرب بنفسك: أيهما أسطع؟ 20W أم 100W؟"},{"chapter_number":5,"chapter_title":"💡 الفصل الخامس: الطاقة والقدرة الكهربائية","lesson_number":2,"lesson_title":"📐 الدرس 2: قوانين القدرة الثلاثة والنشاط الوزاري","order_index":2,"hook":"القاعدة الذهبية من الأستاذ: إذا اعطى في السؤال مقاومة نتذكر فورا قانون اوم لنشتق منه كل قانون حسب المعطيات الموجودة في السؤال!","concepts":[],"laws":[],"notes":[{"heading":"","items":["الاجهزة الكهربائية في المنازل توصل مع بعضها على التوازي.","اذا كان الزمن المعطى بالساعة او الدقائق يحول الى ثواني وكذلك اذا كانت الطاقة المستثمرة بالكيلو جول تحول الى الجول ثم نستخدم القانون P = E/t.","اذا اعطى في السؤال مقاومة نتذكر فورا قانون اوم لنشتق منه كل قانون حسب المعطيات الموجودة في السؤال."],"ministerial":false}],"tables":[{"caption":"","headers":["القانون","متى نستخدمه؟"],"rows":[["P = I V","عندما يعطينا السؤال التيار وفرق الجهد"],["P = I² R","عندما يعطينا السؤال التيار والمقاومة"],["P = V² / R","عندما يعطينا السؤال فرق الجهد والمقاومة"]],"ministerial":false}],"examples":[],"qa":[{"type":"اثبت","question":"س: اثبت ان P = I²R","answer":"∵ R = V/I ⟸ P = IV ⟸ P = I²R\n∴ P = (I R) I ⟸ P = I²R","ministerial":false},{"type":"اثبت","question":"س: اثبت ان P = V²/R","answer":"∵ R = V/I ⟸ I = V/R ⟸ P = IV\nP = V(V/R) ⟸ P = V²/R","ministerial":false},{"type":"نشاط","question":"س: وضح بنشاط كيفية حساب القدرة الكهربائية لجهاز كهربائي (مصباح، تلفاز)؟","answer":"الادوات: ١. مصباح كهربائي يعمل بفولطية (6V) وبقدرة (2.5 W)  ٢. بطارية فولطيتها مناسبة  ٣. فولطميتر  ٤. اميتر  ٥. مفتاح كهربائي  ٦. اسلاك توصيل.\nالعمل:\n١. نربط الاجهزة الكهربائية كما في الشكل.\n٢. نغلق مفتاح الدائرة الكهربائية ونسجل قراءة الأميتر (مقدار التيار في الدائرة) ثم نسجل قراءة الفولطميتر (مقدار فرق الجهد على طرفي المصباح).\n٣. نحسب القدرة بتطبيق العلاقة التالية: P = IV","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 نفّذ النشاط الوزاري بنفسك"},{"chapter_number":5,"chapter_title":"💡 الفصل الخامس: الطاقة والقدرة الكهربائية","lesson_number":3,"lesson_title":"🧮 الدرس 3: مسائل القدرة الكهربائية","order_index":3,"hook":"سر النجاح في مسائل القدرة: اكتب المعطيات أولاً، ثم اختر القانون الذي يناسبها — وأحياناً تصل للجواب بثلاث طرق مختلفة!","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[{"problem":"س٢: مدفأة كهربائية سلطت عليها فولطية مقدارها (220 V) وكانت مقاومة احد اسلاك التسخين الثلاثة (88 Ω) احسب مقدار: ١ ــ القدرة المستهلكة في احد اسلاك التوصيل ٢ ــ التيار المنساب في احد اسلاك التوصيل.","givens":"المعطيات: V = 220 V — R = 88 Ω — المطلوب: P ثم I","solution_steps":["الخطوة ١: عندنا جهد ومقاومة ⟸ نستخدم: P = V²/R = (220×220)/88 = 48400/88 = 550 W","الخطوة ٢: نجد التيار من P = IV: I = P/V = 550/220 = 2.5 A","الخطوة ٣: هناك طريقة اخرى لإيجاد التيار (قانون اوم): I = V/R = 220/88 = 2.5 A"],"ministerial":false},{"problem":"س٣: مدفأة كهربائية سلطت عليها فولطية مقدارها (220 v) وكانت مقاومة سلك التسخين (22Ω) احسب مقدار: ١ــ القدرة المستهلكة في احد اسلاك التسخين ٢ ــ التيار المنساب في احد اسلاك التسخين.","givens":"المعطيات: V = 220 V — R = 22 Ω — المطلوب: P ثم I","solution_steps":["الخطوة ١: P = V²/R = (220×220)/22 = 2200 W","الخطوة ٢: I = V/R = 220/22 = 10 A"],"ministerial":false},{"problem":"س٥: مقاومتان (R₁=9 Ω ، R₂=18 Ω) ربطتا على التوازي وربطت المجموعة عبر فرق جهد قدره (36v) احسب مقدار القدرة الكهربائية المستهلكة في كل مقاومة؟","givens":"المعطيات: V = 36 V — R₁ = 9 Ω — R₂ = 18 Ω — المطلوب: P₁ و P₂ (في التوازي فرق الجهد نفسه على كل مقاومة)","solution_steps":["الخطوة ١: القدرة في المقاومة الاولى: P₁ = V²/R = (36×36)/9 = 144 W","الخطوة ٢: القدرة في المقاومة الثانية: P₂ = V²/R = (36×36)/18 = 72 W"],"ministerial":false},{"problem":"س٦: دائرة تحتوي على مقاومة وفولطميتر واميتر فاذا كانت قراءة الاميتر هي (10A) وقراءة الفولطميتر (110V) احسب: ١ــ مقدار المقاومة ٢ــ القدرة (بثلاث طرق مختلفة).","givens":"المعطيات: V = 110 V — I = 10 A — المطلوب: R ثم P بثلاث طرق","solution_steps":["الخطوة ١: المقاومة من قانون اوم: R = V/I = 110/10 = 11 Ω","الخطوة ٢: الطريقة الأولى: P = I²R = (10)² × 11 = 1100 W","الخطوة ٣: الطريقة الثانية: P = IV = 10 × 110 = 1100 W","الخطوة ٤: الطريقة الثالثة: P = V²/R = (110×110)/11 = 1100 W"],"ministerial":false},{"problem":"س٧: ابريق شاي كهربائي يعمل بقدرة مقدارها (1200 W) فاذا كان التيار المنساب في الابريق (5A) احسب: ١ــ مقدار الفولطية التي يعمل عليها الجهاز ٢ ــ مقاومة سلك التسخين.","givens":"المعطيات: P = 1200 W — I = 5 A — المطلوب: V ثم R","solution_steps":["الخطوة ١: من P = IV: V = P/I = 1200/5 = 240 V","الخطوة ٢: من قانون اوم: R = V/I = 240/5 = 48 Ω"],"ministerial":false},{"problem":"س٨: جهاز كهربائي يستثمر طاقة مقدارها (36K J) في مدة زمنية قدرها ثلاث دقائق وكان مقدار التيار المنساب في هذا الجهاز (2 A) جد مقدار: ١ ــ القدرة المستثمرة ٢ ــ فرق الجهد الذي يعمل علية الجهاز.","givens":"المعطيات: E = 36 kJ = 36000 J — t = 3 دقائق = 180 s — I = 2 A — المطلوب: P ثم V","solution_steps":["الخطوة ١: نحول الوحدات: 36 كيلو جول = 36000 جول، و3 دقائق = 180 ثانية.","الخطوة ٢: القدرة: P = E/t = 36000/180 = 200 W","الخطوة ٣: فرق الجهد من P = IV: V = P/I = 200/2 = 100 V"],"ministerial":false}],"qa":[{"type":"واجب","question":"س٤: اذا كان مقدار التيار الكهربائي المنساب في سلك التسخين لسخان كهربائي هو (10 A) وكانت مقاومة سلك التسخين (22Ω) احسب: ١ــ فرق الجهد الكهربائي ٢ــ القدرة الكهربائية للجهاز.","answer":"تلميح للحل (جرب بنفسك اولاً!):\n١. فرق الجهد من قانون اوم: V = I × R = 10 × 22 = 220 V\n٢. القدرة: P = I²R = (10)² × 22 = 2200 W (او P = IV = 10 × 220 = 2200 W)","ministerial":false}],"has_simulation":false,"simulation_title":""},{"chapter_number":5,"chapter_title":"💡 الفصل الخامس: الطاقة والقدرة الكهربائية","lesson_number":4,"lesson_title":"🏠 الدرس 4: قدرة الأجهزة المنزلية وتوهج المصابيح","order_index":4,"hook":"انظر خلف أي جهاز كهربائي في بيتك — ستجد ملصقاً يذكر القدرة والفولطية... ومنهما تحسب التيار الذي يحتاجه بقانون I = P/V!","concepts":[],"laws":[],"notes":[{"heading":"","items":["التيار المنساب في خويط المصباح هو الذي يؤثر في مقدار توهج المصباح."],"ministerial":false}],"tables":[{"caption":"من البيانات الموضحة على الأجهزة المنزلية (الفولطية والقدرة الكهربائية) إحسب مقدار التيار الذي يحتاجه كل جهاز عند اشتغاله ثم احسب مقدار التيار الكلي؟ لاحظ الجدول التالي — اضغط «احسب» لكل جهاز:","headers":["أسم الجهاز","قدرة الجهاز P (w)","فولطية الجهاز V (v)","تيار الجهاز (I=P/V) A"],"rows":[["مدفئة زيتية كهربائية","1600W","220V","احسب"],["مكواة كهربائية","1000W","220V","احسب"],["غسالة كهربائية","500W","220V","احسب"],["مصباح كهربائي","100W","220V","احسب"],["مفرغة هواء كهربائية","200W","220V","احسب"],["التيار الكلي","مجموع تيارات الاجهزة (توازي)","؟"]],"ministerial":false}],"examples":[],"qa":[{"type":"سؤال","question":"المصابيح (a , b , c) في الشكل المجاور متماثلة، بيّن أي من المصابيح يكون اكثر توهجاً (أكثر سطوعا)؟ وايهما يستهلك قدرة اكبر؟","answer":"نلاحظ أن المصباح (c) أكثر سطوعا من المصباح (a) وكذلك من المصباح (b) بسبب زيادة عدد الأعمدة في دائرة المصباح (c) أي زيادة فرق الجهد الكهربائي عبر المصباح، وبالتالي يزداد مقدار التيار المنساب في المصباح (c). القدرة المتحولة (من طاقة كهربائية الى طاقة ضوئية) في المصباح (c) هي الأكبر (P = V²/R).","ministerial":false},{"type":"سؤال","question":"المصابيح المتماثلة (d , e , f) أي المصابيح يتوهج أكثر و أيهما تتحول عنده القدرة الأكبر؟","answer":"المصباح (d) هو الأكثر سطوعاً (أكثر توهجاً) أما المصباحان (e , f) فيكونان أقل توهجاً بسبب زيادة عدد المصابيح في الدائرة وهذا يؤدي إلى زيادة المقاومة المكافئة في الدائرة ونقصان مقدار التيار المنساب فيها. المصباح (d) تتحول فيه (يستهلك) قدرة اكبر (P = V²/R).","ministerial":false},{"type":"سؤال","question":"بم يتأثر تيار الدائرة الكهربائية ؟","answer":"١. فرق الجهد الكهربائي بين طرفي الدائرة.\n٢. عدد المصابيح المستعملة في الدائرة (مقاومة الدائرة) وطريقة ربطها.","ministerial":false},{"type":"سؤال","question":"مصباحان الأول مكتوب عليه (60W) والثاني مكتوب عليه (30W) ربطا على التوازي مع بعضهما وربطت مجموعتهما بين قطبي بطارية فولطيتها مناسبة — أملا الفراغ في الجمل الآتية بالإشارات المناسبة > ، < ، =","answer":"١. مقاومة المصباح الاول < مقاومة الصباح الثاني.\n٢. التيار المنساب في المصباح الأول > التيار المنساب في المصباح الثاني.\n٣. اضاءة المصباح الأول > اضاءة المصباح الثاني.\n٤. فرق الجهد بين طرفي المصباح الأول = فرق الجهد بين طرفي المصباح الثاني.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 مختبر التوهج: مصباحا 60W و 30W على التوازي"},{"chapter_number":5,"chapter_title":"💡 الفصل الخامس: الطاقة والقدرة الكهربائية","lesson_number":5,"lesson_title":"⚡ الدرس 5: الطاقة الكهربائية E = P × t","order_index":5,"hook":"مصباح صغير يعمل طوال الليل قد يستهلك طاقة أكثر من مكواة قوية تعمل 5 دقائق... لأن الطاقة = القدرة × الزمن!","concepts":[{"term":"الطاقة:","text":"هي القابلية على انجاز الشغل، وتقاس بوحدة جول (J) او (kw-hr).","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["الكيلو واط – ساعة (kw-hr) هي وحدة قياس الطاقة الكهربائية، والواط – ثانية (w-s) هي وحدة قياس الطاقة الكهربائية.","الانتباه الى وحدات قياس الزمن والتي يجب ان تكون بالثانية والقدرة بالواط واذا اتى غير ذلك نستخدم الطرق المعتادة للتحويل.","اذا لم يعطي مباشرة القدرة في السؤال نستخرجها حسب الطرق السابقة المتعارف عليها."],"ministerial":false}],"tables":[{"caption":"للطاقة وحدات قياس متعدد وحسب نوع الطاقة:","headers":["الوحدة","تكافئ"],"rows":[["الجول","1 Joule = newton × meter"],["كيلو واط ــ ساعة","1 kilowatt-hour = 3.6 × 10⁶ joule"],["القدرة الحصانية ــ ساعة","1 horse power-hour = 2.68 × 10⁶ joule"],["الالكترون ــ فولط ورمزها (eV)","1eV = 1.6 × 10⁻¹⁹ joule"]],"ministerial":false}],"examples":[{"problem":"س: اذا استعمل مجفف شعر لمدة (20 minutes) وكانت قدرة المجفف (1500 w) احسب مقدار الطاقة الكهربائية المستثمرة في المجفف ؟","givens":"المعطيات: P = 1500 W — t = 20 دقيقة = 20×60 = 1200 s — المطلوب: E","solution_steps":["الخطوة ١: نحول الزمن: t = 20 × 60 = 1200 sec.","الخطوة ٢: نطبق القانون: E = P × t = 1500 × 1200 = 1800000 J"],"ministerial":false},{"problem":"س: ابريق شاي كهربائي يعمل على فرق جهد (220 V) ينساب في ملف الابريق تيار قدره (10 A). احسب: ١ ــ قدرة الابريق ٢ ــ الطاقة الكهربائية المستثمرة خلال (20 sec).","givens":"المعطيات: V = 220 V — I = 10 A — t = 20 s — المطلوب: P ثم E","solution_steps":["الخطوة ١: القدرة: P = IV = 10 × 220 = 2200 W","الخطوة ٢: الطاقة: E = P × t = 2200 × 20 = 44000 J = 44 KJ"],"ministerial":false},{"problem":"س: جهاز منزلي يستهلك قدرة مقدارها (1200 w) سلط فرق جهد مقداره (240 v) بين طرفيها احسب مقدار: ١ــ التيار الكهربائي المنساب في الجهاز ٢ــ الطاقة الكهربائية المستهلكة خلال اربعة دقائق ؟","givens":"المعطيات: P = 1200 W — V = 240 V — t = 4×60 = 240 s — المطلوب: I ثم E","solution_steps":["الخطوة ١: التيار: I = P/V = 1200/240 = 5 A","الخطوة ٢: الطاقة: E = P × t = 1200 × 240 = 288000 J = 288 KJ"],"ministerial":false},{"problem":"س: مكيف هواء قدرته (2420 watt) فاذا كان التيار المار في ملف ضاغط الهواء (11A) احسب مقدار: ١ ــ الفولطية التي تعمل عليها الجهاز (ج: 220 V) ٢ــ الطاقة الكهربائية المستهلكة خلال زمن قدرة (60 min) (ج: 8712000 j).","givens":"المعطيات: P = 2420 W — I = 11 A — t = 60×60 = 3600 s — المطلوب: V ثم E","solution_steps":["الخطوة ١: الفولطية: V = P/I = 2420/11 = 220 V","الخطوة ٢: نحول الزمن: t = 60 دقيقة = 3600 ثانية.","الخطوة ٣: الطاقة: E = P × t = 2420 × 3600 = 8712000 J"],"ministerial":false}],"qa":[{"type":"سؤال","question":"على ماذا يعتمد مقدار الطاقة الكهربائية المستهلكة او المستثمرة ؟","answer":"١. القدرة الكهربائية.\n٢. زمن استخدام الجهاز.\nحسب العلاقة: E (Joules) = P(W) × t (s)","ministerial":false},{"type":"سؤال","question":"تعمل وزارة الكهرباء على تنصب مقياس كهربائي في كل منزل ما سبب ذلك؟ او: ما لفائدة العملية من وجود مقياس الطاقة الكهربائية (الميزانية) في المنازل؟","answer":"وذلك لتسجيل مقدار الطاقة الكهربائية المستهلكة من قبل الأجهزة الكهربائية الموجودة في المنزل.","ministerial":false}],"has_simulation":true,"simulation_title":"🧮 حاسبة الطاقة الكهربائية"},{"chapter_number":5,"chapter_title":"💡 الفصل الخامس: الطاقة والقدرة الكهربائية","lesson_number":6,"lesson_title":"💰 الدرس 6: كلفة الطاقة الكهربائية","order_index":6,"hook":"فاتورة الكهرباء ليست لغزاً: كلفة = قدرة (kW) × زمن (h) × ثمن الوحدة... ثلاث خطوات وتعرف المبلغ الواجب دفعه!","concepts":[],"laws":[],"notes":[{"heading":"لحساب ثمن الطاقة المستهلكة يجب مراعاة ما يلي:","items":["يجب معرفة ثمن الوحدة الواحدة والتي تقاس بوحدة (Dinar/KW-h).","يجب ان تكون القدرة بالكيلو واط (kw) واذا كانت بالواط نقسم على (1000) كي تحول الى الكيلو واط.","يجب ان يكون الزمن بالساعات (h) واذا وجد بالدقائق او بالثواني يحول الى ساعات حيث اذا كان دقائق نقسم على 60 ليتحول الى ساعة اما اذا كان بالثواني فنقسم على 3600 ليحول الى ساعة."],"ministerial":false}],"tables":[{"caption":"","headers":["القانون","بالرموز"],"rows":[["كلفة الطاقة المستهلكة = القدرة المستهلكة (P) × الزمن (t) × ثمن الوحدة الواحدة (cost)","cost = P × t × unit price"],["كلفة الطاقة المستهلكة = الطاقة الكهربائية × ثمن الوحدة الواحدة","cost = E × unit price"]],"ministerial":false}],"examples":[{"problem":"س: اذا استعملت مكنسة كهربائية لمدة (30 minutes) وكانت المكنسة تستهلك قدرة (1 kw) وثمن الوحدة الواحدة (100 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","givens":"المعطيات: P = 1 kW — t = 30 دقيقة — ثمن الوحدة = 100 دينار — المطلوب: cost","solution_steps":["الخطوة ١: نحول الزمن الى ساعات: t = 30/60 = 0.5 h.","الخطوة ٢: نطبق القانون: cost = P × t × unit price = 1 × 0.5 × 100 = 50 Dinar"],"ministerial":false},{"problem":"س: اذا استعملت غسالة كهربائية لمدة (30 minutes) وكانت الغسالة تستهلك قدرة (500 w) وثمن الوحدة الواحدة (100 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","givens":"المعطيات: P = 500 W — t = 30 دقيقة — ثمن الوحدة = 100 دينار","solution_steps":["الخطوة ١: نحول القدرة الى كيلو واط: P = 500/1000 = 0.5 kW.","الخطوة ٢: نحول الزمن: t = 30/60 = 0.5 h.","الخطوة ٣: cost = 0.5 × 0.5 × 100 = 25 Dinar"],"ministerial":false},{"problem":"س: اذا استعملت غسالة كهربائية لمدة (40 minutes) وكانت الغسالة تستهلك قدرة (600 w) وثمن الوحدة الواحدة (100 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","givens":"المعطيات: P = 600 W — t = 40 دقيقة — ثمن الوحدة = 100 دينار","solution_steps":["الخطوة ١: P = 600/1000 = 0.6 kW.","الخطوة ٢: t = 40/60 = 2/3 = 0.667 h.","الخطوة ٣: cost = 0.6 × 0.667 × 100 = 40 Dinar ⚠️ انتبه: 40/60 تساوي 0.667 لا 0.6 — تقريبها إلى 0.6 يُنقص الجواب من 40 إلى 36 ديناراً. احتفظ بثلاث منازل عشرية في تحويل الدقائق إلى ساعات."],"ministerial":false},{"problem":"س: سخان كهربائي تم تشغيله لمدة (3 hours) ويستهلك قدرة (300 w) اذا علمت ان ثمن الوحد الواحدة (30 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","givens":"المعطيات: P = 300 W — t = 3 h — ثمن الوحدة = 30 دينار","solution_steps":["الخطوة ١: P = 300/1000 = 0.3 kW.","الخطوة ٢: cost = 0.3 × 3 × 30 = 27 Dinar"],"ministerial":false},{"problem":"س: مكواة تعمل على فرق جهد (220 v) وينساب فيها تيار كهربائي (3A) احسب قدرة المكواة وما مقدار المبلغ الواجب دفعه عندما تعمل المكواة لمدة نصف ساعة اذا كان ثمن الوحدة (100 Dinar/KW-h) .","givens":"المعطيات: V = 220 V — I = 3 A — t = نصف ساعة = 0.5 h — ثمن الوحدة = 100 دينار","solution_steps":["الخطوة ١: القدرة اولاً: P = IV = 3 × 220 = 660 W","الخطوة ٢: نحولها الى كيلو واط: P = 660/1000 = 0.66 kW","الخطوة ٣: الكلفة: cost = 0.66 × 0.5 × 100 = 33 Dinar"],"ministerial":false}],"qa":[{"type":"واجب","question":"س١: ابريق شاي يعمل على فرق جهد (220 v) وينساب فيها تيار كهربائي (2A) استخدم لمدة نصف ساعة، احسب مقدار المبلغ الواجب دفعه اذا كان ثمن الوحدة (100 Dinar/KW-h) ؟","answer":"تلميح: P = IV = 440W = 0.44kW ثم cost = 0.44 × 0.5 × 100 = 22 دينار.","ministerial":false},{"type":"واجب","question":"س٢: سخان كهربائي تم تشغيله لمدة (0.5 hours) ويستهلك قدرة (1500 w) اذا علمت ان ثمن الوحدة الواحدة (200 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","answer":"تلميح: 1.5 × 0.5 × 200 = 150 دينار.","ministerial":false},{"type":"واجب","question":"س٣: اذا استعمل مجفف شعر لمدة (30 minutes) وكان المجفف يستهلك قدرة (1200 w) وثمن الوحدة الواحدة (100 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","answer":"تلميح: 1.2 × 0.5 × 100 = 60 دينار.","ministerial":false},{"type":"واجب","question":"س٤: اذا استعملت مكنسة كهربائية لمدة (45 minutes) وكانت المكنسة تستهلك قدرة (800 w) وثمن الوحدة الواحدة (100 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","answer":"تلميح: 0.8 × 0.75 × 100 = 60 دينار.","ministerial":false},{"type":"واجب","question":"س٥: اذا استعملت مكواه كهربائية لمدة (15 minutes) وكانت المكواة تستهلك قدرة (1000 W) وثمن الوحدة الواحدة (100 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","answer":"تلميح: 1 × 0.25 × 100 = 25 دينار.","ministerial":false},{"type":"واجب","question":"س٦: اذا استعمل مجفف شعر لمدة (30 minutes) وكان المجفف يستهلك قدرة (1600 w) وثمن الوحدة الواحدة (50 Dinar/KW-h) فما هو المبلغ الواجب دفعة ؟","answer":"تلميح: 1.6 × 0.5 × 50 = 40 دينار.","ministerial":false}],"has_simulation":true,"simulation_title":"🧮 حاسبة كلفة الطاقة — احسب فاتورة اي جهاز في بيتك!"},{"chapter_number":5,"chapter_title":"💡 الفصل الخامس: الطاقة والقدرة الكهربائية","lesson_number":7,"lesson_title":"🔌 الدرس 7: الكهرباء في بيوتنا","order_index":7,"hook":"L و N و E — ثلاثة حروف تحميك أنت وأجهزتك كل يوم: الحي يجلب الكهرباء، والمتعادل يعيدها، والمؤرض... ينقذ حياتك!","concepts":[{"term":"الفاصم الكهربائي:","text":"سلك معدني فلزي لا يتحمل تيار يزيد مقداره عن الحد المعين له، فإذا تجاوز التيار هذا الحد فعندها يسخن الفاصم لدرجة حرارية تكفي لأنصهاره فينقطع التيار عن الجهاز مما يشكل وسيلة أمان كهربائي.","ministerial":false},{"term":"قاطع الدورة:","text":"جهاز يستعمل للأمان الكهربائي إذ يقوم بقطع التيار الكهربائي تلقائياً في حالة أنسياب تيار في الدائرة الكهربائية أكبر من التيار المصمم لها.","ministerial":false}],"laws":[],"notes":[{"heading":"","items":["السلك الحي L جهده 220V — السلك المتعادل N مؤرض عند محطة القدرة — السلك المؤرض E متصل بالأرض.","الفاصم وقاطع الدورة كلاهما يربط على التوالي مع السلك الحي."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هي الطريقة التي تزودنا بها مؤسسات الطاقة الكهربائية بحيث يكون استعمال الطاقة الكهربائية في حياتنا اليومية بشكل آمن ؟","answer":"تزودنا مؤسسات الطاقة الكهربائية في الطاقة عن طريق سلكين يمر فيهما تيار متناوب فرق الجهد بينهما (220 v):\n١. السلك الأول يسمى السلك الحي أو الحار وهو سلك جهده يساوي (220 v) ويرمز له L.\n٢. سلك ثاني يسمى السلك المتعادل او البارد يرمز له N، يمتاز كونه مؤرض عند محطة القدرة.","ministerial":false},{"type":"علل","question":"فولطية السلك المتعادل ليست عالية ؟","answer":"لكونه مؤرض عند محطة القدرة.","ministerial":false},{"type":"سؤال","question":"ما المقصود بالسلك الحي (الحار) والسلك المتعادل (البارد)؟","answer":"السلك الحي (الحار): هو سلك موصل جهده يساوي 220 volt ويرمز له بالرمز L.\nالسلك المتعادل (البارد): هو سلك موصل فولطيته أقل من السلك الحي لكونه مؤرض ويرمز له بالرمز N.","ministerial":false},{"type":"سؤال","question":"ما السلك المؤرض؟ وما الغرض من استعماله (الفائدة العملية)؟","answer":"السلك المؤرض: هو سلك يربط الجهاز الكهربائي بالأرض ويستعمل للسلامة الكهربائية في حالة حدوث خلل في الدائرة الكهربائية او حدوث تماس بين السلك الحي والغلاف المعدني للجهاز فسوف يؤدي الى انسياب معظم التيار الكهربائي من السلك الحي الى الأرض من خلال السلك المؤرض أي انه يقلل من خطر الصعقة الكهربائية.\nالغرض من استعماله: لتجنب الصعقة الكهربائية وحماية الاجهزة الكهربائية.","ministerial":true},{"type":"سؤال","question":"مما يتركب القبس الكهربائي ذي الفاصم ؟","answer":"يتركب من السلكين الحي L والمتعادل N والسلك المؤرض E والفاصم (Fuse) وجميعها تشكل وسائل امان كهربائي.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من وجود الفاصم في القابس الكهربائي؟ وكيف يربط؟","answer":"وضيفته حماية الأجهزة الكهربائية من العطب او التلف فيعمل على قطع التيار الكهربائي عن الدائرة عندما ينساب تيار أكبر من التيار المناسب لها ويربط على التوالي مع السلك الحي قبل دخول التيار في الجهاز.","ministerial":true},{"type":"علل","question":"يربط الفاصم (Fuse) على التوالي مع السلك الحي قبل دخول التيار في الجهاز؟","answer":"لكي يؤدي وظيفة الحماية فيقطع الدائرة عندما ينساب تيار في الدائرة أكبر من التيار المنسب لها.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من قاطع الدورة عند ربطه في الدائرة الكهربائية وكيف يربط في الدائرة الكهربائية؟","answer":"وذلك لحماية الاجهزة الكهربائية فيقطع تيار الدائرة الكهربائية تلقائيا في حالة انسياب تيار اكبر من التيار المناسب له ويربط على التوالي.","ministerial":false},{"type":"سؤال","question":"هل ان قاطع الدورة يربط على التوالي ام على التوازي في الدائرة الكهربائية مع الجهاز المطلوب حمايته ولماذا ؟","answer":"يربط على التوالي لأنه عندما تصير الدائرة محملة فوق ما تستطيع لا ينساب التيار في الدائرة الكهربائية.","ministerial":false},{"type":"علل","question":"يربط قاطع الدورة في الدائرة الكهربائية للمنزل على التوالي مع السلك الحار قبل تجهيز الأجهزة بالطاقة الكهربائية؟","answer":"لكي يؤدي الحماية للأجهزة الكهربائية فيقطع تيار الدائرة الكهربائية تلقائياً في حالة انسياب تيار أكبر من التيار المناسب لها.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 استكشف القبس الكهربائي ذا الفاصم"},{"chapter_number":5,"chapter_title":"💡 الفصل الخامس: الطاقة والقدرة الكهربائية","lesson_number":8,"lesson_title":"🛡️ الدرس 8: التأريض وتجنب الصعقة الكهربائية","order_index":8,"hook":"طائر يقف مطمئناً على سلك فيه آلاف الفولطات... والسر ليس في ريشه، بل في فرق الجهد بين رجليه الذي يساوي صفراً!","concepts":[],"laws":[],"notes":[{"heading":"","items":["من صفات السلك المؤرض أن يكون غليظاً ومقاومته الكهربائية صغيرة جداً أقل من مقاومة جسم الأنسان لكي ينساب التيار في السلك ولا ينساب في جسم الشخص الملامس للجهاز فتتكون دائرة قصيرة مع السلك دون أن يكون الشخص ضمنها.","يعتبر الفاصم (الفيوز) وسلك التأريض وقاطع الدورة من وسائل تعتبر من وسائل الأمان الكهربائي."],"ministerial":false}],"tables":[{"caption":"تسبب الصعقة الكهربائية أضراراً مختلفة في جسم الأنسان وخاصة في عمل الخلايا والنظام العصبي، فإذا:","headers":["مقدار التيار المنساب في الجسم","الأثر"],"rows":[["0.005 Amp","فانه يسبب ألماً بسيطا"],["0.01 Amp","فإنه يجعل العضلات تنقبض"],["0.1 Amp ولو لثواني قليلة","فانه قد يؤدي للموت"]],"ministerial":false}],"examples":[],"qa":[{"type":"سؤال","question":"عرف عملية التأريض وما رمزها؟","answer":"عملية التأريض: تعني الاتصال بالأرض وهي من وسائل الأمان الكهربائي ورمزها ⏚ (خطوط أفقية متدرجة الطول).","ministerial":false},{"type":"سؤال","question":"ما فائدة عملية التأريض؟","answer":"لتجنب الصعقة الكهربائية وحماية الاجهزة الكهربائية.","ministerial":false},{"type":"سؤال","question":"كيف يتم تجنب الصعقة الكهربائية؟","answer":"تأريض الاجهزة الكهربائية ذات الغلاف المعدني بسلك غليظ مقاومته الكهربائية صغيرة جدا اقل من مقاومة جسم الانسان.","ministerial":false},{"type":"علل","question":"لماذا تؤرض الاجهزة الكهربائية وبالخصوص ذات الغلاف المعدني؟","answer":"لتجنب الصعقة الكهربائية وحماية الاجهزة الكهربائية لان سلك التأريض مقاومته الكهربائية صغيرة جداً اقل من مقاومة جسم الانسان فتتكون دائرة قصيرة مع السلك من غير ان يكون جسم الانسان ضمنها.","ministerial":true},{"type":"علل","question":"يتم توصيل الغسالة الكهربائية عن طريق القابس الثلاثي الحاوي على سلك التأريض؟","answer":"لان ذلك يؤدي الى عدم حدوث صعقة كهربائية في حالة حدوث تماس بين السلك الحي وغلاف الغسالة المعدني.","ministerial":true},{"type":"فكر","question":"يمكن لطائر ان يقف على سلك مكشوف من اسلاك الجهد العالي دون ان يصاب بصعقة كهربائية؟","answer":"لأن مقاومة جسم الطائر كبيرة جدا بين نقطتي تلامس رجلي الطائر بسلك بالنسبة إلى مقاومة هذا الجزء من السلك عندئذ يكاد لا ينساب تيار في جسم الطائر وينساب في السلك فتكون دائرة قصيرة مع السلك من غير أن يكون جسم الطائر ضمنها فيكون فرق الجهد بين نقطتي التلامس بالسلك يساوي صفرا.","ministerial":true},{"type":"سؤال","question":"ما الإجراءات الواجب اتخاذها لغرض الحماية من مخاطر الكهرباء؟ او: كيف يتم تجنب الصعقة الكهربائية ؟","answer":"١. عدم ملامسة شخص تعرض لصعقة كهربائية إلا بعد فصله منها.\n٢. تجنب وضع جسم معدني ممسوك في اليد في نقطة الكهرباء.\n٣. عدم ترك الأسلاك متهرئة.\n٤. تجنب أن يتصل جسمك بين السلك الحي والسلك المتعادل أو الأرض.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 لماذا لا يُصعق الطائر؟ شاهد بنفسك"},{"chapter_number":6,"chapter_title":"🌀 الفصل السادس: الكهربائية والمغناطيسية","lesson_number":1,"lesson_title":"🧭 الدرس 1: تجربة أورستد","order_index":1,"hook":"قبل أورستد كانت الكهرباء والمغناطيسية عالمين منفصلين... تجربة واحدة أثبتت أنهما وجهان لعملة واحدة!","concepts":[],"laws":[],"notes":[{"heading":"","items":["ان انسياب تيار كهربائي في سلك موصل يولد حوله مجال مغناطيسي وهذا ما استنتجه اورستد."],"ministerial":true}],"tables":[],"examples":[],"qa":[{"type":"نشاط","question":"اذكر نشاط يمكنك من خلاله معرفة تأثير المجال المغناطيسي للتيار الكهربائي المنساب في السلك. (تجربة اورستد)","answer":"الأدوات: ١. إبرة مغناطيسية تستند على حامل مدبب   ٢. سلك غليظ بطول 30 cm   ٣. بطارية بفولطية 1.5 v   ٤. أسلاك توصيل   ٥. مفتاح كهربائي.\n\nالعمل:\n\n١. نترك الإبرة المغناطيسية حرة تتجه بموازاة المجال المغناطيسي الأرضي.\n\n٢. نجعل السلك الغليظ فوق الإبرة المغناطيسية بحيث يكون موازيا لمحورها.\n\n٣. نربط فيصل كل غليظ بين قطبي البطارية وعبر المفتاح الكهربائي.\n\n٤. نغلق المفتاح لبرهه من الزمن سنلاحظ انحراف الإبرة المغناطيسية ومن ثم استقرارها بوضع عمودي على طول السلك اما عند انقطاع التيار فإن الإبرة تعود إلى وضعها السابق.\n\n٥. نعكس اتجاه التيار وذلك بعكس قطبية النضيدة ونغلق المفتاح لبرهه من الزمن سنلاحظ أيضا انحراف الإبرة عمودي على طول السلك ولكن بوضع معاكس للحالة الأولى.\n\nأن انحراف الإبرة يدل على تأثرها بعزم قوة مغناطيسية بسبب وجودها في مجال مغناطيسي كما أن عودتها إلى وضعها السابق عند انقطاع التيار يدل على أن هذا التيار ولد مجال مغناطيسي.\n\nالاستنتاج: أنا انسياب التيار الكهربائي في سلك موصل يولد حوله مجالا مغناطيسيا.","ministerial":false},{"type":"سؤال","question":"ما هو أستنتاج أورستد؟","answer":"أن أنسياب تيار كهربائي في سلك موصل يولد حوله مجال مغناطيسي.","ministerial":true},{"type":"سؤال","question":"في تجربة اورستد ماذا يحدث لو وضعنا الابرة المغناطيسية فوق السلك الغليظ وبصورة موازية له؟","answer":"سوف تنحرف الابرة بشكل عمودي مع السلك، ويكون انحرافها باتجاه معاكس لو كانت تحت السلك.","ministerial":false},{"type":"سؤال","question":"في تجربة اورستد ما الغرض من استعمال السلك الغليظ؟","answer":"لان السلك الغيظ تكون مساحة مقطعة العرضي كبيرة وبالتالي سوف يسحب تيار عالي يولد حوله مجال مغناطيسي كافي لأجراء التجربة.","ministerial":false},{"type":"سؤال","question":"ماذا يحصل للإبرة المغناطيسية في تجربة اورستد عند غلق المفتاح الكهربائي الموصل بالبطارية لبرهه من الزمن ؟","answer":"نلاحظ انحراف الإبرة المغناطيسية ومن ثم استقرارها بوضع عمودي على طول السلك ثم عودتها إلى وضعها السابق بعد انقطاع التيار.","ministerial":false},{"type":"سؤال","question":"ماذا يحصل للإبرة المغناطيسية في تجربة اور ستد عند عكس قطبية النضيدة (عكس اتجاه التيار) وأغلق المفتاح الكهربائي الموصل بالبطارية لفترة من الزمن؟","answer":"نلاحظ انحراف الإبرة المغناطيسية ومن ثمة استقرارها بوضع عمودي على طول السلك باتجاه معاكس للحالة الأولى.","ministerial":false},{"type":"علل","question":"انحراف الإبرة المغناطيسية الموضوعة أسفل سلك غليظ عند انسياب تيار كهربائي ؟","answer":"أن انحراف الإبرة يدل على تأثرها بعزم قوة مغناطيسية بسبب وجودها في مجال مغناطيسي ناشئ من مرور التيار في السلك.","ministerial":true},{"type":"علل","question":"انعكاس اتجاه الإبرة المغناطيسية عند انعكاس التيار (انعكاس قطبي البطارية) المار في السلك؟","answer":"بسبب انعكاس اتجاه التيار المار في السلك والذي يؤدي إلى تولد مجال مغناطيسي معاكس للحالة الأولى وبالتالي فإن الإبرة المغناطيسية تنحرف تبعا لاتجاه التيار الذي يولد ذلك المجال.","ministerial":false},{"type":"علل","question":"تعود الإبرة المغناطيسية في تجربة اورستد إلى وضعها السابق عند انقطاع التيار الكهربائي عن السلك المار بموازاتها؟","answer":"لأن عند قطع التيار الكهربائي سوف ينقطع المجال المغناطيسي الذي سبب بتأثرها بعزم قوة مغناطيسية وبالتالي تعود الإبرة إلى وضعها الأصلي لعدم توفر تيار يولد مجال مغناطيسي.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 نفّذ تجربة أورستد بنفسك"},{"chapter_number":6,"chapter_title":"🌀 الفصل السادس: الكهربائية والمغناطيسية","lesson_number":2,"lesson_title":"✋ الدرس 2: المجال المغناطيسي لسلك مستقيم","order_index":2,"hook":"انثر برادة حديد حول سلك فيه تيار... سترتب نفسها في دوائر متحدة المركز — كأنها ترسم لك خريطة المجال المغناطيسي!","concepts":[],"laws":[],"notes":[{"heading":"","items":["النقطة (•) تمثل اتجاه التيار خارج من الورقة والمجال يدور عكس عقرب الساعة — والرمز (×) يمثل التيار داخلاً في الورقة والمجال يدور مع عقرب الساعة."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"نشاط","question":"أشرح نشاط يوضح تخطيط المجال المغناطيسي لتيار مستمر ينساب في سلك مستقيم؟","answer":"الأدوات: ورقة مقوى، عدة بوصلات مغناطيسية صغيرة، سلك غليظ، مفتاح كهربائي، بطارية كهربائية فولطيتها مناسبة، برادة حديد.\n\nالخطوات:\n\n١. نمرر السلك من خلال ورقة المقوى وتربط الدائرة الكهربائية.\n\n٢. ننشر برادة الحديد حول السلك ونغلق الدائرة الكهربائية لينساب التيار الكهربائي في السلك، وننقر على الورقة نقرات خفيفة.\n\n٣. نكرر الخطوات بوضع مجموعة البوصلات فوق ورقة المقوى بدل برادة الحديد ستشكل دائرة مركزها السلك.\n\n٤. نغلق الدائرة لفترة زمنية قصيرة فينساب تيار كهربائي خلال السلك، نلاحظ اتجاه القطب الشمالي للإبرة المغناطيسية.\n\n٥. نعكس قطبية البطارية لينعكس اتجاه التيار الكهربائي في السلك ونكرر الخطوات أعلاه.\n\nنستنتج: أن برادة الحديد تترتب بشكل دوائر متحدة المركز مركزها السلك وبمستوى عمودي عليه، وهذه الدوائر تمثل خطوط المجال المغناطيسي حول السلك والناشىء عن انسياب تيار كهربائي في السلك، أما اتجاه الأقطاب الشمالية لأبر البوصلات فيمثل اتجاه المجال المغناطيسي في النقطة الموضوعة فيها البوصلة.","ministerial":true},{"type":"سؤال","question":"ما شكل المجال المغناطيسي المتولد حول سلك يمر فيه تيار كهربائي مستمر؟ وكيف تحدد اتجاهه ؟","answer":"يكون على شكل دوائر متحدة المركز مركزها السلك وبمستوى عمودي عليه وتبتعد هذه الدوائر عن بعضها كلما ابتعدنا عن مركز السلك ويحدد اتجاهه باستخدام قاعدة الكف الأيمن.","ministerial":true},{"type":"سؤال","question":"ما العوامل المؤثرة على المجال المغناطيسي الناشئ حول سلك مستقيم ينساب فيه تيار كهربائي مستمر؟","answer":"١. يزداد مقدار المجال المغناطيسي (بازدياد عدد خطوط المجال المغناطيسي المار عموديا خلال وحدة المساحة ضمن مساحة معينة) بزيادة مقدار التيار الكهربائي المنساب في السلك.\n\n٢. يزداد مقدار المجال المغناطيسي بالاقتراب من السلك ويقل مقداره كلما ابتعدنا عن السلك.\n\n٣. اتجاه المجال المغناطيسي يعتمد على اتجاه التيار الكهربائي المستمر المنساب في السلك المستقيم.","ministerial":true},{"type":"سؤال","question":"اذكر قاعدة الكاف اليمنى لتحديد اتجاه المجال المغناطيسي حول سلك مستقيم ينساب فيه تيار كهربائي مستمر. وكيف يمكن تحديد اتجاه المجال المغناطيسي داخل ملف ينساب فيه تيار كهربائي مستمر؟","answer":"نطبق قاعدة الكف اليمنى وكالتالي نمسك الملف بالكف اليمنى بحيث يمثل لف الأصابع الى اتجاه التيار الكهربائي بينما يشير الابهام الى اتجاه خطوط المجال المغناطيسي داخل الملف (يشير الى القطب الشمالي).","ministerial":true},{"type":"سؤال","question":"ما شكل وأتجاه المجال المغناطيسي لسلك عمودي على ورقة أفقية ينساب تيار مستمر ؟","answer":"• إذا انساب تيار كهربائي مستمر في سلك عمودي على صفحة افقيه فإن اتجاه المجال المغناطيسي يكون بشكل دوائر متحدة المركز حول السلك في مستوى الصفحة واتجاهه يتوقف على اتجاه التيار الكهربائي.\n\n• إذا انساب التيار في السلك نحو الناظر (خارج من الورقة •) فإن اتجاه المجال المغناطيسي يكون عكس اتجاه دوران عقرب الساعة.\n\n• إذا انساب التيار في السلك مبتعد عن الناظر (داخلا في الورقة ×) فاتجاه المجال المغناطيسي يكون مع اتجاه دوران عقرب الساعة.","ministerial":false},{"type":"علل","question":"تنحرف الابرة المغناطيسية الموضوعة بموازاة سلك يمر فيه تيار كهربائي.","answer":"لأن السلك المار فيه تيار كهربائي يتولد حوله مجال مغناطيسي تتأثر به الأبرة المغناطيسية فتنحرف.","ministerial":false},{"type":"علل","question":"ينعكس اتجاه الأبرة المغناطيسية الموضوعة بموازاة سلك يمر به تيار كهربائي عند عكس هذا التيار.","answer":"ينعكس اتجاه الأبرة المغناطيسية بسبب تغير اتجاه المجال المغناطيسي عند عكس اتجاه التيار الكهربائي.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 نفّذ النشاط: برادة الحديد تكشف المجال"},{"chapter_number":6,"chapter_title":"🌀 الفصل السادس: الكهربائية والمغناطيسية","lesson_number":3,"lesson_title":"➰ الدرس 3: مجال الحلقة الدائرية والملف المحلزن","order_index":3,"hook":"الملف المحلزن الذي فيه تيار يتصرف تماماً مثل ساق مغناطيسية: خطوط متوازية بالداخل ومقفلة بالخارج... لكن بميزة خارقة: يمكنك إطفاؤه!","concepts":[],"laws":[],"notes":[],"tables":[{"caption":"قارن بين خطوط المجال المغناطيسي حول الساق مغناطيسية وحول ملف ينساب فيه تيار كهربائي مستمر.","headers":["خطوط المجال المغناطيسي لساق مغناطيسية","خطوط المجال المغناطيسي حول ملف محلزن"],"rows":[["تنشأ من ترتيب جزيئات الساق الممغنطة باتجاه واحد تقريبا","تنشأ من مرور التيار الكهربائي المستمر داخل الملف"],["خطوط دائرية الشكل تقريبا","خطوط بيضوية الشكل تقريبا"],["المجال المغناطيسي دائمي","المجال المغناطيسي يتلاشى بانقطاع التيار"],["لا يمكن التحكم في المجال المغناطيسي","يمكن التحكم في المجال المغناطيسي"]],"ministerial":false}],"examples":[],"qa":[{"type":"نشاط","question":"س/ أشرح نشاط يوضح تخطيط المجال المغناطيسي لتيار كهربائي مستمر ينساب في حلقة دائرية؟","answer":"أدوات النشاط: ورقة مقوى، عدد من الموصلات المغناطيسية، حلقة من سلك غليظ معزول، مفتاح كهربائي، بطارية فولطيتها مناسبة (عمود جاف)، برادة حديد.\n\nالخطوات:\n\n١. نثبت السلك الغليظ الدائري في لوح المقوى ونربط الدائرة الكهربائية.\n\n٢. نمرر التيار الكهربائي في السلك برهة زمنية ونضع في عدة مواقع عدد من البوصلات.\n\n٣. نعكس اتجاه التيار المنساب في الحلقة ونكرر الخطوات أعلاه.\n\n٤. نعيد عمل النشاط باستعمال برادة الحديد ونلاحظ ترتيبها نجد ان خطوط المجال المغناطيسي الناشئ في حلقة موصلة تكون خطوط بيضوية الشكل تزدحم داخل الحلقة وتكون عمودية عليها.\n\n٥. نكرر النشاط باستعمال ملف محلزن (عدة حلقات او لفات) بدلا من الحلقة سنلاحظ أن خطوط المجال المغناطيسي تكون متوازية مع بعضها داخل الملف.\n\nنستنتج: شكل المجال المغناطيسي داخل الملف المحلزن عبارة عن خطوط مستقيمة متوازية، اما خارج الملف، فتكون خطوط مقفلة.","ministerial":true},{"type":"سؤال","question":"ما هو شكل خطوط المجال المغناطيسي الناشئ من انسياب تيار كهربائي مستمر في حلقة موصلة دائرية؟","answer":"خطوط بيضوية الشكل تقريبا تزدحم داخل الحلقة وعمودية عليها.","ministerial":false},{"type":"سؤال","question":"ما هو شكل خطوط المجال المغناطيسي الناشئ من انسياب تيار كهربائي مستمر في ملف محلزن؟","answer":"خطوط بيضوية مقفلة خارج الملف ومستقيمة متوازية مع بعضها داخل الملف.","ministerial":false},{"type":"سؤال","question":"ما هو شكل المجال المغناطيسي داخل وخارج الملف الذي يسير فيه تيار كهربائي مستمر؟","answer":"ان شكل خطوط المجال المغناطيسي داخل الملف المحلزن عبارة عن خطوط مستقيمة متوازية اما خارج الملف فتكون عبارة عن خطوط مقفلة.","ministerial":false},{"type":"سؤال","question":"على ماذا يعتمد مقدار المجال المغناطيسي لتيار ينساب في ملف محلزن ؟","answer":"١. مقدار التيار (تناسب طردي).\n\n٢. عدد اللفات في واحدة الطول (تناسب طردي).","ministerial":false},{"type":"قارن","question":"قارن بين خطوط المجال المغناطيسي داخل الملف وخارجه من حيث المقدار و الاتجاه ؟","answer":"من حيث الاتجاه: داخل الملف من الجنوب إلى الشمال أما خارجة فيكون من الشمال إلى الجنوب.\n\nمن حيث المقدار: مقدار المجال المغناطيسي داخل الملف اكبر منه خارج الملف (علل) لأن خطوط المجال تتقارب داخل المغناطيس وتباعد خارجة.","ministerial":false},{"type":"علل","question":"مغناطيس شكل حرف U يكون فيه المجال المغناطيسي كبير بين الأقطاب ؟","answer":"لأن خطوط القوى المغناطيسية تتركز على القطبين وبما أنهما متقاربة فيزداد عددها لوحدة الزمن.","ministerial":false},{"type":"سؤال","question":"وضح هل يمكن أن يتولد مجال مغناطيسي حول شحنة كهربائية متحركة ؟ أعط مثال.","answer":"نعم يمكن أن يتولد مجال مغناطيسي حول شحنة متحركة كحركة الإلكترون حول النواة في الذرة.","ministerial":true},{"type":"قارن","question":"قارن بين خطوط المجال المغناطيسي حول الساق مغناطيسية وحول ملف ينساب فيه تيار كهربائي مستمر.","answer":"","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 مختبر الملف المحلزن"},{"chapter_number":6,"chapter_title":"🌀 الفصل السادس: الكهربائية والمغناطيسية","lesson_number":4,"lesson_title":"🧲 الدرس 4: المغناطيس الكهربائي","order_index":4,"hook":"في ساحات السكراب رافعات ترفع أطناناً من الحديد بمغناطيس... سرّه ملف حول قلب حديدي: تيار = مغناطيس، لا تيار = قطعة حديد عادية!","concepts":[{"term":"المغناطيس الكهربائي:","text":"هو مغناطيس مؤقت يزول بزوال التيار الكهربائي المنساب في السلك.","ministerial":true}],"laws":[],"notes":[{"heading":"","items":["المغناطيس الكهربائي مؤقت — يزول بزوال التيار. اما اذا اردنا الاحتفاظ بالمغناطيسية لفترة اطول نستعمل الفولاذ كقلب بدلاً من الحديد المطاوع."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"مما يتركب المغناطيس الكهربائي ؟","answer":"يتركب من قلب من الحديد المطاوع (شكل ساق مستقيمة أو شكل حرف U) يلف حوله سلك موصل معزول وترتبط نهايتي السلك بمصدر للتيار الكهربائي.","ministerial":true},{"type":"سؤال","question":"كيف يكون اتجاه لف السلك في المغناطيس الكهربائي؟","answer":"يكون في اتجاهين متعاكسين كما في المغناطيس الكهربائي شكل حرف U للحصول على قطبين مغناطيسيين أحدهما شمالي والآخر جنوبي.","ministerial":false},{"type":"علل","question":"يكون اتجاه لف السلك في المغناطيس حرف U حول قلب الحديد باتجاهين متعاكسين ؟","answer":"وذلك للحصول على قطبين مغناطيسيين أحدهما شمالي والآخر جنوبي.","ministerial":false},{"type":"سؤال","question":"وضح آلية عمل المغناطيس الكهربائي؟","answer":"عند إغلاق الدائرة الكهربائية يتولد ما يسمى بالمغناطيس الكهربائي وعند فتح الدائرة الكهربائية يتلاشى المجال المغناطيسي في قطعة الحديد المطاوع بسرعة.","ministerial":false},{"type":"سؤال","question":"كيف يمكن احتفاظ المغناطيس الكهربائي بالمغناطيسية لفترة أطول بعد انقطاع التيار الكهربائي ؟","answer":"نستعمل الفولاذ كقلب بدلا من الحديد المطاوع.","ministerial":false},{"type":"سؤال","question":"على ماذا يعتمد مقدار المجال المغناطيسي للمغناطيس الكهربائي ؟","answer":"١. عدد لفات الملف لوحده تطول.\n\n٢. نوع مادة القلب.\n\n٣. مقدار التيار الكهربائي المنساب في الملف.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من المغناطيس الكهربائي؟","answer":"١. استعماله في رفع قطع الفولاذ والحديد السكراب في المصانع ونقلها الى اماكن اخرى.\n\n٢. في الآلات الكهربائية التي تعتمد في عملها على التأثير المغناطيسي للتيار الكهربائي (تمغنط وقتي) كما في الجرس الكهربائي وانواع اخرى معقدة في الاجهزة الالكترونية المختلفة.\n\n٣. يستعمله الجراحون لازالة شظايا الحديد من الجروح وشظايا الحديد النابتة في العين.\n\n٤. يستعمل في المولدات الكهربائية والمحركات الكهربائية ذات الانارة.","ministerial":false},{"type":"سؤال","question":"بم يتميز المغناطيس الكهربائي عن المغناطيس الدائمي؟","answer":"١. يمكن إزالة مجاله المغناطيسي وذلك بقطع التيار عنه.\n\n٢. من الممكن عكس قطبي المغناطيس الكهربائي بعكس ربط قطبي البطارية الكهربائية ولا يمكن ذلك للمغناطيس الدائم.\n\n٣. يمكن تغير قوته المغناطيسية بتغير مقدار التيار المنساب خلال ملفه.\n\n٤. يمكنا من الحصول على مجال مغناطيسي يمكن السيطرة عليه.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 شغّل رافعة السكراب المغناطيسية"},{"chapter_number":6,"chapter_title":"🌀 الفصل السادس: الكهربائية والمغناطيسية","lesson_number":5,"lesson_title":"🔔 الدرس 5: الجرس والهاتف والمرحل","order_index":5,"hook":"حين تتكلم في الهاتف يتحول صوتك إلى تيار كهربائي متغير... يسافر في الأسلاك ثم يعود صوتاً عند سماعة صديقك — بفضل المغناطيس الكهربائي!","concepts":[],"laws":[],"notes":[{"heading":"","items":["يعمل الجرس الكهربائي على التيار المتناوب ولا يعمل على التيار المستمر."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"عرف الجرس الكهربائي ؟ ومم يتركب (اجزاؤه) ؟","answer":"هو جهاز للتنبيه يستثمر المغناطيس الكهربائي في الية عمله. ويتكون من:\n\n١. مغناطيس كهربائي بشكل حرف (U).\n\n٢. حافظه من الحديد المطاوع.\n\n٣. مسمار محوري.\n\n٤. مطرقة.\n\n٥. ناقوس معدني.","ministerial":true},{"type":"سؤال","question":"وضح الية عمل الجرس الكهربائي ؟","answer":"عند غلق المفتاح يعمل المغناطيس الكهربائي على جذب قطعة الحديد المطاوع فتتحرك المطرقة نحو الناقوس وتحدث صوتا وعندها تكون الدائرة الكهربائية مفتوحة لذا يفقد المغناطيس مغناطيسيته فتبتعد قطعة الحديد المطاوع عن المغناطيس الكهربائي عائدة إلى وضعها.","ministerial":true},{"type":"سؤال","question":"ما المقصود بالهاتف ؟","answer":"هو أحد وسائل الاتصال السلكية عن بوعد والتي تستعمل لإرسال واستقبال الموجات الصوتية بين شخصين أو أكثر من خلال سلكين يمر فيهما تيار كهربائي متغير وفق ذبذبات صوت المتكلم.","ministerial":false},{"type":"سؤال","question":"ما هي مكونات الهاتف ؟","answer":"١. لاقطة الصوت: وهي جهاز يقوم بتحويل الطاقة الصوتية إلى طاقة كهربائية.\n\n٢. السماعة: هي جهاز يقوم بتحويل الطاقة الكهربائية إلى طاقة صوتية مشابهة لصوت المتكلم في اللاقطة.","ministerial":false},{"type":"سؤال","question":"وضح آلية عمل الهاتف؟","answer":"عند التكلم أمام لاقطة يتغير مقدار التيار في الدائرة الكهربائية بفعل نبضات من التضاغط والتخلخل و بشكل مشابه لتردد موجات صوت المتكلم (التردد نفسه) وهذا التغير بالتيار ينتقل خلال الأسلاك إلى سماعة الهاتف الآخر والذي يمر عبر المغناطيس الكهربائي الذي يجذب بدوره قرصا من الحديد المطاوع فيتذبذب مولدا موجات صوتية في الهواء مشابهة لصوت المتكلم.","ministerial":true},{"type":"سؤال","question":"ما المقصود بالمرحل الكهربائي؟ ذاكرا استعمالات المرحل الكهربائي؟ او ما الغرض منه ؟ او الفائدة العملية ؟","answer":"عبارة عن مفتاح مغناطيسي يستعمل كأداة للتحكم في إغلاق وفتح الدائرة الكهربائية. وما الغرض منه:\n\n١. في السيارة يعمل المرحل بالتحكم في تشغيل دائرة التيار الكبير بواسطة تيار صغير عنده إدارة مفتاح تشغيل السيارة.\n\n٢. يعمل على فتح وإغلاق الدائرة الإلكترونية ذاتيآ.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من وجود المرحل في السيارة؟","answer":"للتحكم في تشغيل دائرة التيار الكبير (المحرك) عند بداية التشغيل بواسطة تيار صغير عنده إدارة مفتاح السيارة.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من وجود المرحل في الدوائر الإلكترونية؟","answer":"يعمل على فتح وإغلاق الدائرة الإلكترونية ذاتيآ.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 شغّل الجرس الكهربائي وشاهد آلية عمله"},{"chapter_number":6,"chapter_title":"🌀 الفصل السادس: الكهربائية والمغناطيسية","lesson_number":6,"lesson_title":"⚡ الدرس 6: الحث الكهرومغناطيسي والتيار المحتث","order_index":6,"hook":"تيار كهربائي يظهر في ملف بدون أي بطارية! السر كلمة واحدة: الحركة — حرّك المغناطيس وستولد الكهرباء.","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"نشاط","question":"اشرح نشاط توضح فيه كيفية توليد التيار الكهربائي باستعمال مجال مغناطيسي؟","answer":"الأدوات: ١- مغناطيس دائمي بشكل حرف U   ٢- كلفانوميتر   ٣- سلك موصل معزول.\n\nالخطوات:\n\n١. نصل طرفي السلك بطرفي الكلفانوميتر ونحرك السلك باتجاه موازي لخطوط المجال المغناطيسي نلاحظ عدم انحراف مؤشر الكلفانوميتر بسبب عدم حصول تغيير في المجال المغناطيسي.\n\n٢. نحرك السلك باتجاه عمودي على خطوط المجال نلاحظ انحراف مؤشر الكلفانوميتر باتجاهين متعاكسين على جانبي صفر الكلفانوميتر بسبب حصول تغيير في المجال المغناطيسي.\n\n٣. عند توقف الموصل عن الحركة نلاحظ عدم انحراف مؤشر الكلفانوميتر.\n\nالاستنتاج: إن التيار الكهربائي الآني (اللحظي) الذي يتولد في السلك على الرغم من عدم وجود بطارية في دائرته الكهربائية يسمى بالتيار المحتث لأنه تيار نشأ من تغيير المجال المغناطيسي.","ministerial":true},{"type":"نشاط","question":"وضح بنشاط عملي تبين في كيفية توليد القوة الدافعة الكهربائية المحتثه ؟","answer":"الأدوات: ١- ساق مغناطيسية   ٢- ملف اسطواني   ٣- كلفانوميتر.\n\nالخطوات:\n\n١. نربط طرفي الملف بطرفي الكلفانوميتر.\n\n٢. نحرك المغناطيس و نقربها من الملف بموازاة طول الملف ونلاحظ انحراف مؤشر الكلفانوميتر الذي يشير إلى انسياب التيار المحتث فيه.\n\n٣. نثبت المغناطيس بالقرب من الملف (نلاحظ استقرار مؤشر الكلفانوميتر عند الصفر يعني عدم تولد تيار محتث).\n\n٤. نسحب الساق المغناطيسية من داخل الملف إلى الخارج نلاحظ انحراف مؤشر الكلفانوميتر الذي يكون باتجاه معاكس للحالة السابقة.\n\nالاستنتاج: إن التيار المحدث في الدائرة الكهربائية المقفلة ينشأ عندما يتحرك المغناطيس او الملف مسببا تغير في خطوط المجال المغناطيسي بينما لا ينشأ التيار المحتث إذا لم يتحرك أي منهما لعدم حصول تغيير في خطوط المجال المغناطيسي.","ministerial":false},{"type":"سؤال","question":"ما هو التيار الكهربائي المحتث؟ وكيف ينشأ (يتولد)؟","answer":"هو تيار كهربائي ينشا في الدائرة الكهربائية المقفلة عندما تكون هناك حركة عمودية للمغناطيس داخل الملف او حركة الملف بصورة عمودية بالنسبة للمغناطيس مما يسبب تغيرا في خطوط المجال المغناطيسي. وتفسير توليد التيار المحتث هو بسبب تولد فرق جهد محتث على طرفي الموصل يسمى بالقوة الدافعة الكهربائية المحتثة emf والتي تقاس بوحدة الفولت.","ministerial":false},{"type":"سؤال","question":"","answer":"بسبب تولد قوة دافعة كهربائية محتثة (e.m.f محتثة) عبر طرفي ذلك السلك التي تكون بمثابة فرق الجهد اللازم لحركة الشحنات من طرف لآخر.","ministerial":false},{"type":"سؤال","question":"ما تفسير تولد التيار المحدث في الدائرة المقفلة؟","answer":"بسبب تولد قوة دافعة كهربائية محتثة على طرفي الموصل.","ministerial":false},{"type":"سؤال","question":"كيف يتولد التيار المحتث في الدائرة الكهربائية المقفلة؟","answer":"عندما يقطع السلك خطوط المجال المغناطيسي (عند حصول التغير في عدد خطوط القوة المغناطيسية في وحدة الزمن) ولا يتولد هذا التيار عندما يتحرك السلك في اتجاه موازي لخطوط المجال المغناطيسي.","ministerial":false},{"type":"سؤال","question":"ما الشروط الواجب توفرها لتوليد تيار كهربائي محتث ؟","answer":"١. أن يكون السلك الموصل او الملف جزءآ من دائرة كهربائية محتثة.\n\n٢. أن يتحرك المغناطيس او السلك او الملف مسبباً تغير في المجال مغناطيسي.","ministerial":false},{"type":"سؤال","question":"على ماذا يعتمد شدة التيار الكهربائي المحتث المتولد في الموصل ؟","answer":"١. عدد لفات الملف (يتناسب طرديا).\n\n٢. السرعة الحركة النسبية للمغناطيس أو الملف (يتناسب طرديا).\n\n٣. شدة القطب المغناطيسي (يتناسب طرديا).","ministerial":false},{"type":"سؤال","question":"عرف ظاهرة الحث الكهرومغناطيسي ومن الذي أكتشفها؟ وما الفائدة العملية لها؟","answer":"وهي ظاهرة توليد فولطية محتثة عبر موصل كهربائي يقع في مجال مغناطيسي متغير او عن طريق حركة نسبية بين الموصل والمجال المغناطيسي يحدث فيها تغير في المجال المغناطيسي. أكتشفها العالم فراداي.\n\nالفائدة العملية منها: تعتبر أساس عمل العديد من الأجهزة الكهربائية أهمها المولد الكهربائي حيث أدى اكتشاف الضاهرة الى تطور كبير في وسائل انتاج الطاقة الكهربائية ونقلها وتوزيعها خلال شبكات النقل.","ministerial":true},{"type":"سؤال","question":"ما الذي يحصل عند دوران ملف بين قطبي مغناطيس؟","answer":"عند دوران الملف داخل مجال مغناطيس منتظم قاطعا خطوط القوة المغناطيسية سيحدث تغيرا في خطوط القوة المغناطيسية فتتولد قوة دافعة كهربائية محتثة مسببة انسياب تيار كهربائي محتث متناوب في ملف النواة ينتقل عبر الحلقتين المعدنيتين.","ministerial":true},{"type":"علل","question":"عدم انحراف مؤشر الكلفانوميتر عند حركة الموصل بصورة موازية لخطوط المجال المغناطيسي؟","answer":"ان عدم انحراف مؤشر الكلفانوميتر بسبب عدم حصول تغير في المجال المغناطيسي.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 جرّب اكتشاف فرداي بنفسك"},{"chapter_number":6,"chapter_title":"🌀 الفصل السادس: الكهربائية والمغناطيسية","lesson_number":7,"lesson_title":"🏭 الدرس 7: المولد الكهربائي المتناوب والمستمر","order_index":7,"hook":"ملف يدور بين قطبي مغناطيس = كهرباء! هذه هي الفكرة كلها — وكل محطات الكهرباء في العالم مجرد نسخ عملاقة منها.","concepts":[],"laws":[],"notes":[{"heading":"","items":["التيار المتناوب: موجة تتغير في المقدار والاتجاه — التيار المستمر من المولد: يتغير في المقدار لكنه ثابت الاتجاه (أنصاف موجات موجبة)."],"ministerial":false}],"tables":[{"caption":"ما الفرق بين مولد التيار المتناوب و مولد التيار المستمر من حيث التيار الخارج والأجزاء؟","headers":["مولد التيار المتناوب","مولد التيار المستمر"],"rows":[["يولد تيار متغير في المقدار والاتجاه","يولد تيار متغير في المقدار الثابت في الاتجاه"],["يوصل طرفي ملفه بحلقتين معدنيتين منفصلتين","يوصل طرفا ملفه إلى نصفي حلقة معدنية معزولتين كهربائياً عن بعضهما (المبادل)"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"اذكر بعض تطبيقات ظاهرة الحث الذاتي ؟","answer":"١. المولد الكهربائي للتيار المتناوب.\n\n٢. المولد البسيط للتيار المستمر.","ministerial":false},{"type":"سؤال","question":"ما هو المولد الكهربائي للتيار المتناوب ؟ وما الفائدة العملية منه؟","answer":"هو جهاز يعمل على تحويل الطاقة الميكانيكية (الحركية) إلى طاقة كهربائية بوجود مجال مغناطيسي ويعد المصدر الرئيسي المستعمل في إنتاج الطاقة الكهربائية.","ministerial":true},{"type":"سؤال","question":"ما مبدأ عمل المولد الكهربائي ؟","answer":"اساس عمله هو مبدأ الحث الكهرومغناطيسي حسب اكتشاف العالم فرداي.","ministerial":true},{"type":"سؤال","question":"مما يتركب (المكونات الاساسية) المولد الكهربائي للتيار المتناوب ؟","answer":"١. ملف من سلك موصل معزول ملفوف حول قلب من الحديد المطاوع.\n\n٢. حلقتين معزولتين بعضهما.\n\n٣. فرشتان من الكاربون (فحمات).\n\n٤. مغناطيس دائمي أو مغناطيس كهربائي بشكل حرف U.","ministerial":true},{"type":"سؤال","question":"وضح عمل المولد الكهربائي (أو ماذا يحدث عنده دوران ملف بين قطبي المغناطيس)؟","answer":"عند دوران الملف داخل المجال مغناطيسي منتظم قاطعا خطوط القوة المغناطيسية تتولد قوة دافعة كهربائية محتثه emf مسببة انسياب تيار كهربائي محتث متناوب في ملف النواة ينتقل عبر الحلقتين المعدنيتين والفرشاتين الملامستين لهما إلى الدائرة الكهربائية الخارجية ويسمى بالتيار المتناوب.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من فرشتها الكاربون (الفحمات)؟","answer":"ربط الملف في الدائرة الخارجية الكهربائية.","ministerial":false},{"type":"سؤال","question":"مم يتركب مولد التيار المستمر؟","answer":"١. ملف من سلك موصل معزول ملفوف حول قلب من الحديد المطاوع.\n\n٢. المبادل (عبارة عن نصفي حلقة معدنية معزولتين كهربائيا عن بعضهما و متصلتين بطرفي ملف النواة).\n\n٣. فرشتان من الكاربون (فحمات).\n\n٤. مغناطيس دائمي بشكل حرف U.","ministerial":false},{"type":"سؤال","question":"ما فائدة المبادل في المولد البسيط للتيار المستمر؟","answer":"يعطي تيار باتجاه واحد والذي يسمى بالتيار المستمر.","ministerial":false},{"type":"سؤال","question":"كيف يمكن تحويل مولد تيار متناوب إلى مولد التيار المستمر؟","answer":"يتم تحويل مولد تيار متناوب إلى مولد التيار المستمر وذلك برفع حلقتي الزلق منه وربط طرفي الملف بنصفي حلقة معدنية معزولتين كهربائيا ومتصلتين بطرفي ملف النواة تسمى المبادل.","ministerial":true},{"type":"قارن","question":"ما الفرق بين مولد التيار المتناوب و مولد التيار المستمر من حيث التيار الخارج والأجزاء؟","answer":"","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 شغّل المولد الكهربائي وشاهد شكل التيار"},{"chapter_number":6,"chapter_title":"🌀 الفصل السادس: الكهربائية والمغناطيسية","lesson_number":8,"lesson_title":"⚙️ الدرس 8: المحرك الكهربائي","order_index":8,"hook":"المروحة، الخلاط، المكنسة، المثقاب... كل جهاز «يدور» في بيتك بداخله محرك كهربائي — سلك فيه تيار داخل مجال مغناطيسي فيتحرك!","concepts":[{"term":"المحرك الكهربائي:","text":"هو جهاز يحول الطاقة الكهربائية إلى طاقة ميكانيكية بوجود مجال مغناطيسي متغير.","ministerial":true}],"laws":[],"notes":[],"tables":[{"caption":"⚖️ المولد × المحرك: لا تخلط بينهما!","headers":["","المولد الكهربائي","المحرك الكهربائي"],"rows":[["التحويل","ميكانيكية (حركية) ⟵ كهربائية","كهربائية ⟵ ميكانيكية"],["المبدأ","الحث الكهرومغناطيسي (فرداي)","القوة المغناطيسية المؤثرة في سلك يحمل تياراً داخل مجال مغناطيسي"]],"ministerial":false}],"examples":[],"qa":[{"type":"سؤال","question":"ما هو مبدأ عمل المحرك الكهربائي؟ أو علام يعتمد؟","answer":"مبدأ عمله: يعتمد على مبدأ القوة المغناطيسية المؤثرة في سلك ينساب فيه تيار كهربائي مستمر موضوع في مجال مغناطيسي.","ministerial":true},{"type":"سؤال","question":"أذكر عدد من الأجهزة التي يستخدم فيها المحرك الكهربائي؟","answer":"يستخدم المحرك الكهربائي في تشغيل العديد من الاجهزة مثل: المكنسة الكهربائية، المثقاب الكهربائي، الخلاط الكهربائي، المروحة الكهربائية وغيرها.","ministerial":false},{"type":"سؤال","question":"ما هي مكونات المحرك الكهربائي الذي يعمل بالتيار المستمر ؟","answer":"١. نواة المحرك: عبارة عن ملف من سلك من النحاس معزول يحوي داخله على قطعة من الحديد المطاوع.\n\n٢. مغناطيس دائمي قوي يوضع الملف بين قطبيه.\n\n٣. المبادل: عبارة عن نصفي حلقة معدنية معزولتين عن بعضهما ويتصلان بطرفي سلك ملف النواة يدورون مع ملف النواة.\n\n٤. فرشتان من الكاربون تلمسان نصفي المبادل متصلتان بقطبي مصدر للتيار الكهربائي المستمر.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من وجود المبادل في المحرك؟","answer":"يعمل المبادل على عكس قطبية التيار المتناوب ليزود المحرك بتيار نبضي بأتجاه واحد يحافظ على استمرارية دوران نواة المحرك باتجاه واحد.","ministerial":true},{"type":"سؤال","question":"اشرح عمل المحرك الكهربائي ؟ ماذا يحصل عندما ينساب تيار كهربائي مستمر في نواة المحرك الكهربائي؟","answer":"عند إغلاق الدائرة الكهربائية ينساب تيار كهربائي مستمر في الدائرة الخارجية إلى ملف النواة ويمر في طرفي الملف باتجاهين متعاكسين و بتأثير المجال المغناطيسي للتيار المار في ملف النواة والمجال الناشئ عن المغناطيس الدائم تتولد قوتان متعاكستان في الاتجاه متساويتان في المقدار على جانبي الملف تعملان على تدوير الملف حول محورها داخل مجال مغناطيسي ويستمر الملف بالدوران باتجاه واحد بسبب وجود المبادل.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 شغّل المحرك الكهربائي"},{"chapter_number":7,"chapter_title":"🔌 الفصل السابع: المحولة الكهربائية","lesson_number":1,"lesson_title":"🔎 الدرس 1: التيار المحتث والمحولة الكهربائية","order_index":1,"hook":"شاحن موبايلك يأخذ 220 فولت من القابس ويعطي جهازك 5 فولت فقط... من غيّر الرقم؟ إنها محوّلة صغيرة مخبّأة داخل الشاحن!","concepts":[],"laws":[],"notes":[{"heading":"","items":["في بعض الأحيان يتطلب الأمر تغيير الفولطية المتناوبة أما برفع مقدارها أو بخفضه، ولتغيير مقدار الفولطية الخارجة من أي مصدر متناوب نستخدم (المحولة الكهربائية)."],"ministerial":false},{"heading":"","items":["يتولد التيار المحتث في الملف الثانوي للمحولة نتيجة تغيير خطوط المجال المغناطيسي خلال قلب الحديد."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"أين تُستثمر الطاقة الكهربائية؟","answer":"تُستثمر الطاقة الكهربائية في الإضاءة والتدفئة وتشغيل الأجهزة الكهربائية المختلفة...","ministerial":false},{"type":"سؤال","question":"كيف يتولد التيار المحتث؟","answer":"يتولد التيار المحتث من تغير خطوط المجال المغناطيسي خلال الموصل في وحدة الزمن أو نتيجة حصول حركة نسبية بين الموصل والمجال المغناطيسي الواشج للموصل مقترنة بحدوث تغير في الفيض المغناطيسي الواشج.","ministerial":false},{"type":"نشاط","question":"كيف يتولد تيار محتث في ملف ثانوي نتيجة لتغير خطوط المجال المغناطيسي المتولد في الملف الابتدائي؟ وضّح ذلك بنشاط.","answer":"الأدوات: ١. ملف بشكل أسطوانة مجوّفة ٢. ملف حلقي الشكل ٣. مصباح كهربائي ٤. مصدر فولطية متناوب ٥. مفتاح ٦. ساق من الحديد المطاوع طويل نسبياً.\nالعمل:\n١. نضع داخل الملف الأسطواني ساق حديد مطاوع طويل نسبياً.\n٢. نربط مصدر الفولطية المتناوبة والمفتاح على التوالي بين طرفي الملف الأسطواني فتُدعى الدائرة بدائرة الملف الابتدائي.\n٣. نربط المصباح الكهربائي بالملف الحلقي (فيُدعى هذا الملف بالملف الثانوي).\n٤. نغلق دائرة الملف الابتدائي نلاحظ توهّج المصباح المربوط بالملف الثانوي.\nالاستنتاج: يتولد تيار محتث في الملف الثانوي نتيجة لتغير خطوط المجال المغناطيسي في وحدة الزمن المتولد في الملف الابتدائي والذي يسببه انسياب التيار المتناوب فيه.","ministerial":true},{"type":"سؤال","question":"كيف يتولد تيار كهربائي محتث في الملف الثانوي للمحولة الكهربائية؟","answer":"نتيجة لتغيير خطوط المجال المغناطيسي في وحدة الزمن المتولد في الملف الابتدائي والذي سببه انسياب التيار المتناوب فيه.","ministerial":false},{"type":"سؤال","question":"ما المقصود بالمحولة الكهربائية؟","answer":"المحولة الكهربائية: هي جهاز يعمل على رفع الفولطية المتناوبة أو خفضها فيقل التيار أو يزداد نتيجة لذلك.","ministerial":true},{"type":"سؤال","question":"ممّ تتألف المحولة الكهربائية؟ أو ما مكوناتها؟","answer":"تتألف من ملفّين مصنوعين من أسلاك نحاسية معزولة ملفوفة حول قلب مغلق من الحديد المطاوع وهما:\n١. الملف الابتدائي: عبارة عن ملف مربوط مع مصدر الفولطية المتناوبة (الفولطية المجهّزة للطاقة) وعدد لفاته N₁.\n٢. الملف الثانوي: عبارة عن ملف مربوط مع الحمل (الجهاز الذي يشتغل على المحولة) وعدد لفاته N₂.","ministerial":false},{"type":"سؤال","question":"ما هو الملف الابتدائي والثانوي للمحولة؟ مع كتابة الرموز لكل واحد منهما","answer":"الملف الابتدائي: وهو ملف مصنوع من أسلاك موصلة معزولة وملفوف حول القلب الحديد المطاوع ويربط طرفاه مع مصدر الفولطية المتناوبة، ويُرمز له بالرمز N₁ ويقاس بوحدة (turn) (لفة).\nالملف الثانوي: وهو ملف مصنوع من أسلاك موصلة معزولة وملفوف حول القلب الحديد المطاوع ويربط طرفاه مع الحمل الذي يعمل على الفولطية المتناوبة المجهّزة من قبل المحولة، ويُرمز له بالرمز N₂ ويقاس بوحدة (turn) (لفة).","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 نفّذ النشاط: أغلق الدائرة وراقب المصباح"},{"chapter_number":7,"chapter_title":"🔌 الفصل السابع: المحولة الكهربائية","lesson_number":2,"lesson_title":"🔁 الدرس 2: مبدأ عمل المحولة (الحث المتبادل)","order_index":2,"hook":"الملف الابتدائي «يتكلم» والملف الثانوي «يسمع» — واللغة بينهما هي خطوط المجال المغناطيسي المتغيّرة في القلب. هذا هو الحث المتبادل.","concepts":[],"laws":[],"notes":[{"heading":"","items":["مبدأ عمل المحولة: الحث المتبادل بين ملفين متجاورين بينهما تواشج تام يوفّره القلب الحديد المغلق."],"ministerial":true}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"كيف تعمل المحولة الكهربائية؟","answer":"تعمل على أساس ظاهرة الحث المتبادل بين الملفين، فعند انسياب تيار متناوب في الملف الابتدائي للمحولة يولّد مجالاً مغناطيسياً متغيّراً داخل القلب الحديدي فيشجّ هذا المجال الملف الثانوي كما يشجّ الملف الابتدائي.","ministerial":false},{"type":"سؤال","question":"ما هو أساس عمل المحولة (مبدأ عمل المحولة)؟","answer":"الحث المتبادل بين ملفين متجاورين بينهما تواشج تام يوفّره القلب الحديد المغلق.","ministerial":true},{"type":"سؤال","question":"ما فائدة القلب المغلق من الحديد المطاوع في المحولة؟","answer":"يوفّر تواشجاً تاماً بين الملفين الابتدائي والثانوي، أي يوجّه خطوط المجال المغناطيسي كلها لتمرّ خلال الملف الثانوي فلا تتسرّب، فتنتقل الطاقة بينهما بأعلى كفاءة ممكنة.","ministerial":false},{"type":"سؤال","question":"ما الظاهرة التي تعمل بها المحولة الكهربائية؟","answer":"ظاهرة الحث الكهرومغناطيسي المتبادل بين الملفين.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 شاهد الحث المتبادل داخل المحولة"},{"chapter_number":7,"chapter_title":"🔌 الفصل السابع: المحولة الكهربائية","lesson_number":3,"lesson_title":"🔄 الدرس 3: لماذا التيار المتناوب؟","order_index":3,"hook":"البطارية تعطي تياراً ثابتاً لا يتغيّر... والمحولة تحتاج تغيّراً لتعمل. تيار ثابت = فيض ثابت = لا تيار محتث = لا شيء!","concepts":[],"laws":[],"notes":[{"heading":"","items":["المحولة الكهربائية تعمل على التيار المتناوب."],"ministerial":true}],"tables":[],"examples":[],"qa":[{"type":"علل","question":"تُعدّ المحولة الكهربائية من أجهزة التيار المتناوب؟","answer":"لأنها لا تعمل على التيار المستمر الذي لا يولّد تياراً محتثاً في الملف الثانوي لعدم حدوث تغير في المجال المغناطيسي داخل القلب الحديد.","ministerial":false},{"type":"علل","question":"تحتاج المحولة الكهربائية لاشتغالها إلى تيار متناوب؟","answer":"لأن التيار المتناوب ينعكس اتجاهه دورياً فيولّد تغيراً في الفيض المغناطيسي خلال الملفين ويتولد تيار محتث في كل من الملفين، وتنتقل القدرة الكهربائية بين الملفين بسبب التغير الحاصل في الفيض المغناطيسي الذي ولّده التيار المتناوب خلال قلب الحديد المغلق.","ministerial":true},{"type":"علل","question":"لا تعمل المحولة الكهربائية على التيار المستمر؟","answer":"لأن التيار الكهربائي المستمر ثابت في المقدار والاتجاه لا يولّد تغيراً في المجال المغناطيسي داخل القلب الحديدي وبالتالي لا يولّد تياراً محتثاً في الملف الثانوي للمحولة.","ministerial":false},{"type":"سؤال","question":"هل تعمل المحولة الكهربائية لو وُضعت بطارية بين طرفي ملفها الابتدائي؟ وضّح ذلك.","answer":"لا تعمل، لأن تيار البطارية تيار مستمر ثابت المقدار والاتجاه فلا يولّد تغيراً في المجال المغناطيسي ولا يولّد تياراً محتثاً في الملف الثانوي.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 جرّب بنفسك: تيار متناوب أم بطارية؟"},{"chapter_number":7,"chapter_title":"🔌 الفصل السابع: المحولة الكهربائية","lesson_number":4,"lesson_title":"🧮 الدرس 4: قانون المحولة ونسبة التحويل","order_index":4,"hook":"تريد فولطية أعلى؟ لفّ لفّات أكثر على الملف الثانوي. تريد فولطية أقل؟ قلّل لفّاته. بهذه البساطة تسيطر المحولة على الفولطية.","concepts":[],"laws":[],"notes":[{"heading":"","items":["الفولطية تتناسب طردياً مع عدد اللفات: V₂ / V₁ = N₂ / N₁.","نسبة التحويل N₂/N₁: أكبر من 1 ⟵ رافعة، أقل من 1 ⟵ خافضة."],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال ١: محولة V₁ = 220V وعدد لفات ملفها الابتدائي N₁ = 800 والثانوي N₂ = 400. جد فولطية الثانوي V₂ ونوع المحولة.","givens":"","solution_steps":["الخطوة ١: نكتب القانون: N₂ / N₁ = V₂ / V₁","الخطوة ٢: نرتّب لإيجاد V₂: V₂ = V₁ × ( N₂ / N₁ ) = 220 × ( 400 / 800 )","الخطوة ٣: نحسب: V₂ = 220 × 0.5 = 110 V","النوع: نسبة التحويل N₂/N₁ = 400/800 = 0.5 < 1 ⟵ محولة خافضة للفولطية."],"ministerial":false},{"problem":"مثال ٢: محولة V₁ = 120V و N₁ = 200 لفة و N₂ = 600 لفة. جد V₂ ونوع المحولة.","givens":"","solution_steps":["الخطوة ١: V₂ = V₁ × ( N₂ / N₁ ) V₂ = 120 × ( 600 / 200 )","الخطوة ٢: V₂ = 120 × 3 = 360 V","النوع: N₂/N₁ = 3 > 1 ⟵ محولة رافعة للفولطية."],"ministerial":false},{"problem":"مثال ٣ (من الملزمة): محولة رُبط ملفها الابتدائي بمصدر متناوب 240V، والجهاز (الحمل) على ثانويها يشتغل على 12V، وعدد لفات الابتدائي 500 لفة. ما نوع المحولة؟ واحسب عدد لفات الثانوي.","givens":"المعطيات: V₁ = 240V ، V₂ = 12V ، N₁ = 500 لفة ، N₂ = ؟","solution_steps":["١) النوع: V₁ (240) أكبر من V₂ (12) ⟵ محولة خافضة.","٢) عدد لفات الثانوي: V₂ / V₁ = N₂ / N₁ ⟹ 12 / 240 = N₂ / 500","نحلّ: N₂ = ( 500 × 12 ) / 240 = 25 لفة (turn)"],"ministerial":false}],"qa":[{"type":"سؤال","question":"وضّح كيف تعمل المحولة الكهربائية على تغيير مقدار الفولطية الخارجة؟","answer":"بتغيّر عدد لفات الملف الثانوي، وكما يلي — فبما أن الفولطية V تتناسب طردياً مع عدد لفات الملف N: N₂ / N₁ = V₂ / V₁\nN₂ × V₁ = N₁ × V₂\nV₂ = V₁ × ( N₂ / N₁ )","ministerial":false},{"type":"سؤال","question":"ماذا تُسمّى النسبة N₂ / N₁ ؟","answer":"تُسمّى نسبة التحويل، وهي التي تحدّد نوع المحولة (رافعة أم خافضة).","ministerial":false},{"type":"سؤال","question":"متى تكون المحولة خافضة ورافعة للفولطية بالاعتماد على نسبة التحويل؟","answer":"إذا كانت نسبة التحويل أكبر من الواحد ( N₂/N₁ > 1 ) فإن المحولة رافعة للفولطية.\nإذا كانت نسبة التحويل أقل من الواحد ( N₂/N₁ < 1 ) فإن المحولة خافضة للفولطية.","ministerial":true}],"has_simulation":true,"simulation_title":"🧪 حاسبة المحولة: احسب V₂ واعرف نوعها"},{"chapter_number":7,"chapter_title":"🔌 الفصل السابع: المحولة الكهربائية","lesson_number":5,"lesson_title":"⚖️ الدرس 5: علاقة القدرة والتيار","order_index":5,"hook":"تخيّل القدرة كقطعة كعك ثابتة الحجم: المحولة تعيد تقطيعها فقط — فولطية أكبر × تيار أصغر، أو فولطية أصغر × تيار أكبر. الحاصل واحد!","concepts":[],"laws":[],"notes":[{"heading":"","items":["المحولة الرافعة للفولطية تكون خافضة للتيار في الوقت نفسه، وبالعكس المحولة الخافضة للفولطية تكون رافعة للتيار في الوقت نفسه.","لاحظ: التيار يتناسب عكسياً مع عدد اللفات ( I₁/I₂ = N₂/N₁ )."],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال ١ (من الملزمة): محولة مثالية N₁ = 600 لفة و N₂ = 1800 لفة، والقدرة المتناوبة الداخلة في الابتدائي 720W بفولطية 240V. احسب التيار المنساب في ملفها الثانوي.","givens":"المعطيات: N₁ = 600 ، N₂ = 1800 ، P₁ = 720W ، V₁ = 240V ، I₂ = ؟","solution_steps":["الخطوة ١: نوجد تيار الابتدائي من القدرة: P₁ = I₁ × V₁ ⟹ 720 = I₁ × 240 ⟹ I₁ = 720/240 = 3 A","الخطوة ٢: نستخدم N₂/N₁ = I₁/I₂: 1800 / 600 = 3 / I₂ ⟹ 3 = 3 / I₂","الخطوة ٣: نحلّ: I₂ = 3 / 3 = 1 A"],"ministerial":false},{"problem":"مثال ٢ (من الملزمة): محولة كفاءتها 100% ونسبة التحويل فيها ½ تعمل على فولطية متناوبة 220V والتيار المنساب في ملفها الثانوي 1.1A. احسب: ١) فولطية الثانوي ٢) تيار الابتدائي.","givens":"المعطيات: V₁ = 220V ، N₂/N₁ = ½ ، I₂ = 1.1A","solution_steps":["١) فولطية الثانوي: نستخدم N₂/N₁ = V₂/V₁: ½ = V₂ / 220 ⟹ 2V₂ = 220 ⟹ V₂ = 110 V","٢) تيار الابتدائي: نستخدم N₂/N₁ = I₁/I₂: ½ = I₁ / 1.1 ⟹ 2I₁ = 1.1 ⟹ I₁ = 0.55 A"],"ministerial":false},{"problem":"مثال ٣ (من الملزمة): مصباح مكتوب عليه (6V, 12W) رُبط مع الملف الثانوي لمحولة مثالية، والابتدائي مع مصدر متناوب 240V وعدد لفات الابتدائي 8000 لفة، فتوهّج المصباح توهجاً اعتيادياً. احسب: ١) عدد لفات الثانوي ٢) التيار في المصباح ٣) التيار في الابتدائي.","givens":"المعطيات: V₂ = 6V ، P₂ = 12W ، V₁ = 240V ، N₁ = 8000","solution_steps":["١) لفات الثانوي: V₂/V₁ = N₂/N₁: 6/240 = N₂/8000 ⟹ N₂ = (6 × 8000)/240 = 200 لفة","٢) تيار المصباح (الثانوي): P₂ = I₂ × V₂: 12 = I₂ × 6 ⟹ I₂ = 12/6 = 2 A","٣) تيار الابتدائي: I₁/I₂ = V₂/V₁: I₁/2 = 6/240 ⟹ I₁ = (2 × 6)/240 = 0.05 A"],"ministerial":false}],"qa":[{"type":"تذكير","question":"علاقة القدرة بفرق الجهد والتيار","answer":"درسنا سابقاً أن: القدرة = فرق الجهد × التيار P = I × V","ministerial":false},{"type":"سؤال","question":"اكتب القدرة الداخلة في الابتدائي والخارجة من الثانوي","answer":"القدرة الداخلة في الملف الابتدائي = تيار الابتدائي × فولطية الابتدائي: P₁ = I₁ × V₁ القدرة الخارجة من الملف الثانوي = تيار الثانوي × فولطية الثانوي: P₂ = I₂ × V₂","ministerial":false},{"type":"سؤال","question":"ما العلاقة في المحولة المثالية؟","answer":"إذا فرضنا أن القدرة الداخلة تساوي القدرة الخارجة (أي أن المحولة مثالية لا يحصل ضياع في القدرة) فيمكننا القول: P₁ = P₂ ⟹ I₁ × V₁ = I₂ × V₂","ministerial":false},{"type":"اشتقاق","question":"ربط اللفات بالفولطية والتيار","answer":"من I₁ × V₁ = I₂ × V₂ نرتّب فنحصل على: V₂ / V₁ = I₁ / I₂ ... (1) وبما أن الفولطية تتناسب طردياً مع عدد اللفات: V₂ / V₁ = N₂ / N₁ ... (2) وبمقارنة (1) و(2) نحصل على العلاقة الكاملة: N₂ / N₁ = V₂ / V₁ = I₁ / I₂","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 حاسبة المحولة المثالية الكاملة"},{"chapter_number":7,"chapter_title":"🔌 الفصل السابع: المحولة الكهربائية","lesson_number":6,"lesson_title":"📊 الدرس 6: كفاءة المحولة","order_index":6,"hook":"محولة كفاءتها 95% تعني: من كل 100 واط تدخلها، يخرج 95 واط مفيداً ويضيع 5 واط حرارةً. كلما قلّت الخسائر، ارتفعت الكفاءة نحو 100%.","concepts":[],"laws":[],"notes":[{"heading":"","items":["كفاءة المحولة: η = (P₂/P₁) × 100% ، والقدرة المفقودة PLoss = P₁ − P₂.","كلما قلّت خسائر القدرة اقتربت الكفاءة من 100% (المحولة المثالية)."],"ministerial":false}],"tables":[],"examples":[{"problem":"مثال ١ (من الملزمة): إذا كانت القدرة الداخلة في الملف الابتدائي لمحولة (220W) وخسائر القدرة فيها (11W). جد كفاءة المحولة.","givens":"المعطيات: P₁ = 220W ، PLoss = 11W ، η = ؟","solution_steps":["الخطوة ١: نوجد القدرة الخارجة: P₂ = P₁ − PLoss = 220 − 11 = 209 W","الخطوة ٢: نطبّق قانون الكفاءة: η = (P₂/P₁) × 100% = (209/220) × 100%","الخطوة ٣: η = 95 %"],"ministerial":false},{"problem":"مثال ٢ (من الملزمة): محولة كهربائية كفاءتها (80%) والقدرة الخارجة منها (4.8 kW). ما مقدار القدرة الداخلة في المحولة؟","givens":"المعطيات: η = 80% ، P₂ = 4.8 kW ، P₁ = ؟","solution_steps":["الخطوة ١: من قانون الكفاءة: η = (P₂/P₁) × 100% ⟹ 80/100 = 4.8/P₁","الخطوة ٢: ضرب تبادلي: 80 × P₁ = 100 × 4.8","الخطوة ٣: P₁ = (100 × 4.8)/80 = 480/80 = 6 kW"],"ministerial":false},{"problem":"مثال ٣ (من الملزمة): محولة كهربائية كفاءتها 95% إذا كانت القدرة الداخلة منها (9.5 kW). ما مقدار القدرة الخارجية في المحولة؟","givens":"المعطيات: η = 95% ، P₁ = 9.5 kW ، P₂ = ؟","solution_steps":["الخطوة ١: من قانون الكفاءة: η = (P₂/P₁) × 100% ⟹ 95/100 = P₂/9.5","الخطوة ٢: ضرب تبادلي: 100 × P₂ = 95 × 9.5","الخطوة ٣: P₂ = (95 × 9.5)/100 ≈ 9 kW"],"ministerial":false}],"qa":[{"type":"سؤال","question":"ما المقصود بكفاءة المحولة؟ واكتب قانونها","answer":"كفاءة المحولة: النسبة بين القدرة الخارجية P₂ إلى القدرة الداخلة P₁ مضروبة في 100%، ويُرمز لها بالرمز η (وتُسمّى إيتا). η = ( P₂ / P₁ ) × 100%كفاءة المحولة = (القدرة الخارجة ÷ القدرة الداخلة) × 100%","ministerial":false},{"type":"سؤال","question":"ما العلاقة بين القدرة الداخلة والخارجة والقدرة المفقودة؟","answer":"القدرة المفقودة (الضائعة) = القدرة الداخلة − القدرة الخارجة: PLoss = P₁ − P₂","ministerial":false}],"has_simulation":true,"simulation_title":"🧪 حاسبة كفاءة المحولة"},{"chapter_number":7,"chapter_title":"🔌 الفصل السابع: المحولة الكهربائية","lesson_number":7,"lesson_title":"🔥 الدرس 7: خسائر القدرة في المحولة","order_index":7,"hook":"ضع يدك على محوّلة تعمل منذ ساعات... ستجدها دافئة! تلك الحرارة هي القدرة الضائعة — عدوّ الكفاءة الذي يحاربه المهندسون بذكاء.","concepts":[],"laws":[],"notes":[{"heading":"","items":["هناك نوعان من خسائر القدرة في المحولة: خسائر ناتجة عن مقاومة أسلاك الملفين وخسائر ناتجة عن التيارات الدوامة."],"ministerial":true}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما أنواع خسائر القدرة في المحولة الكهربائية؟ وكيف يمكن تقليلها؟","answer":"١. خسارة ناتجة عن مقاومة أسلاك الملفين: تظهر بشكل طاقة حرارية في أسلاك الملفين، ولتقليلها تُصنع الأسلاك من مادة ذات مقاومة صغيرة المقدار (النحاس مثلاً).\n٢. خسارة التيارات الدوامة: تظهر بشكل طاقة حرارية في القلب الحديد، ولتقليلها يُصنع قلب المحولة بشكل صفائح من الحديد رقيقة ومعزولة ومكبوسة.","ministerial":true},{"type":"سؤال","question":"وضّح الخسارة الناتجة عن مقاومة أسلاك الملفين وكيف يمكن التقليل منها؟","answer":"خسائر ناتجة عن مقاومة أسلاك الملفين تظهر بشكل طاقة حرارية في أسلاك الملف الابتدائي والملف الثانوي أثناء اشتغال المحولة وهي ناتجة عن المقاومة الأومية لأسلاك الملفين، ولتقليل هذه الخسارة تُصنع أسلاك الملفين من مادة ذات مقاومة صغيرة المقدار (كالنحاس).","ministerial":false},{"type":"سؤال","question":"ما المقصود بالتيارات الدوامة؟","answer":"وهي تيارات محتثّة داخل القلب الحديد للمحولة أثناء اشتغالها تتولّد بسبب التغير الحاصل في خطوط المجال المغناطيسي خلال قلب الحديد، وتظهر بشكل طاقة حرارية فيه.","ministerial":true},{"type":"علل","question":"تُصنع أسلاك الملفين للمحولة من مادة ذات مقاومة صغيرة المقدار (النحاس)؟","answer":"وذلك لتقليل الخسارة الناتجة من مقاومة أسلاك الملفين والتي تظهر بشكل طاقة حرارية في الأسلاك.","ministerial":false},{"type":"علل","question":"يُصنع قلب المحولة الكهربائية بشكل صفائح من الحديد المطاوع رقيقة ومعزولة عن بعضها البعض كهربائياً ومكبوسة؟","answer":"لتقليل الخسائر الناتجة من التيارات الدوامة.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 التيارات الدوامة: قلب مصمت مقابل قلب مصفّح"},{"chapter_number":7,"chapter_title":"🔌 الفصل السابع: المحولة الكهربائية","lesson_number":8,"lesson_title":"🏙️ الدرس 8: نقل الطاقة والاستعمالات","order_index":8,"hook":"القاعدة الذهبية لنقل الكهرباء: فولطية عالية جداً وتيار واطئ جداً. لماذا؟ لأن الخسارة الحرارية في الأسلاك تعتمد على التيار — قلّل التيار تقلّ الخسارة.","concepts":[],"laws":[],"notes":[{"heading":"","items":["تُنقل القدرة الكهربائية لمسافات بعيدة بفولطية عالية وتيار واطئ لتقليل الخسارة بسبب مقاومة الأسلاك.","عند محطة الإرسال تُستعمل محولة رافعة، وقبل دخول المدينة/المصنع محولة خافضة."],"ministerial":true}],"tables":[{"caption":"قارن بين المحولة الرافعة والمحولة الخافضة","headers":["المحولة الرافعة","المحولة الخافضة"],"rows":[["عدد لفات الملف الثانوي أكبر من عدد لفات ملفها الابتدائي","عدد لفات ملفها الثانوي أقل من عدد لفات الملف الابتدائي"],["الفولطية الخارجة من الملف الثانوي أكبر من الفولطية الداخلة إلى ملفها الابتدائي","الفولطية الخارجة من الملف الثانوي أقل من الفولطية الداخلة إلى ملفها الابتدائي"],["التيار الخارج من ملفها الثانوي أقل من التيار الداخل إلى ملفها الابتدائي","التيار الخارج من ملفها الثانوي أكبر من التيار الداخل إلى ملفها الابتدائي"],["نسبة التحويل أكبر من واحد","نسبة التحويل أقل من واحد"],["مثل المحولة المستعملة في جهاز التلفاز لتجهيز الفولطية العالية للقاذف الإلكتروني للشاشة","مثل المحولات المستخدمة في جهاز اللحام الكهربائي"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"كيف تنتقل الطاقة الكهربائية إلى مسافات بعيدة؟ وضّح الفائدة من نقلها بفولطية عالية وتيار واطئ.","answer":"تنتقل القدرة الكهربائية إلى مسافات بعيدة بفولطية عالية وتيار واطئ، وذلك لتقليل الخسارة التي تحصل بسبب المقاومة الكبيرة في هذه الأسلاك.","ministerial":true},{"type":"سؤال","question":"لتجهيز القدرة الكهربائية من محطة توليدها إلى مصنع كبير يبعد عنها بُعداً معيّناً — ما نوع المحولة المستعملة: (١) في بداية خطوط نقل القدرة عند محطة الإرسال؟ (٢) في نهاية خطوط نقل القدرة قبل دخولها المصنع؟","answer":"١) في بداية نقل خطوط القدرة عند محطة الإرسال تُستعمل محولة رافعة (لرفع الفولطية وخفض التيار فتقلّ الخسارة).\n٢) في نهاية خطوط نقل القدرة قبل دخولها المصنع تُستعمل محولة خافضة (لخفض الفولطية إلى القيمة الآمنة للاستعمال).","ministerial":false},{"type":"سؤال","question":"اذكر استعمالات المحولة الخافضة","answer":"١. معظم المحولات المستعملة في الفولطية الداخلة إلى المنازل من هذا النوع.\n٢. المحولة المستعملة في مناطق استلام القدرة المجهّزة إلى المدن.\n٣. المحولة المستعملة في جهاز اللحام الكهربائي.\n٤. المحولة المستعملة في شاحنة الموبايل.","ministerial":false},{"type":"سؤال","question":"اذكر استعمالات المحولة الرافعة","answer":"١. المحولة المستعملة في جهاز التلفاز في تجهيز الفولطية العالية للقاذف الإلكتروني للشاشة.\n٢. المحولة المستعملة في محطات توليد الطاقة الكهربائية عند إرسالها إلى المدن.","ministerial":false},{"type":"سؤال","question":"في أي المجالات تُستعمل المحولة الكهربائية؟","answer":"المحولة الخافضة للفولطية: تُستعمل في المنازل في جهاز التسجيل والمذياع وشاحنة الموبايل وفي بعض الثلاجات الكهربائية وفي اللحام، وتُستعمل كذلك في نهاية خطوط نقل القدرة الكهربائية إلى المستهلك في المدن.\nالمحولة الرافعة للفولطية: تُستعمل في جهاز التلفاز لتجهيز الفولطية العالية للقاذف الإلكتروني للشاشة، وتُستعمل في محطات توليد الطاقة الكهربائية عند إرسالها للمدن.","ministerial":false},{"type":"قارن","question":"قارن بين المحولة الرافعة والمحولة الخافضة","answer":"","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 رحلة الكهرباء: من المحطة إلى المدينة"},{"chapter_number":8,"chapter_title":"🔆 الفصل الثامن: تكنولوجيا مصادر الطاقة","lesson_number":1,"lesson_title":"🌍 الدرس 1: الطاقة في حياتنا ومصادرها الحالية","order_index":1,"hook":"الكهرباء التي تشحن موبايلك لم تُولَد في القابس! خلفها محطة بعيدة تحرق وقوداً، أو ماءٌ يسقط خلف سد، أو نواة ذرّة تنشطر. هذه هي مصادر الطاقة.","concepts":[],"laws":[],"notes":[{"heading":"","items":["هذه المصادر الثلاثة تُسمّى غير متجددة لأنها تُستنفَد بالاستعمال (سنتعمّق فيها في الدروس القادمة).","في مقابلها توجد الطاقة المتجددة (الشمس، الرياح، الوقود الحيوي، المد والجزر) — وهي موضوع الدروس 5 إلى 8."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما المقصود بالطاقة؟","answer":"الطاقة: هي المقدرة على إنجاز الشغل، وأهم وحداتها هي الجول (Joule).","ministerial":false},{"type":"سؤال","question":"وضّح فائدة الطاقة في حياتنا العملية؟","answer":"الطاقة هي إحدى المقومات الرئيسية للمجتمعات المتحضرة ونحتاج إليها في تسيير حياتنا اليومية، حيث تُستعمل الطاقة في تشغيل كثير من المصانع، وفي تحريك وسائط النقل المختلفة، وفي تشغيل الأدوات المنزلية وغير ذلك من الأغراض.","ministerial":false},{"type":"سؤال","question":"اذكر صور الطاقة؟","answer":"١. الضوء  ٢. الحرارة  ٣. الصوت  ٤. الطاقة الميكانيكية  ٥. الطاقة الكيميائية  ٦. الطاقة النووية  ٧. الطاقة الكيميائية المخزونة في أواصر الذرات والجزيئات.","ministerial":true},{"type":"سؤال","question":"عدّد مصادر الطاقة الحالية في العالم (غير المتجددة)؟","answer":"١. المصادر الأحفورية (النفط _ الفحم _ الغاز الطبيعي).\n٢. مصادر الطاقة المائية.\n٣. مصادر الطاقة النووية.","ministerial":true}],"has_simulation":true,"simulation_title":"🎨 لوحة صور الطاقة — انقر أي صورة"},{"chapter_number":8,"chapter_title":"🔆 الفصل الثامن: تكنولوجيا مصادر الطاقة","lesson_number":2,"lesson_title":"🛢️ الدرس 2: الطاقة الأحفورية","order_index":2,"hook":"كل لتر بنزين تضعه في السيارة كان يوماً بقايا كائنات حية دُفنت وتحوّلت تحت الضغط والحرارة عبر ملايين السنين. لهذا نستهلكها أسرع بكثير مما تتكوّن!","concepts":[],"laws":[],"notes":[{"heading":"","items":["من مصادر الطاقة غير المتجددة هي: الفحم الحجري والنفط والغاز الطبيعي."],"ministerial":true}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما مميزات مصادر الطاقة الأحفورية؟","answer":"١. هي مصادر الطاقة غير المتجددة.\n٢. يشترك في تكوينها عنصرا الهيدروجين والكاربون أي المواد الهيدروكاربونية، بالإضافة إلى نسب مختلفة من الماء والكبريت والأوكسجين والنتروجين وأكاسيد الكاربون.\n٣. احتياطي العالم منها يتناقص بشكل كبير لأن معدل تكوينها أقل من معدل استهلاكها.\n٤. مثل الفحم الحجري والنفط والغاز الطبيعي.","ministerial":true},{"type":"علل","question":"تُعتبر مصادر الطاقة الأحفورية مواد هيدروكربونية؟","answer":"لأنها تتكوّن من عنصرَي الكاربون والهيدروجين، إضافةً إلى نسب مختلفة من الماء والكبريت والأوكسجين والنيتروجين.","ministerial":false},{"type":"علل","question":"تُعدّ مصادر الطاقة الأحفورية من مصادر الطاقة غير المتجددة؟","answer":"لأنها مواد مستهلَكة، ومعدل تكوّنها في الطبيعة أقل بكثير من معدل استهلاكها.","ministerial":false},{"type":"سؤال","question":"ما الفائدة من استعمال الوقود الأحفوري؟ أو ما استعمالات الوقود الأحفوري؟","answer":"١. توليد الكهرباء: حيث تُستعمل الحرارة الناتجة من حرق الوقود في تسخين الماء لإنتاج البخار الذي يُستعمل في تدوير التوربينات الموصّلة للمولدات الكهربائية.\n٢. تشغيل وسائل النقل المختلفة.\n٣. يُستعمل كوقود مباشر لأغراض الطهي والتسخين.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 المحطة الحرارية: من الوقود إلى الكهرباء"},{"chapter_number":8,"chapter_title":"🔆 الفصل الثامن: تكنولوجيا مصادر الطاقة","lesson_number":3,"lesson_title":"💧 الدرس 3: الطاقة المائية","order_index":3,"hook":"سدّ الموصل وسدّ حديثة في العراق لا يخزنان الماء فقط — بل يحوّلان سقوطه إلى كهرباء تُضيء مدناً بأكملها. كيف؟ الجاذبية تفعل معظم العمل!","concepts":[],"laws":[],"notes":[{"heading":"","items":["إنّ الطاقة المتولّدة من حركة أو سقوط المياه تُدعى الطاقة المائية.","مصادر الطاقة المائية تعتمد على تحويل الطاقة الكامنة المختزنة في الماء إلى طاقة ميكانيكية حركية أثناء سقوط الماء."],"ministerial":true}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"وضّح مفهوم مصادر الطاقة المائية؟ أو اذكر مبدأ عمل تكنولوجيا طاقة المياه؟","answer":"تعتمد على أساس تحويل الطاقة المختزنة (طاقة الوضع) في المياه المحفوظة خلف السدود أو الأماكن المرتفعة، وتحويلها إلى طاقة حركية أثناء السقوط؛ حيث يتدفق الماء خلال أنبوب إلى توربين مائي أو هيدروليكي، وعندما يندفع الماء يقوم بتدوير المولدات الكهربائية الكبيرة المرتبطة به فينتج طاقة كهربائية.","ministerial":true},{"type":"سؤال","question":"كيف يتم إنتاج الطاقة الكهربائية باستخدام مصادر الطاقة المائية؟","answer":"أثناء سقوط الماء المحفوظ خلف الأماكن المرتفعة والسدود، يتدفق الماء خلال الأنبوب أو المجرى إلى توربين مائي أو هيدروليكي، وعندما يندفع يقوم بتدوير المولدات الكهربائية المرتبطة به فتنتج الطاقة الكهربائية.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من استخدام تكنولوجيا طاقة المياه؟","answer":"توليد الطاقة الكهربائية، وذلك من خلال تحويل طاقة الوضع المخزونة في المياه إلى طاقة ميكانيكية تعمل على تدوير التوربينات المولّدة للكهرباء.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 السد الكهرومائي: من طاقة الوضع إلى كهرباء"},{"chapter_number":8,"chapter_title":"🔆 الفصل الثامن: تكنولوجيا مصادر الطاقة","lesson_number":4,"lesson_title":"⚛️ الدرس 4: الطاقة النووية","order_index":4,"hook":"نيوترون واحد يضرب نواة يورانيوم-235 فتنشطر وتطلق نيوترونات جديدة تضرب نوىً أخرى... تفاعل متسلسل يُطلق طاقة حرارية جبّارة داخل قلب المفاعل!","concepts":[],"laws":[],"notes":[{"heading":"","items":["الحرارة الناتجة من الانشطار تُستعمل لغلي الماء ← البخار يدير التوربين ← المولد ← كهرباء (المبدأ نفسه في المحطة الحرارية للدرس 2)."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هو الوقود المستعمل في المفاعلات النووية؟","answer":"اليورانيوم 235 (U-235).","ministerial":true},{"type":"سؤال","question":"كيف يمكننا الحصول (إنتاج) على طاقة كهربائية من مصادر الطاقة النووية؟ وضّح ذلك","answer":"تُنتج محطات الطاقة النووية الطاقة الكهربائية بالأسلوب نفسه في المحطات الحرارية (البخارية)، ولكنها تستعمل منظومة تُسمّى بـالمفاعل النووي بدلاً من غرفة احتراق الوقود. ويُعرَّف المفاعل النووي على أنه مصدر إنتاج الطاقة الحرارية الهائلة جداً عن طريق انشطار نوى ذرات عنصر اليورانيوم 235 الذي يُستعمل كوقود نووي للمفاعل، ويُستفاد من الحرارة الناتجة من الانشطار النووي لتحويل الماء إلى بخار، ويدور البخار التوربين الذي يدير مولدات الطاقة فتتولّد الكهرباء.","ministerial":true},{"type":"سؤال","question":"ما المقصود بـ: ١. تخصيب اليورانيوم  ٢. المفاعل النووي؟","answer":"١. تخصيب اليورانيوم: هي عملية فصل اليورانيوم نوع U-235 عن باقي الأنواع لأغراض عملية الانشطار النووي.\n٢. المفاعل النووي: هو منظومة من الأجهزة تُنتج طاقة حرارية هائلة جداً عن طريق الانشطار النووي لذرات العناصر الثقيلة مثل اليورانيوم U-235.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 التفاعل المتسلسل داخل المفاعل"},{"chapter_number":8,"chapter_title":"🔆 الفصل الثامن: تكنولوجيا مصادر الطاقة","lesson_number":5,"lesson_title":"♻️ الدرس 5: الطاقة المتجددة (البديلة)","order_index":5,"hook":"الشمس تشرق كل يوم، والرياح تهبّ، والأمواج تتحرك بلا توقّف... طاقة مجانية، نظيفة، ولا تنفد. هذا هو سرّ الطاقة المتجددة!","concepts":[],"laws":[],"notes":[],"tables":[{"caption":"قارن بين الطاقة الأحفورية (غير المتجددة) والطاقة المتجددة؟","headers":["الطاقة المتجددة ♻️","الطاقة غير المتجددة 🛢️"],"rows":[["لا تُستنفَد","تُستنفَد"],["طاقة نظيفة (غير ملوّثة)","طاقة غير نظيفة (ملوّثة)"],["متاحة محلياً","يمكن أن تكون غير متاحة محلياً"],["تكاليف إنتاجها قليلة","تكاليف إنتاجها عالية"]],"ministerial":false}],"examples":[],"qa":[{"type":"سؤال","question":"ما الأسباب التي جعلت استعمال الطاقة المتجددة يُفضَّل على أنواع الطاقة غير المتجددة؟ أو ما مزاياها؟","answer":"١. إنها طاقة لا تُستنفَد.\n٢. طاقة نظيفة (غير ملوّثة) على عكس أنواع الوقود الأحفوري الذي ينبعث منه عند احتراقه مواد هيدروكربونية تؤثّر في البيئة.\n٣. ممكن أن تكون متاحة محلياً عكس الوقود الأحفوري.\n٤. قلّة تكاليف إنتاج الطاقة منها.","ministerial":false},{"type":"صح/خطأ","question":"«يُفضَّل استعمال الطاقة المتجددة على غير المتجددة لأنها طاقة تُستنفَد» — هل الجملة صحيحة؟","answer":"خاطئة؛ لأن الطاقة المتجددة لا تُستنفَد.","ministerial":true},{"type":"سؤال","question":"عدّد أهم مصادر الطاقة البديلة (الطاقة المتجددة)؟","answer":"١. الطاقة الشمسية (Solar energy)\n٢. طاقة الرياح (Wind energy)\n٣. طاقة الوقود الحيوي (Biofuel energy)\n٤. طاقة المد والجزر (Tidal energy)","ministerial":true}],"has_simulation":true,"simulation_title":"🎯 لعبة: صنّف مصدر الطاقة"},{"chapter_number":8,"chapter_title":"🔆 الفصل الثامن: تكنولوجيا مصادر الطاقة","lesson_number":6,"lesson_title":"☀️ الدرس 6: الطاقة الشمسية","order_index":6,"hook":"لوح صغير على السطح يلتقط ضوء الشمس ويحوّله كهرباء تُشغّل بيتاً كاملاً — بلا وقود، بلا دخان، وبلا فاتورة! كيف تفعل الخلية الشمسية ذلك؟","concepts":[],"laws":[],"notes":[{"heading":"","items":["الطاقة الشمسية: هي الطاقة التي تستقبلها الأرض على سطحها، وتُعدّ مصدر الحياة، وهي المصدر المباشر وغير المباشر لمختلف أنواع الطاقات المتوفرة عليها."],"ministerial":false},{"heading":"","items":["هناك أنواع من السخانات الشمسية تُستعمل فيها المرايا بشكل قطع مكافئ لتركيز الأشعة والحصول على حرارة تسخين أعلى.","تُستثمر الخلايا الشمسية في توليد الطاقة الكهربائية لتشغيل محركات ترفع مياه الآبار."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هي مميزات (مزايا) الطاقة الشمسية؟ / لماذا تُعدّ في طليعة مصادر الطاقة المتجددة؟","answer":"١. تتميّز بسهولة توفّرها في الكثير من بقاع العالم.\n٢. خلوّها من أي تأثيرات سلبية على البيئة، حيث لا تتسبّب في انطلاق غازات أو مواد كيميائية ضارّة بالبيئة أو الإنسان.","ministerial":true},{"type":"سؤال","question":"اذكر استعمالات الطاقة الشمسية؟","answer":"١. تقنية توليد الكهرباء.\n٢. تقنية التطبيقات الحرارية، وهي نوعان: أ- تقنية تحلية المياه المالحة. ب- تقنية تسخين المياه والتدفئة.","ministerial":false},{"type":"سؤال","question":"ما مبدأ عمل الخلية الشمسية؟","answer":"تحوّل طاقة ضوء الشمس إلى طاقة كهربائية.","ministerial":false},{"type":"علل","question":"توضَع طبقة من الزجاج على لوح الخلية الشمسية عند صناعتها؟ ما الفائدة؟","answer":"لحماية الخلية الشمسية من التأثيرات الجوية.","ministerial":false},{"type":"سؤال","question":"ما الاختلاف بين الخلية الجافة والخلية الشمسية؟","answer":"الاختلاف بينهما على أساس مبدأ العمل: فالخلية الجافة تحوّل الطاقة الكيميائية إلى طاقة كهربائية، بينما الخلية الشمسية تحوّل طاقة أشعة الشمس إلى طاقة كهربائية.","ministerial":false},{"type":"سؤال","question":"ما هو السخّان الشمسي؟","answer":"السخّان الشمسي: عبارة عن منظومة متكاملة تُستعمل في تجميع الأشعة الشمسية الساقطة واستثمار طاقتها الحرارية في تسخين المياه وتدفئة البيوت خلال فترة سطوع الشمس.","ministerial":false},{"type":"علل","question":"تُستخدم معادن مطلية باللون الأسود (مثل أكاسيد الكروم والكوبلت) في منظومات السخّان الشمسي؟","answer":"لغرض امتصاص أكبر كمية ممكنة من الأشعة الشمسية، وأن اللون الأسود ماصّ جيّد للأشعة.","ministerial":false},{"type":"سؤال","question":"ما الطرق المستعملة في تحلية المياه بالطاقة الشمسية؟","answer":"١. الطريقة غير المباشرة: تعتمد على توفير الطاقة الكهربائية لتشغيل وحدات التحلية باستعمال الخلايا الشمسية للحصول على طاقة حرارية أو كهربائية أو ميكانيكية.\n٢. الطريقة المباشرة: يُستعمل ضوء الشمس مباشرة لتسخين المياه غير النقية وتحويلها إلى بخار، ثم تحويل البخار إلى ماء نقي باستعمال المقطّر الشمسي.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 الشمس تعمل: خلية شمسية أم سخّان شمسي؟"},{"chapter_number":8,"chapter_title":"🔆 الفصل الثامن: تكنولوجيا مصادر الطاقة","lesson_number":7,"lesson_title":"🌬️ الدرس 7: طاقة الرياح والوقود الحيوي","order_index":7,"hook":"هل تعلم أن سيارة قد تسير على وقود مصنوع من قصب السكر أو فول الصويا؟ وأن مروحةً على تلّة قد تُضيء قرية بأكملها من هبوب الرياح فقط؟","concepts":[],"laws":[],"notes":[{"heading":"","items":["هناك وقود حيوي غازي (غاز الميثان) يمكن الحصول عليه من التحلّل اللاهوائي للمزروعات والفضلات والنفايات وغيرها."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هو مبدأ عمل تقنية الرياح (الطاقة الهوائية)؟","answer":"استثمار قوة الرياح في تدوير المروحة الهوائية، وتتصل المروحة مع مولّد كهربائي فتدور نواة المولّد وتتولّد نتيجةً لذلك الطاقة الكهربائية.","ministerial":true},{"type":"سؤال","question":"على ماذا يعتمد مصدر طاقة الرياح؟","answer":"يعتمد على سرعة الرياح والتي يجب أن تكون بمعدلات لا تقلّ عن 5.4 m/s، وعلى أن يجري هبوبها لساعات طويلة خلال اليوم.","ministerial":true},{"type":"سؤال","question":"أي الأماكن أفضل عند استعمال تقنية الرياح ولماذا؟","answer":"المناطق الساحلية والمناطق الصحراوية، لأن حركة الرياح فيها تكون سريعة.","ministerial":false},{"type":"سؤال","question":"ما المقصود بالوقود الحيوي؟","answer":"الوقود الحيوي: هو الطاقة المستثمَرة في الكائنات الحية سواء كانت نباتية أم حيوانية، وهو أهم مصادر الطاقة المتجددة.","ministerial":false},{"type":"سؤال","question":"الوقود الحيوي السائل يُنتَج بنوعين، اذكرهما؟","answer":"١. وقود الإيثانول السائل. ٢. وقود الديزل الحيوي.","ministerial":true},{"type":"سؤال","question":"ما المقصود بـ (وقود الإيثانول السائل / وقود الديزل الحيوي)؟ أو اذكر طرق إنتاجهما؟","answer":"١. وقود الإيثانول السائل: يُستخرج من قصب السكر والبطاطا الحلوة والذرة والتمر، حيث يُستعمل في مجالات عدّة منها تشغيل بعض السيارات.\n٢. وقود الديزل الحيوي: يُستخرج من النباتات الحاوية على الزيوت مثل فول الصويا وزيت عباد الشمس وغيرها.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 توربين الرياح: هل تكفي سرعة الرياح؟"},{"chapter_number":8,"chapter_title":"🔆 الفصل الثامن: تكنولوجيا مصادر الطاقة","lesson_number":8,"lesson_title":"🌊 الدرس 8: طاقة المد والجزر","order_index":8,"hook":"جاذبية القمر تسحب مياه البحار فترتفع (مدّ) ثم تنخفض (جزر) مرتين كل يوم. لو استثمرنا هذه الحركة العملاقة لأدارت توربينات ضخمة تنير مدناً ساحلية!","concepts":[],"laws":[],"notes":[{"heading":"","items":["فارق منسوب الماء بين المد والجزر + حركة ملايين الأمتار المكعبة = مصدر كبير للطاقة يُدير التوربينات.","تُستعمل المولدات الطافية في البحر لتوليد طاقة المد والجزر كهربائياً."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما المقصود بتكنولوجيا طاقة المد والجزر؟ أو ما مبدأ عملها؟ وكيف تُستثمر في إنتاج الطاقة الكهربائية؟","answer":"هي عملية استثمار حركة المد والجزر في توليد الطاقة الكهربائية. وتقوم الفكرة على أن منسوب الماء يرتفع وقت المد وينخفض وقت الجزر في البحار والمحيطات، وفي ضوء ذلك يُشكّل فارق ارتفاع وانخفاض منسوب المياه وحركته مصدراً كبيراً للطاقة — إذا أخذنا بنظر الاعتبار ملايين الأمتار المكعبة التي تتعرّض لهذه الحركة — حيث يمكن الإفادة منها في تشغيل التوربينات لتوليد الطاقة الكهربائية.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من المولدات الطافية في البحر؟","answer":"وذلك لتوليد طاقة المد والجزر المستثمَرة في توليد الطاقة الكهربائية.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 المد والجزر يديران التوربين"},{"chapter_number":9,"chapter_title":"🛰️ الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة","lesson_number":1,"lesson_title":"🌍 الدرس 1: جو الأرض والغلاف الجوي","order_index":1,"hook":"لولا الغلاف الجوي لتجمّدت الأرض ليلاً واحترقت نهاراً، ولما وُجدت حياة أصلاً! إنه بطانية الأرض ودرعها الواقي في آنٍ واحد.","concepts":[],"laws":[],"notes":[{"heading":"","items":["الغلاف الجوي غير متجانس (طبقات بعضها فوق بعض) لكن نِسب غازاته الرئيسية ثابتة كالهواء الجاف.","الجاذبية الأرضية هي التي تُمسك الغلاف الجوي مرتبطاً بالأرض فلا يهرب إلى الفضاء."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما المقصود بـ: ١- جو الأرض ٢- الغلاف الجوي؟","answer":"١. جو الأرض: هو عبارة تُطلق على غلاف الهواء المحيط بالكرة الأرضية إحاطة تامة.\n٢. الغلاف الجوي: هو عبارة عن طبقة مكوّنة من خليط غير متجانس من الغازات بنسب ثابتة تحيط بالكرة الأرضية مرتبطة بها بفعل الجاذبية الأرضية.","ministerial":false},{"type":"صح/خطأ","question":"«يتألف الغلاف الجوي من خليط من الغازات جميعها متغيّرة النسب». صحيحة أم خاطئة؟","answer":"خاطئة. لأن الغلاف الجوي يتألف من غازات ذات نسب ثابتة مثل الهواء الجاف.","ministerial":false},{"type":"سؤال","question":"اذكر أربعة غازات رئيسية مكوّنة للغلاف الجوي مع النسب المئوية الخاصة بها؟","answer":"١. النتروجين (N₂) بنسبة 78% ٢. الأوكسجين (O₂) بنسبة 20.9%\n٣. أركون (Ar) بنسبة 0.93% ٤. ثنائي أوكسيد الكاربون (CO₂) بنسبة 0.03%","ministerial":true},{"type":"سؤال","question":"عرّف الاحترار العالمي (الاحتباس الحراري)؟","answer":"هي ظاهرة بقاء الحرارة في جو الأرض أكثر من المعدل الطبيعي وعدم تسرّبها إلى خارج الغلاف الجوي، نتيجة امتصاص غاز ثاني أوكسيد الكاربون المنبعث من المصانع والأنشطة المختلفة.","ministerial":false},{"type":"علل","question":"النشاط البشري غير المتوازن يسبّب إفساد الغلاف الجوي؟","answer":"لأن نِسَب مكوّنات الغلاف الجوي الطبيعية تتغيّر عن حالتها الطبيعية، فيؤدي ذلك إلى تولّد احتباس حراري، والذي يسبّب تغيّرات مناخية وفيضانات وانصهار نسب الجليد في القطبين وأعاصير غير مألوفة.","ministerial":false}],"has_simulation":true,"simulation_title":"🎨 تركيب الغلاف الجوي — انقر أي غاز"},{"chapter_number":9,"chapter_title":"🛰️ الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة","lesson_number":2,"lesson_title":"🌡️ الدرس 2: طبقات الغلاف الجوي الخمس","order_index":2,"hook":"لو ركبت صاروخاً من الأرض إلى الفضاء لعبرت خمس طبقات مختلفة، تتغيّر فيها الحرارة صعوداً وهبوطاً بشكل عجيب! تخيّل أن الحرارة تنخفض ثم تصعد ثم تنخفض ثم تصعد من جديد.","concepts":[],"laws":[],"notes":[{"heading":"","items":["ترتيب الطبقات من الأرض للأعلى: التروبوسفير ← الستراتوسفير ← الميزوسفير ← الثرموسفير ← الإكسوسفير.","حيلة للحفظ: «ت س م ث إ» — تروبو، ستراتو، ميزو، ثرمو، إكسو.","سنتعمّق في كل طبقة في الدروس القادمة (3، 4، 5)."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"عدّد طبقات الغلاف الجوي؟","answer":"١. التروبوسفير ٢. الستراتوسفير ٣. الميزوسفير ٤. الثرموسفير ٥. الإكسوسفير\n(مرتّبة من الأقرب إلى سطح الأرض إلى الأبعد نحو الفضاء)","ministerial":true}],"has_simulation":true,"simulation_title":"🛰️ مخطط طبقات الغلاف الجوي — انقر أي طبقة"},{"chapter_number":9,"chapter_title":"🛰️ الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة","lesson_number":3,"lesson_title":"🏔️ الدرس 3: التروبوسفير والستراتوسفير","order_index":3,"hook":"هل لاحظت أن الطائرات تحلّق عالياً جداً؟ إنها تصعد فوق التروبوسفير المضطرب لتطير في بداية الستراتوسفير الهادئ حيث لا عواصف ولا سُحُب!","concepts":[],"laws":[],"notes":[{"heading":"","items":["في التروبوسفير: كلما ارتفعنا قلّت الحرارة والضغط والكثافة.","في الستراتوسفير: كلما ارتفعنا ازدادت الحرارة بسبب امتصاص الأوزون للأشعة فوق البنفسجية.","الطائرات النفّاثة تحلّق قرب حدّ التروبوسفير/الستراتوسفير هرباً من اضطراب الطقس."],"ministerial":false}],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما مميزات طبقة التروبوسفير؟ (تكلّم عن طبقة التروبوسفير)","answer":"١. الطبقة الأولى من الغلاف الجوي القريبة من سطح الأرض.\n٢. يمتد ارتفاعها حوالي 14 كيلومتر.\n٣. ضغطها وكثافتها تتناقص بشكل سريع مع زيادة الارتفاع.\n٤. درجة حرارتها تتناقص بمعدل ثابت 6.5°C الذي يسمى ثابت التناقص.\n٥. تحدث فيها جميع الظواهر المناخية والتغيّرات الجوية وتشكّل 80% من الغلاف الجوي.","ministerial":true},{"type":"سؤال","question":"ما المقصود بـ(ثابت التناقص) في طبقة التروبوسفير؟","answer":"هو معدل تناقص كل من الكثافة والضغط كلما ارتفعنا عن سطح الأرض، حيث تقلّ درجة الحرارة حوالي 6.5°C كلما ارتفعنا كيلومتراً واحداً.","ministerial":true},{"type":"سؤال","question":"ما مميزات طبقة الستراتوسفير؟","answer":"١. هي الطبقة الثانية من الغلاف الجوي القريبة من سطح الأرض.\n٢. يمتد ارتفاعها حوالي من 14 km إلى 50 km.\n٣. ضغطها وكثافتها أقل من الطبقة الأولى.\n٤. درجة حرارتها تزداد مع الارتفاع (من 15°C إلى 50°C).\n٥. تحتوي على طبقة الأوزون.","ministerial":true}],"has_simulation":true,"simulation_title":"🌡️ الحرارة مع الارتفاع — حرّك المنطاد"},{"chapter_number":9,"chapter_title":"🛰️ الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة","lesson_number":4,"lesson_title":"☂️ الدرس 4: طبقة الأوزون","order_index":4,"hook":"الأوزون مثل نظّارة شمسية عملاقة للأرض كلها! يمتص الأشعة فوق البنفسجية الحارقة نوع C قبل أن تصل إلينا. بدونه لأصيب كل كائن حي بحروق وسرطانات.","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"عرّف طبقة الأوزون؟ وفي أي طبقة تتولّد؟ وما فائدتها؟","answer":"هي مظلّة واقية لكل كائن حي على سطح الأرض، إذ تقوم بحجب الإشعاع المؤذي نوع C من الأشعة فوق البنفسجية. ويتولّد الأوزون من الأشعة فوق البنفسجية القادمة من الشمس في طبقة الستراتوسفير، حيث تأتي تلك الأشعة بثلاثة أنواع A, B, C.","ministerial":true},{"type":"علل","question":"تُعدّ طبقة الأوزون مظلّة واقية لكل كائن حي على سطح الأرض؟","answer":"لأنها تقوم بحجب الإشعاع المؤذي نوع C من الأشعة فوق البنفسجية، الذي يُعدّ من أخطر أنواع الأشعة الضارّة بالكائنات الحية.","ministerial":true},{"type":"سؤال","question":"وضّح كيف تتولّد طبقة الأوزون في الجو؟ واذكر المعادلة الكيميائية؟","answer":"إن الأشعة فوق البنفسجية القادمة من الشمس نوع A و B تُمتص من قِبل جزيئات الأوكسجين O₂ الموجودة في الجو، حيث تتفكّك هذه الجزيئة إلى ذرّتين O + O، وبعدها تندمج كل ذرّة مع جزيئة أوكسجين O₂ لتكوّن جزيئة الأوزون O₃، وفق المعادلتين:\nO₂ + UV → O + O\nO + O₂ → O₃","ministerial":false},{"type":"سؤال","question":"ما المقصود بثقب الأوزون؟ أو على ماذا يدلّ مصطلح ثقب الأوزون؟","answer":"ثقب الأوزون: هو مصطلح يدلّ على انخفاض تركيز الأوزون في منطقة معيّنة، كما هو الحال في انخفاض مستوى تركيز الأوزون عند القطبين الجغرافيين.","ministerial":false},{"type":"سؤال","question":"صنّف الأشعة فوق البنفسجية القادمة من الشمس؟","answer":"١. أشعة نوع C: تؤثّر على الأحياء الموجودة على سطح الأرض.\n٢. أشعة نوع B: لها تأثيرات سلبية، إذا تعرّض لها الإنسان لفترة طويلة قد تسبّب سرطان الجلد.\n٣. أشعة نوع A: تتّحد مع B لتكوّن طبقة الأوزون.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 مظلّة الأوزون — جرّب: طبقة سليمة أم فيها ثقب؟"},{"chapter_number":9,"chapter_title":"🛰️ الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة","lesson_number":5,"lesson_title":"🌌 الدرس 5: الميزوسفير والثرموسفير والإكسوسفير","order_index":5,"hook":"«الشهب» التي تراها ليلاً تلمع وتختفي هي أجسام صغيرة تحترق بالاحتكاك عندما تدخل الميزوسفير! وفوقها بمئات الكيلومترات تعكس طبقة الأيونوسفير موجات الراديو لتصل بعيداً.","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما مميزات طبقة الميزوسفير؟","answer":"١. موجودة في منتصف الغلاف الجوي وتمتد من ارتفاع 50 كيلومتراً إلى 90 كيلومتراً.\n٢. مكوّناتها الغازية (الهيليوم والهيدروجين).\n٣. ذات ضغط منخفض وقليلة الكثافة.\n٤. درجة الحرارة تنخفض إلى أقصى ما يمكن، تبلغ حوالي -120°C.","ministerial":true},{"type":"أكمل","question":"الطبقة المحصورة بين 50km و90km في منتصف الغلاف الجوي؟","answer":"تُدعى طبقة الغلاف الجوي الموجودة في منتصف الغلاف الجوي المحصورة بين 50km إلى 90km بطبقة الميزوسفير.","ministerial":true},{"type":"سؤال","question":"ما مميزات طبقة الثرموسفير؟","answer":"١. طبقة ساخنة فوق الميزوسفير تُعرف بالطبقة الحرارية.\n٢. ترتفع من 90 كيلومتراً حتى ارتفاع 500 كيلومتر.\n٣. تسمّى أيضاً بالطبقة المتأيّنة (الأيونوسفير).\n٤. تتّصف بزيادة درجة حرارتها مع الارتفاع عن سطح الأرض وتصل إلى حوالي 1000°C عند الحافة العليا.\n٥. تعكس الموجات الراديوية ذات التردد الأقل من 300 كيلوهرتز.","ministerial":false},{"type":"صح/خطأ","question":"«تمتاز طبقة الثرموسفير بقابليتها على عكس الموجات الراديوية». صحيحة أم خاطئة؟","answer":"صحيحة، لأنها تعكس الموجات ذات التردد الأقل من 300KHZ.","ministerial":false},{"type":"سؤال","question":"ما مميزات طبقة الإكسوسفير؟","answer":"١. أعلى طبقة من طبقات جو الأرض.\n٢. تقع على ارتفاع يزيد على 500 كيلومتر عن سطح الأرض.\n٣. تمثّل الغلاف الغازي الخارجي.\n٤. جزيئات الغاز فيها تتحرّك بسرعة كبيرة جداً، حيث تمتلك طاقة حركية كافية للإفلات من قوة جذب الأرض والهروب إلى الفضاء الخارجي.","ministerial":false},{"type":"أكمل","question":"أعلى طبقات الغلاف الجوي؟","answer":"تُعدّ طبقة الإكسوسفير أعلى طبقات الغلاف الجوي.","ministerial":false}],"has_simulation":true,"simulation_title":"🎬 الطبقات الثلاث العليا — اختر طبقة لتشاهد ظاهرتها"},{"chapter_number":9,"chapter_title":"🛰️ الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة","lesson_number":6,"lesson_title":"📡 الدرس 6: انتشار الموجات اللاسلكية","order_index":6,"hook":"موجة سماوية واحدة قد تسافر آلاف الكيلومترات لأنها ترتدّ عن طبقة الأيونوسفير كما ترتدّ الكرة عن الجدار! أما الموجة الأرضية فتزحف قرب سطح الأرض ولا تصل بعيداً.","concepts":[],"laws":[],"notes":[],"tables":[{"caption":"الفرق بين الموجات الأرضية والسماوية","headers":["ت","الموجات الأرضية","الموجات السماوية"],"rows":[["1","موجات راديوية تنتقل قريبة من سطح الأرض","موجات تنتقل لمسافات بعيدة عن سطح الأرض"],["2","قصيرة المدى","بعيدة المدى"],["3","تنتشر بخطوط مستقيمة","تسلك أنماطاً مختلفة تبعاً لترددها"],["4","تأمين الاتصالات لمسافات قصيرة","تأمين الاتصالات لمسافات بعيدة جداً لقابليتها على الانعكاس عن طبقة الأيونوسفير"],["5","ترددها أقل من 200MHZ","على نوعين: عالية التردد HF وأعلى من HF"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"كيف تنتشر الموجات اللاسلكية في الجو؟ (اذكر أنواع قنوات الاتصال اللاسلكية)","answer":"تنتشر في طريقتين هما: الموجات الأرضية والموجات السماوية.","ministerial":true},{"type":"سؤال","question":"ما الموجات الأرضية؟ وبمَ تمتاز؟","answer":"هي موجات راديوية تنتقل قريبة من سطح الأرض، لذا يُشار إليها بالموجات السطحية. تمتاز:\n١. تنتشر قريبة من سطح الأرض.\n٢. ذات مدى قصير بسبب انتشارها بخطوط مستقيمة.\n٣. ترددها أقل من 200 ميغاهرتز.","ministerial":true},{"type":"علل","question":"الموجات الأرضية غير قادرة على تأمين الاتصالات إلا لمسافات قصيرة المدى؟","answer":"تكون قصيرة المدى بسبب انتشارها بخطوط مستقيمة نتيجة لتحدّب سطح الأرض.","ministerial":true},{"type":"سؤال","question":"علامَ تعتمد قدرة إرسال الموجات الأرضية؟","answer":"١. طبيعة الهوائي. ٢. تردد الموجات الناقلة. ٣. قدرة جهاز الإرسال.","ministerial":false},{"type":"سؤال","question":"ما الموجات السماوية؟ ومميزاتها؟","answer":"هي موجات تُستعمل في الاتصالات بعيدة المدى وتسلك أنماطاً مختلفة تبعاً لترددها:\n١. موجات عالية التردد (HF): تنعكس عن طبقة الأيونوسفير مما يمكّنها من الانتقال خلال مسافة بعيدة لآلاف الكيلومترات.\n٢. موجات ذات تردد أعلى من (HF): هي موجات (ميكروية) تنتقل لمسافات بعيدة، إذ تتمكّن من اختراق طبقة الأيونوسفير وتنفذ إلى الفضاء الخارجي، وتُستعمل في اتصالات الأقمار الصناعية والهواتف النقّالة.","ministerial":true},{"type":"سؤال","question":"ما الفائدة العملية من الموجات الميكروية (ذات التردد الأعلى من HF)؟","answer":"تنتقل لمسافات بعيدة إذ تتمكّن من اختراق طبقة الأيونوسفير وتنفذ إلى الفضاء الخارجي، وتُستعمل في اتصالات الأقمار الصناعية والهواتف النقّالة.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 محاكاة انتشار الموجات — اختر نوع الموجة"},{"chapter_number":9,"chapter_title":"🛰️ الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة","lesson_number":7,"lesson_title":"📱 الدرس 7: الهاتف النقال","order_index":7,"hook":"حين تتكلّم في الهاتف، يتحوّل صوتك إلى إشارة كهربائية ثم إلى موجة لاسلكية يبعثها الهوائي إلى أقرب برج، ومنه تنطلق حول العالم في أجزاء من الثانية!","concepts":[],"laws":[],"notes":[],"tables":[],"examples":[],"qa":[{"type":"سؤال","question":"ما هو الهاتف النقال؟","answer":"هو جهاز من الأجهزة التقنية المعقّدة بسبب تكدّس الدوائر الإلكترونية على مساحة صغيرة، وهو وسيلة اتصال لاسلكية.","ministerial":false},{"type":"سؤال","question":"عدّد المكوّنات الأساسية بالهاتف النقال؟","answer":"١. دائرة إلكترونية تحتوي رقائق المعالج والذاكرة.\n٢. هوائي. ٣. شاشات العرض. ٤. لوحة مفاتيح.\n٥. لاقطات صوت. ٦. السمّاعة. ٧. البطارية.","ministerial":false}],"has_simulation":true,"simulation_title":"🔧 مكوّنات الهاتف النقال — انقر أي مكوّن"},{"chapter_number":9,"chapter_title":"🛰️ الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة","lesson_number":8,"lesson_title":"🛰️ الدرس 8: الأقمار الصناعية","order_index":8,"hook":"حين تشاهد مباراة تُبثّ مباشرة من قارّة أخرى، أو يرشدك تطبيق الخرائط، فأنت تستفيد من قمر صناعي يدور على ارتفاع قد يبلغ 36000 كيلومتراً فوق رأسك!","concepts":[],"laws":[],"notes":[],"tables":[{"caption":"مقارنة الأقمار الصناعية","headers":["الوجه","أقمار الاتصالات","الأقمار العلمية","الأقمار العسكرية"],"rows":[["الغرض","الاتصالات الهاتفية والقنوات الفضائية ونقل المعلومات","مراقبة الطقس والأنواع الجوية والنشاط الشمسي و GPS","مسح وتصوير المواقع العسكرية لغرض التجسّس"],["الارتفاع","عالية جداً بحدود 36000km","متوسطة","واطئة نسبياً"]],"ministerial":true}],"examples":[],"qa":[{"type":"سؤال","question":"ما هو القمر الصناعي؟","answer":"القمر الصناعي: هو تابع يدور حول الأرض، يحمل أجهزة ومعدّات إلكترونية تُستعمل في الاتصالات والأغراض العلمية والعسكرية والاقتصادية وغيرها.","ministerial":false},{"type":"سؤال","question":"اذكر استعمالات الأقمار الصناعية؟ وما الفائدة العملية منها (الغرض)؟","answer":"١. أقمار صناعية للاتصالات: أقمار مخصّصة لأغراض الاتصالات الهاتفية والقنوات الفضائية التلفازية ونقل المعلومات، وتكون على ارتفاعات عالية من سطح الأرض بحدود (36000 km) وهي أعلى من بقية الأقمار.\n٢. أقمار صناعية علمية: الغاية منها مراقبة الطقس والأنواع الجوية والنشاط الشمسي، وأقمار منظومة تحديد المواقع العالمي GPS، وتكون على ارتفاعات متوسطة.\n٣. أقمار صناعية للأغراض العسكرية: تدور في مدارات خاصة بارتفاعات واطئة نسبياً لمسح وتصوير المواقع العسكرية لأغراض التجسّس وغيرها.","ministerial":true}],"has_simulation":true,"simulation_title":"🎬 مدارات الأقمار الصناعية — اختر نوعاً"}];